        'text' => '我叫王小明，今年二十岁，是中国人。我在北京语言大学学习中文。今天在课堂上，我认识了一个新朋友，他叫大卫。大卫是美国人，今年二十一岁。他是我的同学，也在这里学习中文。我很高兴认识他。我们互相问了名字。大卫问我叫什么名字，我告诉他我叫王小明。我也问他是哪国人，他说他是美国人。大卫会说一点儿中文，他的发音很好。老师让我们两个人一组练习对话。我们练习了"你好""我叫""很高兴认识你"这些句子。大卫学得很快，我也帮他纠正发音。下课以后，我们一起在学校附近的咖啡厅喝咖啡，聊了很多。我们说了各自的国家和爱好。大卫喜欢运动和旅行，我喜欢看书和听音乐。我们约定明天还一起上课。学习中文让我认识了很多新朋友，我觉得非常开心。以后我要更加努力地学习中文，认识更多的人。朋友是人生中很重要的财富，我很珍惜每一个朋友。',
