    2 => [
        'title' => 'Bài 2: 谢谢 - Cảm ơn',
        'text' => '今天下午，我去图书馆看书。在图书馆门口，我遇到了我的同学小李。小李是我的好朋友，他常常帮助我。上次他帮我做作业，这次又帮我找书。我对他说："谢谢你的帮助。"小李笑着说："不客气，我们是朋友，互相帮助是应该的。"我们一起进了图书馆。图书馆里很安静，大家都在认真地看书。我找不到我想要的那本中文书，小李帮我一起找。他对我说："你要的书在这里。"我说："谢谢你！"他说："不客气。"后来我不小心碰到旁边一个人的书，书掉在地上，发出很大的声音。我赶紧说："对不起！对不起！"那个人抬起头，笑着说："没关系。"我马上帮他把书捡起来，整理好还给他。他很高兴地对我说："谢谢你。"我说："不客气。"我觉得说"谢谢"和"对不起"是非常重要的礼貌用语。在中国，人们常常说"谢谢"和"对不起"。请进、请坐、请喝茶，这些都是很礼貌的说法。今天小李请我去他家喝茶。我去了他家，他请我坐下，给我倒了一杯中国的绿茶。茶很好喝，我说："谢谢你的茶。"他说："不客气，你慢慢喝。"我们需要学习这些礼貌用语，这样我们才能在社会上交到更多的朋友。礼貌让人开心，也让人与人之间的关系更加融洽。以后我也要做一个有礼貌的人，多说"谢谢"和"对不起"。',
