            ['point' => '请 + Động từ (mời làm gì)', 'explain' => '请 được dùng như một kính ngữ để mời hoặc yêu cầu ai đó làm gì một cách lịch sự. Cấu trúc: 请 + Động từ. Đây là một trong những cách diễn đạt lịch sự phổ biến nhất trong tiếng Trung. Có thể thêm tân ngữ: 请你 + Động từ. Ví dụ: 请坐 (Mời ngồi), 请进 (Mời vào), 请喝茶 (Mời uống trà). Trong giao tiếp hàng ngày, 请 được dùng rất thường xuyên.', 'examples' => ['请进！Mời vào!', '请喝茶。Mời uống trà.', '请坐。Mời ngồi.']],
