    3 => [
        'title' => 'Bài 3: 你叫什么名字 - Tên bạn là gì',
        'text' => '今天汉语课上，老师让我们每个人介绍自己。我们都是学习汉语的学生，来自不同的国家。老师先问大家："你们叫什么名字？"同学们一个一个地回答。第一个同学说："我叫山本，我是日本人。"第二个同学说："我叫安娜，我是法国人。"第三个同学说："我叫大卫，我是美国人。"轮到我的时候，我站起来说："我叫王小明，我是中国人。"老师笑着说："很好。"老师又问我们："你们会说汉语吗？"有的同学会说一点儿，有的同学不会说。大卫会说一点儿汉语，但是说得不太好。安娜不会说汉语，她是刚来的。山本会说一点儿汉语，他学习汉语已经半年了。老师对我们说："不要害怕说错，多说多练习就好了。"我们都点点头。老师还教我们一个新句子："你叫什么名字？"我们两个人一组练习。我和大卫一组。他问我："你叫什么名字？"我说："我叫王小明。"我问他："你叫什么名字？"他说："我叫大卫。"我们练习了很多遍。然后老师又问："你们是哪国人？"我们说："我是中国人""我是美国人""我是日本人""我是法国人"。大家都说得很开心。学习汉语让我们认识了很多新朋友，我们都觉得很高兴。',
        'dialogues' => [
            ['who' => '老师', 'cn' => '同学们好！今天我们来学习怎么问名字。', 'vi' => 'Chào các em! Hôm nay chúng ta học cách hỏi tên.'],
            ['who' => '学生', 'cn' => '老师好！', 'vi' => 'Chào cô giáo!'],
            ['who' => '老师', 'cn' => '你叫什么名字？', 'vi' => 'Em tên là gì?'],
            ['who' => '山本', 'cn' => '我叫山本，我是日本人。', 'vi' => 'Em tên là Yamamoto, em là người Nhật.'],
            ['who' => '老师', 'cn' => '你是哪国人？你会说汉语吗？', 'vi' => 'Em là người nước nào? Em biết nói tiếng Trung không?'],
            ['who' => '安娜', 'cn' => '我是法国人。我会说一点儿汉语。', 'vi' => 'Em là người Pháp. Em biết nói một chút tiếng Trung.'],
            ['who' => '大卫', 'cn' => '我是美国人，我不会说汉语。', 'vi' => 'Em là người Mỹ, em không biết nói tiếng Trung.'],
            ['who' => '老师', 'cn' => '没关系，慢慢学。你们都是好学生。', 'vi' => 'Không sao, từ từ học. Các em đều là học sinh giỏi.'],
            ['who' => '山本', 'cn' => '老师，汉语难吗？', 'vi' => 'Thưa cô, tiếng Trung có khó không ạ?'],
            ['who' => '老师', 'cn' => '汉语不难，只要多听多说就可以学会。', 'vi' => 'Tiếng Trung không khó, chỉ cần nghe nhiều nói nhiều là có thể học được.'],
            ['who' => '安娜', 'cn' => '我会英语，也会法语。', 'vi' => 'Em biết tiếng Anh và tiếng Pháp.'],
            ['who' => '老师', 'cn' => '你们都会说两种语言，很好！', 'vi' => 'Các em đều biết nói hai thứ tiếng, rất tốt!'],
        ],
        'grammar' => [
            ['point' => '哪 + Danh từ (nước nào, người nào)', 'explain' => '哪 là một nghi vấn từ dùng để hỏi về sự lựa chọn, thường được đặt trước danh từ. Cấu trúc phổ biến: 哪 + Danh từ. Ví dụ: 哪国 (nước nào), 哪个人 (người nào), 哪个学校 (trường nào). Lưu ý phân biệt 哪 (nǎ) và 那 (nà, đó/kia). 哪 có thanh 3 và dùng để hỏi, còn 那 có thanh 4 và dùng để chỉ định.', 'examples' => ['你是哪国人？Bạn là người nước nào?', '你是哪个学校的学生？Bạn là sinh viên trường nào?', '哪本书是你的？Quyển sách nào là của bạn?']],
            ['point' => '都 (đều, tất cả)', 'explain' => '都 là phó từ chỉ sự bao gồm tất cả các đối tượng, có nghĩa là "đều" hoặc "cả". 都 luôn đứng trước động từ hoặc tính từ, không đứng ở cuối câu. Khi chủ ngữ là số nhiều, thường dùng 都 để nhấn mạnh tất cả các thành viên. Phủ định của 都 là 都不 (đều không). Ví dụ: 我们都是学生 (Chúng tôi đều là sinh viên).', 'examples' => ['我们都是同学。Chúng tôi đều là bạn cùng lớp.', '他们都说汉语。Họ đều nói tiếng Trung.', '我都不认识。Tôi đều không quen.']],
            ['point' => '会 + Động từ (biết làm gì đó)', 'explain' => '会 được dùng để diễn tả khả năng làm một việc gì đó nhờ đã học hoặc đã biết. Cấu trúc: Chủ ngữ + 会 + Động từ. Phủ định: 不会 (không biết làm). Câu hỏi: 会...吗? 会 khác với 能 ở chỗ 会 chỉ khả năng có được do học tập, còn 能 chỉ khả năng do điều kiện cho phép. Ví dụ: 我会游泳 (Tôi biết bơi — đã học).', 'examples' => ['我会说汉语。Tôi biết nói tiếng Trung.', '他不会英文。Anh ấy không biết tiếng Anh.', '你会写汉字吗？Bạn biết viết chữ Hán không?']],
        ],
