    4 => [
        'title' => 'Bài 4: 她是我的汉语老师 - Cô ấy là giáo viên tiếng Trung của tôi',
        'text' => '我的汉语老师姓张，我们都叫她张老师。张老师今年三十岁，是北京人。她教我们汉语，教得非常好。张老师的课很有意思，我们都喜欢上她的课。今天张老师让我们介绍自己的家人。我第一个站起来说："我家有四口人，爸爸、妈妈、我和妹妹。我爸爸是医生，在医院工作。我妈妈是老师，在大学教英文。我妹妹是学生，她今年十五岁，在中学学习。我还有一个哥哥，他已经工作了，他是律师。"张老师听了以后点点头，然后问大家："你们家里有几口人？"大卫说："我家有五口人，爸爸、妈妈、两个哥哥和我。我爸爸是工程师，我妈妈是护士。"安娜说："我家有三口人，爸爸、妈妈和我。我爸爸是律师，我妈妈是记者。"山本说："我家有四口人，爸爸、妈妈、弟弟和我。我爸爸是公司职员，我妈妈是家庭主妇。"张老师笑着说："大家的家庭都不一样，但是都很幸福。家是很重要的地方，我们要爱自己的家人。"张老师还教我们怎么用"的"来表示所属关系。她说："我的老师""他的书""妈妈的手机"这些短语中，"的"表示前面的词语属于后面的东西。我们按照张老师教的句子练习了很多遍。',
        'dialogues' => [
            ['who' => '张老师', 'cn' => '请大家介绍自己的家人。你家里有几口人？', 'vi' => 'Xin mời các em giới thiệu về gia đình mình. Nhà em có mấy người?'],
            ['who' => '王小明', 'cn' => '我家有四口人，爸爸、妈妈、妹妹和我。', 'vi' => 'Nhà em có bốn người, bố, mẹ, em gái và em.'],
            ['who' => '张老师', 'cn' => '你爸爸做什么工作？', 'vi' => 'Bố em làm công việc gì?'],
            ['who' => '王小明', 'cn' => '我爸爸是医生，我妈妈是老师。', 'vi' => 'Bố em là bác sĩ, mẹ em là giáo viên.'],
            ['who' => '张老师', 'cn' => '这是谁的手机？', 'vi' => 'Đây là điện thoại của ai?'],
            ['who' => '大卫', 'cn' => '这是张老师的手机。', 'vi' => 'Đây là điện thoại của cô Trương.'],
            ['who' => '张老师', 'cn' => '那本书是谁的？', 'vi' => 'Quyển sách kia là của ai?'],
            ['who' => '安娜', 'cn' => '那是王小明的书。', 'vi' => 'Đó là sách của Vương Tiểu Minh.'],
            ['who' => '张老师', 'cn' => '你有哥哥或姐姐吗？', 'vi' => 'Em có anh trai hoặc chị gái không?'],
            ['who' => '大卫', 'cn' => '我有两个哥哥，没有姐姐。', 'vi' => 'Em có hai anh trai, không có chị gái.'],
            ['who' => '张老师', 'cn' => '你家人都喜欢你学习中文吗？', 'vi' => 'Gia đình em đều thích em học tiếng Trung phải không?'],
            ['who' => '安娜', 'cn' => '是的，他们都很支持我。', 'vi' => 'Vâng, họ đều rất ủng hộ em.'],
        ],
        'grammar' => [
            ['point' => 'Trợ từ sở hữu 的 (của)', 'explain' => '的 là trợ từ quan trọng nhất trong tiếng Trung, dùng để chỉ mối quan hệ sở hữu hoặc mô tả. Cấu trúc: Danh từ / Đại từ + 的 + Danh từ. Ví dụ: 我的书 (sách của tôi), 妈妈的手机 (điện thoại của mẹ). Khi danh từ được sở hữu đã rõ ngữ cảnh, có thể lược bỏ: 这是谁的？— 我的 (Của ai đây? — Của tôi). 的 cũng được dùng trong các cụm mô tả: 很大的学校 (ngôi trường rất lớn).', 'examples' => ['我的书。Sách của tôi.', '这是老师的手机。Đây là điện thoại của cô giáo.', '妈妈的包。Túi của mẹ.']],
            ['point' => 'Có với 有 (chỉ sự sở hữu)', 'explain' => '有 là động từ chỉ sự sở hữu hoặc tồn tại, nghĩa là "có". Cấu trúc: Chủ ngữ + 有 + Tân ngữ. Phủ định: 没有 (không có). Câu hỏi dùng 吗: 你有...吗? 有 có thể chỉ sở hữu vật chất (我有书) hoặc quan hệ gia đình (我有一个哥哥). Không giống tiếng Anh, 有 không thay đổi hình thức theo chủ ngữ hay thì.', 'examples' => ['我家有三口人。Nhà tôi có ba người.', '我有一个哥哥。Tôi có một anh trai.', '他没有中文书。Anh ấy không có sách tiếng Trung.']],
            ['point' => 'Cấu trúc "A + 的 + B" (A là của B)', 'explain' => 'Khi muốn nói B thuộc về A, dùng cấu trúc A + 的 + B. Đây là cấu trúc cơ bản và rất quan trọng trong tiếng Trung. A có thể là đại từ nhân xưng (我, 你, 他), danh từ chỉ người (妈妈, 老师), hoặc danh từ chỉ nơi chốn. Khi A và B có mối quan hệ mật thiết như gia đình, tổ chức, có thể lược bỏ 的: 我妈妈 (mẹ tôi) thay vì 我的妈妈. Tuy nhiên, với đa số trường hợp, 的 là bắt buộc.', 'examples' => ['我的汉语老师。Giáo viên tiếng Trung của tôi.', '妈妈的手机。Điện thoại của mẹ.', '中国的城市。Các thành phố của Trung Quốc.']],
        ],
        'pronunciation' => ['focus' => 'an/ang/en/eng', 'drill' => ['bān', 'bāng', 'pán', 'páng', 'mén', 'méng', 'fán', 'fáng']],
        'vocab' => [
            ['w' => '家', 'p' => 'jiā', 'm' => 'nhà, gia đình', 'pos' => '名词', 'ex' => ['我家有四口人。Nhà tôi có bốn người.', '我爱我家。Tôi yêu gia đình tôi.']],
            ['w' => '爸爸', 'p' => 'bàba', 'm' => 'bố, ba', 'pos' => '名词', 'ex' => ['我爸爸是医生。Bố tôi là bác sĩ.', '爸爸很忙。Bố rất bận.']],
            ['w' => '妈妈', 'p' => 'māma', 'm' => 'mẹ, má', 'pos' => '名词', 'ex' => ['我妈妈是老师。Mẹ tôi là giáo viên.', '妈妈做的饭很好吃。Cơm mẹ nấu rất ngon.']],
            ['w' => '哥哥', 'p' => 'gēge', 'm' => 'anh trai', 'pos' => '名词', 'ex' => ['我有一个哥哥。Tôi có một anh trai.', '哥哥很高。Anh trai rất cao.']],
            ['w' => '姐姐', 'p' => 'jiějie', 'm' => 'chị gái', 'pos' => '名词', 'ex' => ['姐姐是学生。Chị gái là sinh viên.', '我姐姐很漂亮。Chị gái tôi rất đẹp.']],
            ['w' => '弟弟', 'p' => 'dìdi', 'm' => 'em trai', 'pos' => '名词', 'ex' => ['我弟弟十岁。Em trai tôi mười tuổi.', '弟弟喜欢运动。Em trai thích thể thao.']],
            ['w' => '妹妹', 'p' => 'mèimei', 'm' => 'em gái', 'pos' => '名词', 'ex' => ['我妹妹很可爱。Em gái tôi rất dễ thương.', '妹妹在中学学习。Em gái học ở trường trung học.']],
            ['w' => '医生', 'p' => 'yīshēng', 'm' => 'bác sĩ', 'pos' => '名词', 'ex' => ['医生在医院工作。Bác sĩ làm việc ở bệnh viện.', '他是好医生。Anh ấy là bác sĩ giỏi.']],
            ['w' => '工作', 'p' => 'gōngzuò', 'm' => 'công việc, làm việc', 'pos' => '动词, 名词', 'ex' => ['他在大学工作。Anh ấy làm việc ở trường đại học.', '他的工作很有意思。Công việc của anh ấy rất thú vị.']],
            ['w' => '大学', 'p' => 'dàxué', 'm' => 'đại học', 'pos' => '名词', 'ex' => ['我在大学学习。Tôi học ở trường đại học.', '北京大学很有名。Đại học Bắc Kinh rất nổi tiếng.']],
            ['w' => '学校', 'p' => 'xuéxiào', 'm' => 'trường học', 'pos' => '名词', 'ex' => ['学校很大。Trường học rất lớn.', '我们学校有很多学生。Trường chúng tôi có nhiều sinh viên.']],
            ['w' => '律师', 'p' => 'lǜshī', 'm' => 'luật sư', 'pos' => '名词', 'ex' => ['他是律师。Anh ấy là luật sư.', '律师的工作很忙。Công việc của luật sư rất bận.']],
            ['w' => '工程师', 'p' => 'gōngchéngshī', 'm' => 'kỹ sư', 'pos' => '名词', 'ex' => ['爸爸是工程师。Bố là kỹ sư.', '工程师的工作很重要。Công việc của kỹ sư rất quan trọng.']],
