    5 => [
        'title' => 'Bài 5: 今天几号 - Hôm nay ngày mấy',
        'text' => '今天是我好朋友大卫的生日。早上我一起床就看了看日历，今天九月十五号，星期五。大卫的生日是九月十五号，所以今天是他的生日。我准备给他一个惊喜。我去商店买了一个生日蛋糕和一个礼物。蛋糕很漂亮，上面写着"生日快乐"四个字。然后我给大卫打了一个电话。我说："大卫，今天几号？"大卫说："今天九月十五号。"我说："你知道今天是什么日子吗？"大卫说："今天星期五啊。"我笑着说："今天也是你的生日！生日快乐！"大卫很惊讶，他说："啊，我忘了！谢谢你记得！"晚上我们约了几个朋友一起吃饭。我们在一家中餐厅吃饭，点了很多菜。吃完饭以后，我拿出蛋糕，大家一起唱生日歌。大卫很感动，他说："谢谢大家！今天我很开心。"我们一起吃蛋糕，聊天，玩游戏。大卫问我："你生日是几月几号？"我说："我的生日是三月二十号。"大卫说："好的，到时候我也给你过生日。"我们一直玩到晚上十点才回家。今天真是一个快乐的日子。每年的九月十五号我都会记得是大卫的生日。朋友之间的关心和祝福让生活更加美好。',
        'dialogues' => [
            ['who' => 'A', 'cn' => '今天几月几号？', 'vi' => 'Hôm nay tháng mấy ngày mấy?'],
            ['who' => 'B', 'cn' => '今天九月十五号。', 'vi' => 'Hôm nay ngày mười lăm tháng chín.'],
            ['who' => 'A', 'cn' => '今天星期几？', 'vi' => 'Hôm nay thứ mấy?'],
            ['who' => 'B', 'cn' => '今天星期五。', 'vi' => 'Hôm nay thứ sáu.'],
            ['who' => 'A', 'cn' => '你生日是几月几号？', 'vi' => 'Sinh nhật bạn là ngày mấy tháng mấy?'],
            ['who' => 'B', 'cn' => '我的生日是三月二十号。', 'vi' => 'Sinh nhật tôi là ngày hai mươi tháng ba.'],
            ['who' => 'A', 'cn' => '你今年多大？', 'vi' => 'Năm nay bạn bao nhiêu tuổi?'],
            ['who' => 'B', 'cn' => '我今年二十岁。', 'vi' => 'Năm nay tôi hai mươi tuổi.'],
            ['who' => 'A', 'cn' => '现在几点？', 'vi' => 'Bây giờ là mấy giờ?'],
            ['who' => 'B', 'cn' => '现在晚上八点。', 'vi' => 'Bây giờ là tám giờ tối.'],
            ['who' => 'A', 'cn' => '生日快乐！这是给你的礼物。', 'vi' => 'Chúc mừng sinh nhật! Đây là quà cho bạn.'],
            ['who' => 'B', 'cn' => '谢谢你！你太好了！', 'vi' => 'Cảm ơn bạn! Bạn thật tốt!'],
        ],
        'grammar' => [
            ['point' => 'Từ chỉ thời gian làm chủ ngữ', 'explain' => 'Trong tiếng Trung, từ chỉ thời gian (今天, 明天, 现在, v.v.) có thể làm chủ ngữ trong câu, đặc biệt là trong các câu miêu tả về thời gian hoặc sự kiện. Cấu trúc: Thời gian + Động từ / Tính từ. Thời gian luôn đặt ở đầu câu hoặc trước động từ. Không giống tiếng Việt, trật tự thời gian trong tiếng Trung từ lớn đến nhỏ: năm → tháng → ngày → giờ. Ví dụ: 2024年9月15号 (ngày 15 tháng 9 năm 2024).', 'examples' => ['今天九月十五号。Hôm nay ngày mười lăm tháng chín.', '明天是星期一。Ngày mai là thứ hai.', '现在八点。Bây giờ là tám giờ.']],
            ['point' => 'Câu hỏi với 几 (mấy)', 'explain' => '几 được dùng để hỏi về số lượng nhỏ (thường dưới 10) hoặc hỏi về số thứ tự, ngày tháng. Cấu trúc: 几 + Danh từ / Lượng từ. Ví dụ: 几号 (ngày mấy), 几点 (mấy giờ), 几个 (mấy cái). Khi hỏi tuổi dùng 几岁 (mấy tuổi) cho trẻ em hoặc 多大 (bao nhiêu tuổi) cho người lớn. 几 khác với 多少: 几 dùng cho số nhỏ, 多少 dùng cho số lớn và không giới hạn.', 'examples' => ['今天几号？Hôm nay ngày mấy?', '现在几点？Bây giờ mấy giờ?', '你几岁？Bạn mấy tuổi?']],
            ['point' => 'Trật tự từ trong câu chỉ thời gian', 'explain' => 'Trong tiếng Trung, khi có nhiều từ chỉ thời gian, trật tự luôn từ lớn đến nhỏ: Năm → Tháng → Ngày → Giờ → Phút. Đây là quy tắc quan trọng khác với tiếng Việt và tiếng Anh. Ví dụ: 2024年9月15号下午三点 (3 giờ chiều ngày 15 tháng 9 năm 2024). Các từ chỉ thời gian thường đứng trước động từ chính trong câu. Khi muốn nhấn mạnh thời gian, có thể đặt ở đầu câu.', 'examples' => ['我九月十五号生日。Sinh nhật tôi ngày mười lăm tháng chín.', '他每天早上八点上课。Anh ấy học lúc tám giờ mỗi sáng.', '我们星期五晚上见面。Chúng tôi gặp nhau tối thứ sáu.']],
        ],
        'pronunciation' => ['focus' => 'tone pairs 3-3', 'drill' => ['nǐ hǎo', 'hěn hǎo', 'lǎo shī', 'kě yǐ', 'yǔ fǎ', 'yǒng gǎn', 'jiǎn dān', 'yǐng xiǎng']],
