    6 => [
        'title' => 'Bài 6: 我会说汉语 - Tôi biết nói tiếng Trung',
        'text' => '我叫安娜，我是法国人。我学习汉语已经半年了。现在我可以说一些简单的汉语。我会说"你好""谢谢""对不起"这些日常用语，也会用汉语问问题和回答问题。今天老师让我们用汉语做自我介绍。我站在前面，用汉语说："大家好，我叫安娜，我是法国人。我会说法语和英语，也会说一点儿汉语。我很喜欢学习汉语，汉语很有意思。"老师听了以后很高兴，说："安娜说得很不错！"我的同学大卫是美国人，他也会说一些汉语，但是说得不太好。他常常把声调说错。比如他把"你好"说成"nǐ hào"，把"谢谢"说成"xiè xiè"。老师帮他纠正了很多次。大卫有点儿着急，老师说："不要着急，慢慢来，多练习就好了。"老师教我们要多听、多说、多读、多写。她还说学习语言没有捷径，只有努力才能学好。我每天早上都会听中文录音，跟着读。晚上我会写汉字，每个字写五遍。虽然很辛苦，但是看到自己的进步，我很开心。现在我能用汉语和中国人聊天了。上周末我在商店里遇到一个中国人，我用汉语问他："你好，这个多少钱？"他听懂了，还夸我说得好。我真的很开心！以后我还要继续努力学习，希望有一天能说一口流利的中文。',
        'dialogues' => [
            ['who' => '老师', 'cn' => '安娜，你用汉语介绍一下自己吧。', 'vi' => 'Anna, em hãy tự giới thiệu bằng tiếng Trung đi.'],
            ['who' => '安娜', 'cn' => '大家好，我叫安娜，我是法国人。我会说法语和英语。', 'vi' => 'Xin chào mọi người, tôi tên là Anna, tôi là người Pháp. Tôi biết nói tiếng Pháp và tiếng Anh.'],
            ['who' => '老师', 'cn' => '你会说汉语吗？', 'vi' => 'Em biết nói tiếng Trung không?'],
            ['who' => '安娜', 'cn' => '我会说一点儿汉语。我正在学习。', 'vi' => 'Em biết nói một chút tiếng Trung. Em đang học.'],
            ['who' => '老师', 'cn' => '你说得很好！大卫，你呢？', 'vi' => 'Em nói rất tốt! David, còn em?'],
            ['who' => '大卫', 'cn' => '我...我会说一点点。但是我说得不好。', 'vi' => 'Em... em biết nói một chút. Nhưng em nói không tốt.'],
            ['who' => '老师', 'cn' => '没关系，你再说一遍给我听听。', 'vi' => 'Không sao, em nói lại lần nữa cho cô nghe.'],
            ['who' => '大卫', 'cn' => '你好，我叫大卫，我是美国人。', 'vi' => 'Xin chào, tôi tên David, tôi là người Mỹ.'],
            ['who' => '老师', 'cn' => '你的声调有问题。跟我读：nǐ hǎo。', 'vi' => 'Thanh điệu của em có vấn đề. Đọc theo cô: nǐ hǎo.'],
            ['who' => '大卫', 'cn' => 'nǐ hǎo。', 'vi' => 'nǐ hǎo.'],
            ['who' => '老师', 'cn' => '对！这次好多了。你还能说什么？', 'vi' => 'Đúng! Lần này tốt hơn nhiều. Em còn có thể nói gì?'],
            ['who' => '大卫', 'cn' => '我能用汉语买东西了。', 'vi' => 'Em có thể dùng tiếng Trung mua đồ rồi.'],
            ['who' => '老师', 'cn' => '很好！能学以致用是最棒的。', 'vi' => 'Rất tốt! Có thể học và dùng được là tuyệt nhất.'],
        ],
        'grammar' => [
            ['point' => '会 (biết) cho khả năng học được', 'explain' => '会 được dùng để diễn tả khả năng làm việc gì đó nhờ đã học tập hoặc rèn luyện. Cấu trúc: Chủ ngữ + 会 + Động từ. Ví dụ: 我会说汉语 (Tôi biết nói tiếng Trung — đã học). 他会游泳 (Anh ấy biết bơi — đã học). Phủ định: 不会 (không biết). Câu hỏi: 会...吗? 会 chỉ khả năng có được thông qua học tập, khác với 能 chỉ khả năng do điều kiện cho phép. Khi muốn nói "biết làm gì đó" đã học qua, luôn dùng 会.', 'examples' => ['我会说汉语。Tôi biết nói tiếng Trung.', '他不会写汉字。Anh ấy không biết viết chữ Hán.', '你会做中国菜吗？Bạn biết làm món Trung Quốc không?']],
            ['point' => '能 (có thể) cho khả năng do điều kiện', 'explain' => '能 diễn tả khả năng làm việc gì đó do điều kiện cho phép, hoặc được phép làm gì. Cấu trúc: Chủ ngữ + 能 + Động từ. 能 khác với 会 ở chỗ: 能 chỉ khả năng do hoàn cảnh, điều kiện bên ngoài cho phép, còn 会 chỉ kỹ năng đã học được. Ví dụ: 我能去 (Tôi có thể đi — vì không có rào cản). 我会去吗? (Tôi có biết đi không? Sai — phải dùng 能 cho tình huống). Trong một số ngữ cảnh, 能 và 会 có thể thay thế nhau, nhưng về cơ bản chúng khác nhau.', 'examples' => ['我能用汉语买东西。Tôi có thể dùng tiếng Trung mua đồ.', '今天我不能去。Hôm nay tôi không thể đi.', '你能帮我吗？Bạn có thể giúp tôi không?']],
            ['point' => '一点儿 (một chút)', 'explain' => '一点儿 được dùng để chỉ một số lượng nhỏ hoặc một mức độ thấp. Cấu trúc: Động từ + 一点儿 hoặc 一点儿 + Danh từ. Ví dụ: 说一点儿 (nói một chút), 一点儿水 (một chút nước). 一点儿 thường được dùng sau động từ chỉ hành động hoặc trước danh từ. Trong câu phủ định, 一点儿 có thể đứng trước tính từ để nhấn mạnh: 一点儿都不好 (không tốt chút nào). Lưu ý: 一点儿 có thể rút gọn thành 点儿 trong khẩu ngữ.', 'examples' => ['我会说一点儿汉语。Tôi biết nói một chút tiếng Trung.', '请给我一点儿水。Xin cho tôi một chút nước.', '我一点儿都不累。Tôi không mệt chút nào.']],
        ],
        'pronunciation' => ['focus' => 'tone pairs 3-4', 'drill' => ['nǚ rén', 'lǚ xíng', 'hǎo kàn', 'lǎo shì', 'kě pà', 'yǒu qù', 'gǎn xiè', 'mǎi mài']],
