    7 => [
        'title' => 'Bài 7: 你吃什么 - Bạn ăn gì',
        'text' => '今天中午，我和大卫一起去学校附近的餐厅吃饭。我们走进一家中国餐厅，里面的人很多。服务员走过来问我们："你们想吃点什么？"我对大卫说："你想吃什么？今天我请客。"大卫看了看菜单，说："我想吃米饭和鱼香肉丝。你呢？"我说："我喜欢吃面条，我要一碗牛肉面。"大卫问我："你喝什么？"我说："我喝一杯茶。"大卫说："我要一瓶可乐。"服务员记下了我们点的菜。等了一会儿，菜就上来了。大卫尝了一口鱼香肉丝，说："很好吃！中国菜真好吃！"我说："是啊，中国菜有很多种，以后我们可以多尝尝。"大卫问我："你会做中国菜吗？"我说："我不会做，但是我妈妈会做。她做的菜特别好吃。"大卫说："什么时候我可以去你家尝尝你妈妈做的菜？"我说："好啊，欢迎你去！"我们一边吃一边聊天。大卫说他很喜欢吃中国菜，特别是北京烤鸭和火锅。我说我也很喜欢吃，下次我们一起去吃火锅。吃完饭以后，我付了钱。这顿饭一共五十块钱，不贵，很好吃。我们都很开心。',
