        'grammar' => [
            ['point' => 'Động từ 要 (muốn)', 'explain' => '要 là động từ chỉ sự muốn hoặc cần một thứ gì đó. Cấu trúc: Chủ ngữ + 要 + Tân ngữ (danh từ/động từ). Ví dụ: 我要一碗面 (Tôi muốn một tô mì). 我要吃饭 (Tôi muốn ăn cơm). Phủ định thường dùng 不想 (không muốn) thay vì 不要, vì 不要 mang nghĩa "đừng" hoặc "không được". Khi đi mua đồ hoặc gọi món, 要 rất thông dụng. Câu hỏi: 你要...吗? hoặc 你想...吗?', 'examples' => ['我要一碗面条。Tôi muốn một tô mì.', '你想吃什么？Bạn muốn ăn gì?', '我不要咖啡，我要茶。Tôi không muốn cà phê, tôi muốn trà.']],
            ['point' => '喜欢 + Danh từ / Động từ (thích)', 'explain' => '喜欢 là động từ chỉ sự yêu thích, có thể đi với danh từ hoặc động từ. Cấu trúc: 喜欢 + Danh từ (thích cái gì) hoặc 喜欢 + Động từ (thích làm gì). Ví dụ: 我喜欢中国菜 (Tôi thích món Trung Quốc). 我喜欢看书 (Tôi thích đọc sách). Phủ định: 不喜欢 (không thích). 喜欢 khác với 爱: 爱 mạnh hơn và thường dùng cho người hoặc đam mê lớn. Để hỏi sở thích, dùng: 你喜欢什么？', 'examples' => ['我喜欢吃中国菜。Tôi thích ăn món Trung Quốc.', '你喜欢做什么？Bạn thích làm gì?', '我不喜欢喝咖啡。Tôi không thích uống cà phê.']],
            ['point' => '再 + Động từ (lại, thêm)', 'explain' => '再 là phó từ chỉ sự lặp lại hoặc thực hiện thêm một hành động trong tương lai. Cấu trúc: 再 + Động từ. 再 thường dùng cho hành động chưa xảy ra, muốn làm thêm hoặc làm lại. Ví dụ: 再吃一碗 (ăn thêm một bát). 再说一遍 (nói lại một lần nữa). Lưu ý: 再 chỉ hành động trong tương lai, còn 又 chỉ hành động đã xảy ra trong quá khứ. Phân biệt: 再吃 (sẽ ăn thêm) vs 又吃了 (đã ăn thêm).', 'examples' => ['我再吃一碗。Tôi ăn thêm một bát.', '请再说一遍。Xin hãy nói lại một lần.', '下次再来。Lần sau lại đến.']],
