    8 => [
        'title' => 'Bài 8: 多少钱 - Bao nhiêu tiền',
        'text' => '今天是星期天，天气很好。我和妈妈一起去市场买东西。市场里很热闹，有很多卖东西的人，也有很多买东西的人。我们先去水果摊买水果。卖水果的阿姨对我们说："你们好！想买什么水果？"妈妈问："苹果多少钱一斤？"阿姨说："苹果五块钱一斤。"妈妈又说："这个多少钱？"她指的是橘子。阿姨说："橘子三块五一斤。"妈妈买了三斤苹果和两斤橘子。然后我们去服装店买衣服。妈妈看中了一件红色的上衣，问："这件衣服多少钱？"店员说："这件衣服一百二十块。"妈妈说："太贵了，能便宜一点儿吗？"店员说："那给您便宜十块，一百一十块。"妈妈还是觉得贵。店员又说："这件衣服质量很好，这个价格已经很便宜了。"最后妈妈花了一百一十块买了那件衣服。我看中了一双蓝色的运动鞋。我问："这双鞋多少钱？"店员说："这双鞋二百块。"妈妈觉得太贵了，不想买。但我说我真的很喜欢，妈妈就帮我买了。今天一共花了很多钱，但是买到了喜欢的东西，我们都很高兴。在回家的路上，妈妈对我说："以后买东西要看好价格，不要乱花钱。"我点点头。',
        'dialogues' => [
            ['who' => '阿姨', 'cn' => '你好！想买什么水果？', 'vi' => 'Xin chào! Muốn mua trái cây gì?'],
            ['who' => '妈妈', 'cn' => '苹果多少钱一斤？', 'vi' => 'Táo bao nhiêu tiền một cân?'],
            ['who' => '阿姨', 'cn' => '苹果五块钱一斤。', 'vi' => 'Táo năm tệ một cân.'],
            ['who' => '妈妈', 'cn' => '太贵了，便宜一点儿吧。', 'vi' => 'Đắt quá, rẻ một chút đi.'],
            ['who' => '阿姨', 'cn' => '那四块五一斤，您要多少？', 'vi' => 'Vậy bốn tệ rưỡi một cân, cô muốn mua bao nhiêu?'],
            ['who' => '妈妈', 'cn' => '我要三斤。', 'vi' => 'Tôi muốn ba cân.'],
            ['who' => '店员', 'cn' => '这件衣服很漂亮，您要试试吗？', 'vi' => 'Cái áo này rất đẹp, cô muốn thử không?'],
            ['who' => '妈妈', 'cn' => '这件多少钱？', 'vi' => 'Cái này bao nhiêu tiền?'],
            ['who' => '店员', 'cn' => '这件一百二十块。', 'vi' => 'Cái này một trăm hai mươi tệ.'],
            ['who' => '妈妈', 'cn' => '太贵了，能便宜一点儿吗？', 'vi' => 'Đắt quá, có thể rẻ hơn một chút không?'],
            ['who' => '店员', 'cn' => '那就一百一十块吧。', 'vi' => 'Vậy thì một trăm mười tệ nhé.'],
            ['who' => '王小明', 'cn' => '这双鞋多少钱？', 'vi' => 'Đôi giày này bao nhiêu tiền?'],
            ['who' => '店员', 'cn' => '这双鞋二百块，是今年的新款。', 'vi' => 'Đôi giày này hai trăm tệ, là hàng mới của năm nay.'],
        ],
        'grammar' => [
            ['point' => '多少 (bao nhiêu) vs 几 (mấy)', 'explain' => 'Cả 多少 và 几 đều là từ hỏi về số lượng, nhưng khác nhau về phạm vi sử dụng. 几 dùng khi hỏi số lượng nhỏ (thường dưới 10) và phải đi kèm với lượng từ: 几本书 (mấy quyển sách), 几天 (mấy ngày). 多少 có thể dùng cho mọi số lượng và không nhất thiết phải có lượng từ: 多少人 (bao nhiêu người), 多少钱 (bao nhiêu tiền). 多少 thường dùng khi hỏi giá tiền, số điện thoại, số lượng lớn. Trong khẩu ngữ, 多少 có thể dùng thay cho 几 trong nhiều trường hợp.', 'examples' => ['这个多少钱？Cái này bao nhiêu tiền?', '你有几本书？Bạn có mấy quyển sách?', '多少人都可以。Bao nhiêu người cũng được.']],
            ['point' => 'Lượng từ (Measure Words)', 'explain' => 'Trong tiếng Trung, khi đếm danh từ phải dùng lượng từ. Cấu trúc: Số + Lượng từ + Danh từ. Các lượng từ phổ biến: 个 (cái, người — dùng chung), 块 (đồng tiền), 斤 (cân), 件 (cái, chiếc — cho quần áo), 双 (đôi), 瓶 (chai), 杯 (cốc), 碗 (bát). Mỗi danh từ có lượng từ riêng, nhưng 个 có thể dùng thay thế trong nhiều trường hợp khẩu ngữ. Không có lượng từ sẽ khiến câu không đúng ngữ pháp.', 'examples' => ['三斤苹果。Ba cân táo.', '一件衣服。Một cái áo.', '两双鞋。Hai đôi giày.']],
            ['point' => '太 + Tính từ + 了 (quá... rồi)', 'explain' => 'Cấu trúc 太...了 dùng để biểu thị mức độ vượt quá tiêu chuẩn, có nghĩa là "quá". 太 đứng trước tính từ, 了 đứng cuối câu. Có thể dùng cho cả nghĩa tích cực (太好了 — tốt quá) và tiêu cực (太贵了 — đắt quá). Trong giao tiếp, cấu trúc này rất phổ biến để biểu lộ cảm xúc. Lưu ý: 太 thường dùng với 了, nhưng trong một số trường hợp có thể bỏ 了 khi dùng với nghĩa "rất" trong văn phong trang trọng.', 'examples' => ['太贵了！Đắt quá!', '太好了！Tốt quá!', '这个太小了。Cái này nhỏ quá.']],
        ],
        'pronunciation' => ['focus' => 'numbers and tones', 'drill' => ['yī', 'èr', 'sān', 'sì', 'wǔ', 'liù', 'qī', 'bā']],
