    9 => [
        'title' => 'Bài 9: 我家有三口人 - Nhà tôi có ba người',
        'text' => '大家好，我叫王小明。今天我要给大家介绍我的家庭。我家有五口人：爷爷、奶奶、爸爸、妈妈和我。爷爷今年七十二岁，奶奶今年六十八岁。爷爷以前是医生，现在已经退休了。奶奶以前是老师，也退休了。他们现在在家里休息，每天早上去公园锻炼身体。我的爸爸今年四十五岁，他是工程师，在一家大公司工作。他工作很忙，但是每天都会回家吃晚饭。我的妈妈今年四十三岁，她是护士，在医院工作。她工作也很辛苦，但是她很爱我们这个家。我没有哥哥姐姐，也没有弟弟妹妹，我是家里唯一的孩子。但是我有两个好朋友，一个是我的同学大卫，一个是我的同学安娜。我们经常一起学习，一起玩。大卫是美国人，他家里有五口人：爸爸、妈妈、两个哥哥和他。安娜是法国人，她家里有三口人：爸爸、妈妈和她。我们三个的家里人数都不一样，但是我们都过得很幸福。我爷爷和奶奶很疼我，常常给我做好吃的东西。周末的时候，我们一家人常常一起去公园散步。有时候也会去看电影或者去餐厅吃饭。我很爱我的家人，家人是我最重要的财富。',
        'dialogues' => [
            ['who' => '老师', 'cn' => '王小明，你家有几口人？', 'vi' => 'Vương Tiểu Minh, nhà em có mấy người?'],
            ['who' => '王小明', 'cn' => '我家有五口人。', 'vi' => 'Nhà em có năm người.'],
            ['who' => '老师', 'cn' => '你家有谁？', 'vi' => 'Nhà em có những ai?'],
            ['who' => '王小明', 'cn' => '有爷爷、奶奶、爸爸、妈妈和我。', 'vi' => 'Có ông nội, bà nội, bố, mẹ và em.'],
            ['who' => '老师', 'cn' => '你爷爷做什么工作？', 'vi' => 'Ông em làm công việc gì?'],
            ['who' => '王小明', 'cn' => '爷爷以前是医生，现在退休了。', 'vi' => 'Ông trước đây là bác sĩ, bây giờ đã nghỉ hưu.'],
            ['who' => '老师', 'cn' => '你有兄弟姐妹吗？', 'vi' => 'Em có anh chị em không?'],
            ['who' => '王小明', 'cn' => '没有，我是独生子。', 'vi' => 'Không ạ, em là con một.'],
            ['who' => '大卫', 'cn' => '我家有五口人，我有两个哥哥。', 'vi' => 'Nhà tôi có năm người, tôi có hai anh trai.'],
            ['who' => '安娜', 'cn' => '我家只有三口人，我是独生女。', 'vi' => 'Nhà tôi chỉ có ba người, tôi là con một.'],
            ['who' => '老师', 'cn' => '大家的家庭都不一样，但是都很幸福。', 'vi' => 'Gia đình mọi người đều khác nhau, nhưng đều rất hạnh phúc.'],
        ],
        'grammar' => [
            ['point' => '有 (có) chỉ sự tồn tại', 'explain' => '有 được dùng để chỉ sự tồn tại hoặc sở hữu. Trong câu chỉ sự tồn tại, cấu trúc thường là: Địa điểm / Nơi chốn + 有 + Người / Vật (Ở đâu đó có ai/cái gì). Ví dụ: 我家有五口人 (Nhà tôi có năm người). 桌子上有一本书 (Trên bàn có một quyển sách). Phủ định: 没有 (không có). 有 rất quan trọng trong tiếng Trung và xuất hiện trong nhiều ngữ cảnh. Có thể dùng 有 để hỏi về sự tồn tại: 你家有几个人？', 'examples' => ['我家有五口人。Nhà tôi có năm người.', '桌子上有一本书。Trên bàn có một quyển sách.', '他没有哥哥。Anh ấy không có anh trai.']],
            ['point' => 'Số + Lượng từ + Danh từ', 'explain' => 'Trong tiếng Trung, khi muốn đếm hoặc nói về số lượng, cấu trúc cố định là: Số + Lượng từ + Danh từ. Lượng từ là thành phần bắt buộc, không thể thiếu. Mỗi danh từ thường đi kèm với lượng từ riêng: 一个人, 两本书, 三张桌子. Khi số lượng là 2, dùng 两 thay vì 二 trước lượng từ: 两个人, 两本书. Nhưng trong số đếm và khi đọc số thì dùng 二: 十二, 二十, 二百.', 'examples' => ['三个人。Ba người.', '两本书。Hai quyển sách.', '五口人。Năm người.']],
            ['point' => 'Phủ định với 没有 (không có)', 'explain' => '没有 là dạng phủ định của 有, mang nghĩa "không có". Cấu trúc: Chủ ngữ + 没有 + Tân ngữ. 没有 cũng được dùng để phủ định sự tồn tại hoặc sở hữu. Trong quá khứ, 没有 (hoặc 没) được dùng để phủ định hành động đã xảy ra: 我没去 (Tôi đã không đi). Lưu ý: 不 dùng để phủ định hiện tại và tương lai, 没有 dùng để phủ định quá khứ và sự tồn tại. VD: 我没有钱 (Tôi không có tiền — phủ định sở hữu).', 'examples' => ['我没有哥哥。Tôi không có anh trai.', '他没有钱。Anh ấy không có tiền.', '我没去学校。Tôi đã không đi học.']],
        ],
        'pronunciation' => ['focus' => 'r initial', 'drill' => ['rè', 'rì', 'rén', 'ràng', 'ruò', 'rú', 'rǎn', 'rào']],
