            ['w' => '口', 'p' => 'kǒu', 'm' => 'miệng, người (lượng từ cho gia đình)', 'pos' => '量词', 'ex' => ['我家有三口人。Nhà tôi có ba người.', '一家四口人。Một gia đình bốn người.']],
