    10 => [
        'title' => 'Bài 10: 天气很好 - Thời tiết đẹp',
        'text' => '北京的春天很暖和，但是有时候会刮风。夏天很热，常常下雨。秋天最舒服，天气凉快，不冷不热。冬天很冷，会下雪，到处白茫茫的，非常漂亮。今天天气很好，晴空万里，没有云彩。太阳暖暖地照在身上，让人感觉很舒服。我决定和朋友大卫一起去公园玩。我们走在路上，温暖的春风吹在脸上，很舒服。公园里有很多人。有的人在跑步，有的人在散步，有的人在放风筝。天空中有很多五颜六色的风筝，非常好看。大卫说："今天的天气真好啊！不冷也不热。"我说："是啊，春天是最美的季节。我最喜欢春天了。"大卫问我："你最喜欢什么季节？"我说："我喜欢春天和秋天。春天暖和，秋天凉快。你呢？"大卫说："我喜欢夏天，因为夏天可以去游泳。但是夏天太热了，有时候会中暑。"我说："冬天也很美啊，下雪的时候很好看。"大卫说："但是冬天太冷了，我不喜欢冷。"我们走到一个小湖边，湖水很清，可以看到水里的鱼。我们坐在湖边的椅子上，一边聊天一边看风景。今天真是一个愉快的一天。好的天气让人心情也好。我希望每天都是好天气。',
        'dialogues' => [
            ['who' => '王小明', 'cn' => '今天天气真好！我们出去玩吧。', 'vi' => 'Hôm nay thời tiết đẹp quá! Chúng ta ra ngoài chơi đi.'],
            ['who' => '大卫', 'cn' => '好啊！今天的天气不冷也不热。', 'vi' => 'Tốt quá! Thời tiết hôm nay không lạnh cũng không nóng.'],
            ['who' => '王小明', 'cn' => '你最喜欢什么季节？', 'vi' => 'Bạn thích mùa nào nhất?'],
            ['who' => '大卫', 'cn' => '我最喜欢夏天，因为可以去游泳。', 'vi' => 'Tôi thích nhất mùa hè, vì có thể đi bơi.'],
            ['who' => '王小明', 'cn' => '夏天太热了，我喜欢春天和秋天。', 'vi' => 'Mùa hè nóng quá, tôi thích mùa xuân và mùa thu.'],
            ['who' => '大卫', 'cn' => '北京冬天会下雪吗？', 'vi' => 'Mùa đông Bắc Kinh có tuyết không?'],
            ['who' => '王小明', 'cn' => '会啊，北京冬天常常下雪，很漂亮。', 'vi' => 'Có chứ, mùa đông Bắc Kinh thường có tuyết, rất đẹp.'],
            ['who' => '大卫', 'cn' => '今天多少度？', 'vi' => 'Hôm nay bao nhiêu độ?'],
            ['who' => '王小明', 'cn' => '今天大概二十度左右。', 'vi' => 'Hôm nay khoảng hai mươi độ.'],
            ['who' => '大卫', 'cn' => '太好了，那我们快走吧！', 'vi' => 'Tuyệt quá, vậy chúng ta đi nhanh thôi!'],
        ],
        'grammar' => [
            ['point' => 'Trạng từ chỉ mức độ: 很, 非常, 太', 'explain' => 'Trong tiếng Trung, các trạng từ chỉ mức độ đứng trước tính từ để bổ nghĩa. 很 (rất) là phổ biến nhất, thường dùng trong câu trần thuật. 非常 (rất, vô cùng) có mức độ mạnh hơn 很. 太...了 (quá) chỉ mức độ vượt quá, thường mang sắc thái cảm thán. Cấu trúc: 很/非常/太 + Tính từ. Lưu ý: 太 thường đi kèm 了 ở cuối câu. Các trạng từ này không thể dùng cùng lúc với nhau. Không dùng 很 sau 有 hoặc 是.', 'examples' => ['今天很热。Hôm nay rất nóng.', '这个非常好吃。Cái này rất ngon.', '天气太好了！Thời tiết tốt quá!']],
            ['point' => '了 chỉ sự thay đổi (Change of State)', 'explain' => '了 ở cuối câu (ngữ khí từ) biểu thị sự thay đổi trạng thái hoặc tình huống mới. Nó cho biết một sự việc đã xảy ra hoặc một trạng thái mới bắt đầu. Ví dụ: 下雨了! (Mưa rồi! — trước không mưa, bây giờ mưa). 我明白了 (Tôi hiểu rồi — trước không hiểu, bây giờ hiểu). 她不高兴了 (Cô ấy không vui nữa — thay đổi tâm trạng). 了 này khác với 了 chỉ hoàn thành hành động.', 'examples' => ['下雨了。Mưa rồi.', '天气变冷了。Thời tiết trở nên lạnh rồi.', '我明白了。Tôi hiểu rồi.']],
            ['point' => 'Câu vị ngữ chủ-vị (Subject-Predicate Predicate)', 'explain' => 'Trong tiếng Trung, có một cấu trúc đặc biệt: Chủ ngữ + [Chủ ngữ 2 + Vị ngữ]. Toàn bộ cụm [Chủ ngữ 2 + Vị ngữ] làm vị ngữ cho chủ ngữ chính. Cấu trúc này thường dùng trong miêu tả. Ví dụ: 今天天气很好 (Hôm nay thời tiết rất tốt) — "今天" là chủ ngữ chính, "天气很好" là vị ngữ chủ-vị. 我头疼 (Tôi đau đầu) — "我" là chủ ngữ, "头疼" (đầu đau) là vị ngữ. Cấu trúc này rất phổ biến trong tiếng Trung.', 'examples' => ['今天天气很好。Hôm nay thời tiết rất đẹp.', '他身体很好。Anh ấy sức khỏe rất tốt.', '我肚子饿了。Tôi đói bụng rồi.']],
        ],
        'pronunciation' => ['focus' => 'ü and üe', 'drill' => ['nǚ', 'lǜ', 'xué', 'yuè', 'jué', 'què', 'xuān', 'yuán']],
