            ['w' => '热', 'p' => 'rè', 'm' => 'nóng', 'pos' => '形容词', 'ex' => ['夏天很热。Mùa hè rất nóng.', '今天太热了。Hôm nay nóng quá.']],
            ['w' => '暖和', 'p' => 'nuǎnhuo', 'm' => 'ấm áp', 'pos' => '形容词', 'ex' => ['春天很暖和。Mùa xuân rất ấm áp.', '屋里很暖和。Trong nhà rất ấm.']],
