    11 => [
        'title' => 'Bài 11: 九月去北京旅游最好 - Tháng chín đi Bắc Kinh du lịch là tốt nhất',
        'text' => '北京是中国有名的古城，有很多名胜古迹，比如故宫、长城、天坛和颐和园。每年都有很多外国朋友来北京旅游。北京最好看的季节是秋天，尤其是九月。九月天气凉快，不冷也不热，最适合出去玩了。如果你们想到北京旅游，九月是最好的时间。我朋友大卫想暑假来北京旅游，他问我什么时候来最好。我对他说："暑假的时候北京太热了，而且人也很多。你最好九月来，九月天气凉快，还可以看到很美的风景。"大卫听了以后说："好啊，那我就九月来。"我又对他说："来北京一定要去长城，长城是世界七大奇迹之一，非常壮观。还要去故宫看看，那是明清两代的皇宫。天坛也很漂亮，是古代皇帝祭天的地方。"大卫说："这么多好玩的地方，我已经等不及了。"来北京旅游不仅要看风景，还要吃北京的美食。北京烤鸭很有名，全聚德的烤鸭最好吃。还有炸酱面、涮羊肉，都是北京的特色菜。如果大家来北京旅游，我可以给大家当导游。',
        'dialogues' => [
            ['who' => '大卫', 'cn' => '王小明，我想暑假去北京旅游，你觉得怎么样？', 'vi' => 'Vương Tiểu Minh, tôi muốn đi du lịch Bắc Kinh vào kỳ nghỉ hè, anh thấy thế nào?'],
            ['who' => '王小明', 'cn' => '暑假北京太热了，你最好九月去。', 'vi' => 'Nghỉ hè Bắc Kinh nóng quá, anh tốt nhất nên đi tháng chín.'],
            ['who' => '大卫', 'cn' => '九月天气怎么样？', 'vi' => 'Thời tiết tháng chín thế nào?'],
            ['who' => '王小明', 'cn' => '九月天气很凉快，不冷也不热，很适合旅游。', 'vi' => 'Tháng chín thời tiết rất mát mẻ, không lạnh cũng không nóng, rất thích hợp du lịch.'],
            ['who' => '大卫', 'cn' => '北京有哪些好玩的地方？', 'vi' => 'Bắc Kinh có những chỗ nào thú vị?'],
            ['who' => '王小明', 'cn' => '故宫、长城、天坛和颐和园都很有名，你一定要去看看。', 'vi' => 'Tử Cấm Thành, Vạn Lý Trường Thành, Thiên Đàn và Di Hòa Viên đều rất nổi tiếng, anh nhất định phải đi xem.'],
            ['who' => '大卫', 'cn' => '北京有什么好吃的？', 'vi' => 'Bắc Kinh có gì ngon?'],
            ['who' => '王小明', 'cn' => '北京烤鸭最有名，还有炸酱面和涮羊肉。', 'vi' => 'Vịt quay Bắc Kinh nổi tiếng nhất, còn có mì trộn tương và lẩu cừu.'],
            ['who' => '大卫', 'cn' => '太好了！我一定要去北京看看。', 'vi' => 'Tuyệt quá! Tôi nhất định phải đi Bắc Kinh xem.'],
        ],
        'grammar' => [
            ['point' => 'So sánh với 比', 'explain' => 'Trong tiếng Trung, 比 được dùng để so sánh hai đối tượng. Cấu trúc: A + 比 + B + Tính từ. Ví dụ: 今天比昨天冷 (Hôm nay lạnh hơn hôm qua). 北京比上海大 (Bắc Kinh lớn hơn Thượng Hải). Nếu muốn nói mức độ chênh lệch, thêm lượng từ sau tính từ: 我比他大三岁 (Tôi lớn hơn anh ấy ba tuổi). Phủ định dùng 没有: A + 没有 + B + Tính từ (A không bằng B).', 'examples' => ['今天比昨天热。Hôm nay nóng hơn hôm qua.', '北京比上海大。Bắc Kinh lớn hơn Thượng Hải.', '我没有他高。Tôi không cao bằng anh ấy.']],
            ['point' => '最好 + Động từ (tốt nhất nên làm gì)', 'explain' => '最好 là một cấu trúc khuyên bảo, nghĩa là "tốt nhất là nên". Nó được đặt trước động từ để đưa ra lời khuyên. Cấu trúc: Chủ ngữ + 最好 + Động từ. Ví dụ: 你最好早点来 (Bạn tốt nhất nên đến sớm). 我们最好坐地铁去 (Chúng ta tốt nhất nên đi tàu điện ngầm). Đây là cách đưa ra lời khuyên nhẹ nhàng, lịch sự. Không dùng với nghĩa mệnh lệnh.', 'examples' => ['你最好九月来。Bạn tốt nhất nên đến tháng chín.', '我们最好坐地铁去。Chúng ta tốt nhất nên đi tàu điện ngầm.', '你最好多穿衣服。Bạn tốt nhất nên mặc nhiều quần áo.']],
            ['point' => 'Cấu trúc 是...的 (nhấn mạnh)', 'explain' => 'Cấu trúc 是...的 được dùng để nhấn mạnh một thành phần trong câu, như thời gian, địa điểm, cách thức. Đặt 是 trước thành phần cần nhấn mạnh và 的 ở cuối câu. Ví dụ: 我是去年来的北京 (Tôi đến Bắc Kinh từ năm ngoái — nhấn mạnh thời gian). 他是坐飞机来的 (Anh ấy đến bằng máy bay — nhấn mạnh phương tiện). Cấu trúc này thường dùng khi đã có ngữ cảnh trước đó.', 'examples' => ['我是去年来的。Tôi đến từ năm ngoái.', '他是坐火车去的。Anh ấy đi bằng tàu hỏa.', '这本书是在书店买的。Cuốn sách này được mua ở hiệu sách.']],
