    12 => [
        'title' => 'Bài 12: 我每天六点起床 - Tôi mỗi ngày dậy lúc sáu giờ',
        'text' => '我的日常生活很有规律。我每天六点起床，起床以后先刷牙洗脸，然后做早饭。我通常会喝一杯牛奶，吃两片面包和一个鸡蛋。吃完早饭后，我七点离开家去学校。从家到学校坐地铁要四十分钟。我一般七点四十五分到学校，八点开始上课。上午有四节课，十二点下课。中午我在学校食堂吃饭，食堂的饭菜又便宜又好吃。下午我没有课的时候，会去图书馆看书或者写作业。我一般五点离开学校回家。晚饭是我和爸爸妈妈一起吃的，我们一边吃饭一边聊天，很开心。吃完晚饭以后，我有时候看电视，有时候看书。晚上十点左右，我开始准备睡觉。睡觉前我会看一会儿手机，然后十点半关灯睡觉。这就是我的一天。虽然每天做的事情差不多，但是我觉得很充实。周末的时候，我的生活会不一样。星期六我可以睡懒觉，有时候和朋友出去玩。星期天我会在家复习功课，预习下个星期要学的内容。我的同学大卫常常问我："你每天都这么早起床，不累吗？"我说："习惯了就好了。早睡早起身体好。"',
        'dialogues' => [
            ['who' => '大卫', 'cn' => '王小明，你每天几点起床？', 'vi' => 'Vương Tiểu Minh, mỗi ngày bạn dậy lúc mấy giờ?'],
            ['who' => '王小明', 'cn' => '我每天六点起床。', 'vi' => 'Mỗi ngày tôi dậy lúc sáu giờ.'],
            ['who' => '大卫', 'cn' => '这么早！你几点睡觉？', 'vi' => 'Sớm vậy! Bạn đi ngủ lúc mấy giờ?'],
            ['who' => '王小明', 'cn' => '我晚上十点半睡觉。', 'vi' => 'Tôi đi ngủ lúc mười rưỡi tối.'],
            ['who' => '大卫', 'cn' => '你早上吃什么？', 'vi' => 'Sáng bạn ăn gì?'],
            ['who' => '王小明', 'cn' => '我喝一杯牛奶，吃面包和鸡蛋。', 'vi' => 'Tôi uống một cốc sữa bò, ăn bánh mì và trứng.'],
            ['who' => '大卫', 'cn' => '你怎么去学校？', 'vi' => 'Bạn đến trường bằng gì?'],
            ['who' => '王小明', 'cn' => '我坐地铁去学校，需要四十分钟。', 'vi' => 'Tôi đi tàu điện ngầm đến trường, cần bốn mươi phút.'],
            ['who' => '大卫', 'cn' => '中午你在哪儿吃饭？', 'vi' => 'Trưa bạn ăn cơm ở đâu?'],
            ['who' => '王小明', 'cn' => '我在学校食堂吃饭。', 'vi' => 'Tôi ăn ở căng tin trường.'],
            ['who' => '大卫', 'cn' => '周末你一般做什么？', 'vi' => 'Cuối tuần bạn thường làm gì?'],
            ['who' => '王小明', 'cn' => '星期六出去玩儿，星期天在家复习功课。', 'vi' => 'Thứ bảy ra ngoài chơi, chủ nhật ở nhà ôn bài.'],
        ],
        'grammar' => [
            ['point' => 'Mỗi ngày: 每天 và 每 + Lượng từ + Danh từ', 'explain' => '每 có nghĩa là "mỗi", thường được dùng với lượng từ và danh từ để nói về tần suất. Cấu trúc: 每 + (Số) + Lượng từ + Danh từ. Ví dụ: 每天 (mỗi ngày), 每个星期 (mỗi tuần), 每个人 (mỗi người). 每 thường kết hợp với 都 ở phần vị ngữ để nhấn mạnh: 我每天都喝牛奶 (Ngày nào tôi cũng uống sữa). Trong câu có 每, 都 thường đi kèm để diễn tả "tất cả các trường hợp đều như vậy".', 'examples' => ['我每天六点起床。Tôi dậy lúc sáu giờ mỗi ngày.', '他每个星期都去游泳。Anh ấy đi bơi mỗi tuần.', '每个人都说汉语好。Mỗi người đều nói tiếng Trung tốt.']],
            ['point' => 'Từ chỉ tần suất: 常常, 有时候, 一般', 'explain' => 'Trong tiếng Trung, từ chỉ tần suất đứng trước động từ chính. Các từ thường gặp: 常常 (thường xuyên), 有时候 (thỉnh thoảng, có lúc), 一般 (bình thường, thông thường). 常常 có tần suất cao hơn 有时候. 一般 được dùng để nói về thói quen hoặc tình huống thông thường. Ví dụ: 我常常看书 (Tôi thường xuyên đọc sách). 我有时候看电视 (Thỉnh thoảng tôi xem TV). 我一般十点睡觉 (Thông thường tôi đi ngủ lúc 10 giờ).', 'examples' => ['我常常去图书馆。Tôi thường xuyên đến thư viện.', '我有时候看电视。Thỉnh thoảng tôi xem TV.', '我一般十二点吃午饭。Thông thường tôi ăn trưa lúc mười hai giờ.']],
            ['point' => 'Các từ nối thời gian: 然后, 以后, 先...再...', 'explain' => '先...再... (trước... sau đó...) và 然后 (sau đó) được dùng để sắp xếp trình tự hành động. 先 đứng trước hành động thứ nhất, 再/然后 đứng trước hành động thứ hai. 先 và 再 thường dùng trong cùng một câu: 先吃饭再看书 (Ăn cơm trước rồi đọc sách sau). 然后 có thể dùng riêng giữa hai câu. 以后 (sau đó, về sau) thường chỉ thời gian trong tương lai hoặc sau một mốc thời gian.', 'examples' => ['我先刷牙再吃早饭。Tôi đánh răng trước rồi ăn sáng sau.', '我起床以后先洗脸，然后吃早饭。Sau khi dậy tôi rửa mặt trước, sau đó ăn sáng.', '以后我要早点儿起床。Sau này tôi phải dậy sớm hơn.']],
        ],
