            ['w' => '每天', 'p' => 'měi tiān', 'm' => 'mỗi ngày', 'pos' => '时间词', 'ex' => ['我每天喝牛奶。Tôi uống sữa mỗi ngày.', '他每天跑步。Anh ấy chạy bộ mỗi ngày.']],
            ['w' => '刷牙', 'p' => 'shuā yá', 'm' => 'đánh răng', 'pos' => '动词', 'ex' => ['我每天早上刷牙。Tôi đánh răng mỗi sáng.', '睡觉前要刷牙。Trước khi ngủ phải đánh răng.']],
