    13 => [
        'title' => 'Bài 13: 左边那个红色的是我的 - Cái màu đỏ bên trái là của tôi',
        'text' => '今天下午没课，我和安娜一起去商场买东西。商场很大，有很多层，每一层卖的东西都不一样。一楼卖化妆品和首饰，二楼卖男装，三楼卖女装，四楼卖运动用品，五楼是美食广场。我们先去三楼看女装。安娜想买一件外套。她看中了一件白色的和一件黑色的。她问我："你觉得哪件好看？白色还是黑色？"我说："白色很好看，但是黑色更耐脏。你更喜欢哪个颜色？"安娜说："两个我都喜欢，我不知道选哪个。"我说："那件白色的你穿着很漂亮。你试试看吧。"安娜试了一下白色的外套，非常合适。她说："那我就买白色的吧。"我们走到收银台，售货员说："这件三百五十块。"安娜付了钱。然后我们去四楼看运动鞋。我需要一双新运动鞋。我看到一双蓝色的和一双红色的。我问安娜："左边那双蓝色的好看还是右边那双红色的好看？"安娜说："我觉得左边那个蓝色的更好看。"我试了一下，大小正合适。我问售货员："这双鞋多少钱？"售货员说："这双二百八十块，现在是打折季节，可以打八折。"我说："那很便宜啊，我就买这双吧。"今天我和安娜都买到了喜欢的东西，我们都很满意。',
        'dialogues' => [
            ['who' => '安娜', 'cn' => '王小明，你看这两件外套，哪件好看？', 'vi' => 'Vương Tiểu Minh, anh nhìn hai cái áo khoác này, cái nào đẹp?'],
            ['who' => '王小明', 'cn' => '左边那件白色的很好看。', 'vi' => 'Cái màu trắng bên trái rất đẹp.'],
            ['who' => '安娜', 'cn' => '但是黑色的更耐脏。', 'vi' => 'Nhưng màu đen bẩn hơn.'],
            ['who' => '王小明', 'cn' => '你试试白色的吧，你穿着一定很漂亮。', 'vi' => 'Em thử cái màu trắng đi, em mặc nhất định rất đẹp.'],
            ['who' => '安娜', 'cn' => '好吧，我试试。好看吗？', 'vi' => 'Được, em thử nhé. Có đẹp không?'],
            ['who' => '王小明', 'cn' => '很好看！大小也很合适。', 'vi' => 'Rất đẹp! Kích cỡ cũng rất vừa.'],
            ['who' => '王小明', 'cn' => '你看这两双鞋，哪双好看？', 'vi' => 'Em nhìn hai đôi giày này, đôi nào đẹp?'],
            ['who' => '安娜', 'cn' => '左边那个蓝色的更好看。', 'vi' => 'Đôi màu xanh bên trái đẹp hơn.'],
            ['who' => '王小明', 'cn' => '这双鞋多少钱？', 'vi' => 'Đôi giày này bao nhiêu tiền?'],
            ['who' => '售货员', 'cn' => '这双二百八十块，现在打八折。', 'vi' => 'Đôi này hai trăm tám mươi tệ, bây giờ đang giảm 20%.'],
            ['who' => '王小明', 'cn' => '很便宜，我买了。', 'vi' => 'Rất rẻ, tôi mua.'],
        ],
        'grammar' => [
            ['point' => 'Từ chỉ vị trí: 左边, 右边, 上边, 下边', 'explain' => 'Từ chỉ vị trí trong tiếng Trung thường có cấu trúc: Danh từ / Đại từ + 的 + Từ chỉ vị trí. Ví dụ: 左边 (bên trái), 右边 (bên phải), 上边 (bên trên), 下边 (bên dưới), 前边 (đằng trước), 后边 (đằng sau), 里面 (bên trong), 外面 (bên ngoài). Có thể dùng 边 hoặc 面 tùy theo khẩu ngữ hoặc văn viết. Để chỉ vị trí cụ thể: 在...的左边/右边/上边/下边. Ví dụ: 书在桌子的上边 (Sách ở trên bàn).', 'examples' => ['左边那个是我的。Cái bên trái là của tôi.', '书在桌子的上边。Sách ở trên mặt bàn.', '他在我的右边。Anh ấy ở bên phải tôi.']],
            ['point' => 'Đại từ chỉ thị: 这, 那 + Lượng từ', 'explain' => 'Khi có nhiều đối tượng, dùng 这 (này) và 那 (kia) kết hợp với lượng từ và danh từ để xác định cụ thể. Cấu trúc: 这/那 + Lượng từ + (Danh từ). Ví dụ: 这个 (cái này), 那个 (cái kia), 这件 (cái này — cho quần áo), 那双 (đôi kia). Khi muốn phân biệt hai đối tượng, thường so sánh: 这个比那个好 (Cái này tốt hơn cái kia). Lượng từ phải phù hợp với danh từ đi kèm.', 'examples' => ['这个比那个大。Cái này lớn hơn cái kia.', '我要这个，不要那个。Tôi muốn cái này, không muốn cái kia.', '那件衣服很漂亮。Cái áo kia rất đẹp.']],
            ['point' => 'Cấu trúc so sánh: A 比 B + Tính từ + 一点儿/得多', 'explain' => 'Để chỉ mức độ chênh lệch trong so sánh, thêm các từ bổ nghĩa sau tính từ. 一点儿 (một chút) chỉ chênh lệch ít. 得多 (nhiều hơn) chỉ chênh lệch lớn. Cấu trúc: A + 比 + B + Tính từ + 一点儿/得多. Ví dụ: 这个比那个大一点儿 (Cái này lớn hơn cái kia một chút). 今天比昨天冷得多 (Hôm nay lạnh hơn hôm qua nhiều). Cũng có thể dùng 多了 thay cho 得多.', 'examples' => ['这个比那个大一点儿。Cái này lớn hơn cái kia một chút.', '今天比昨天冷得多。Hôm nay lạnh hơn hôm qua nhiều.', '她比我高多了。Cô ấy cao hơn tôi nhiều.']],
        ],
