    14 => [
        'title' => 'Bài 14: 这个工作是他帮我介绍的 - Công việc này là anh ấy giới thiệu cho tôi',
        'text' => '大学毕业后，我想找一份工作。我的朋友李明在一家公司做经理，他对我说："我们公司正在招聘，你要不要来试试？"我说："好啊，谢谢你帮我介绍工作。"李明帮我约好了面试时间。面试那天，我穿得很正式，提前十分钟到了公司。面试官问了我很多问题，比如我的专业、工作经验和对未来的规划。我觉得自己回答得还不错。面试结束以后，李明问我觉得怎么样。我说："还可以，但是不知道能不能被录用。"过了两天，李明给我打电话说："恭喜你，你被录用了！"我听了非常高兴，对他说："谢谢你帮我介绍这个工作！晚上我请你吃饭。"李明说："不用客气，我们是朋友嘛。"我开始工作以后，发现这份工作很适合我。公司环境很好，同事之间互相帮助，关系很融洽。我的工作主要是做市场调研，每天要分析数据，写报告。虽然工作有点儿忙，但是我觉得很有意义。经理对我很好，常常给我指导和帮助。我每天早上去上班，下午五点半下班。周末一般不用加班。我对现在的工作很满意。我常常想起是李明帮我介绍了这份好工作，所以我非常感激他。以后我也要像他一样，帮助更多的朋友。',
        'dialogues' => [
            ['who' => '李明', 'cn' => '王小明，我们公司正在招人，你感兴趣吗？', 'vi' => 'Vương Tiểu Minh, công ty tôi đang tuyển người, bạn có quan tâm không?'],
            ['who' => '王小明', 'cn' => '真的吗？太好了！我正想找工作呢。', 'vi' => 'Thật sao? Tuyệt quá! Tôi đang muốn tìm việc.'],
            ['who' => '李明', 'cn' => '我把你的简历给经理看了，他说可以来面试。', 'vi' => 'Tôi đưa CV của bạn cho quản lý xem, anh ấy nói có thể đến phỏng vấn.'],
            ['who' => '王小明', 'cn' => '谢谢你帮我介绍！什么时候面试？', 'vi' => 'Cảm ơn bạn đã giới thiệu giúp! Khi nào phỏng vấn?'],
            ['who' => '李明', 'cn' => '这个星期五下午两点，你方便吗？', 'vi' => 'Thứ sáu này hai giờ chiều, bạn có tiện không?'],
            ['who' => '王小明', 'cn' => '方便，我一定准时到。', 'vi' => 'Tiện, tôi nhất định đến đúng giờ.'],
            ['who' => '李明', 'cn' => '面试的时候要放松，别紧张。', 'vi' => 'Khi phỏng vấn phải thư giãn, đừng căng thẳng.'],
            ['who' => '王小明', 'cn' => '好的，我知道了。你帮我介绍这个工作，我真不知道该怎么感谢你。', 'vi' => 'Được, tôi biết rồi. Bạn giới thiệu công việc này cho tôi, tôi thực sự không biết cảm ơn thế nào.'],
            ['who' => '李明', 'cn' => '别客气，我们是好朋友嘛。', 'vi' => 'Đừng khách sáo, chúng ta là bạn tốt mà.'],
        ],
        'grammar' => [
            ['point' => 'Cấu trúc 是...的 nhấn mạnh đối tượng', 'explain' => 'Cấu trúc 是...的 được dùng để nhấn mạnh một thành phần trong câu, thường là chủ thể thực hiện hành động. Trong câu "这个工作是他帮我介绍的", 是 đặt trước "他" để nhấn mạnh rằng chính anh ấy là người đã giới thiệu. Cấu trúc: 是 + Thành phần nhấn mạnh + Động từ + 的. Rất thông dụng trong khẩu ngữ để trả lời câu hỏi về ai đã làm gì. Ví dụ: 是谁告诉你的? (Ai đã nói với bạn?).', 'examples' => ['这个工作是他介绍的。Công việc này là anh ấy giới thiệu.', '是我告诉他的。Chính tôi đã nói với anh ấy.', '这本书是在北京买的。Cuốn sách này được mua ở Bắc Kinh.']],
            ['point' => 'Động từ 帮 + Đối tượng + Động từ (giúp ai làm gì)', 'explain' => '帮 là động từ mang nghĩa "giúp". Cấu trúc: 帮 + Người + Động từ. Nghĩa là giúp ai đó làm việc gì. Ví dụ: 帮我介绍 (giúp tôi giới thiệu), 帮他找 (giúp anh ấy tìm). 帮 có thể thay thế bằng 帮助 nhưng 帮 ngắn gọn hơn, thường dùng trong khẩu ngữ. Nếu muốn nói giúp đỡ chung chung thì dùng 帮助. Cả hai đều theo cấu trúc: 帮/帮助 + Người (+ Động từ).', 'examples' => ['他帮我介绍工作。Anh ấy giúp tôi giới thiệu công việc.', '你能帮我一下吗？Bạn có thể giúp tôi một chút không?', '我帮你找找看。Tôi giúp bạn tìm xem sao.']],
            ['point' => 'Cách nói về sự cảm kích: 真不知道该怎么感谢你', 'explain' => 'Để bày tỏ lòng biết ơn một cách mạnh mẽ, người Trung Quốc thường nói: 真不知道该怎么感谢你 (Thực sự không biết nên cảm ơn bạn thế nào). Đây là cách nói lịch sự cho thấy sự biết ơn sâu sắc. Các cách cảm ơn khác: 非常感谢 (vô cùng cảm ơn), 太感谢了 (cảm ơn quá), 麻烦你了 (làm phiền bạn rồi — xin lỗi đã làm phiền). Khi đáp lại: 不客气, 别客气, 没事儿, 应该的.', 'examples' => ['真不知道该怎么感谢你！Thực sự không biết nên cảm ơn bạn thế nào.', '非常感谢你的帮助！Rất cảm ơn sự giúp đỡ của bạn.', '太麻烦你了！Làm phiền bạn quá!']],
        ],
        'pronunciation' => ['focus' => 'tone pairs 2-3', 'drill' => ['pí jiǔ', 'huí jiā', 'fáng jiān', 'qián miàn', 'tóng xué', 'shuǐ guǒ', 'yóu yǒng', 'píng guǒ']],
        'vocab' => [
