            ['w' => '公司', 'p' => 'gōngsī', 'm' => 'công ty', 'pos' => '名词', 'ex' => ['他在一家大公司上班。Anh ấy đi làm ở một công ty lớn.', '我们公司环境很好。Công ty chúng tôi môi trường rất tốt.']],
