    15 => [
        'title' => 'Bài 15: 就买这件吧 - Cứ mua cái này đi',
        'text' => '这个周末商场做活动，很多东西都在打折。妈妈想买一件大衣，我陪她一起去逛商场。我们来到一家女装店，里面有很多漂亮的大衣。妈妈看了一件又一件，总是拿不定主意。她先看了一件黑色的，觉得太长了。然后又看了一件灰色的，觉得颜色太暗了。接着看了一件红色的，觉得太鲜艳了。售货员很热情，给妈妈推荐了好几件。妈妈试了又试，还是不知道买哪件好。我对妈妈说："妈妈，我觉得你穿那件深蓝色的大衣很好看，很合适你。就买这件吧。而且现在打折，比原价便宜了两百块。"妈妈又看了看镜子里的自己，说："真的好看吗？"我说："真的很好看，你穿着很有气质。"售货员也在旁边说："这件是我们的新款，卖得很好。现在打七折，很划算。"妈妈想了想，终于说："好吧，就买这件吧。"付钱的时候，妈妈又看见旁边有一条围巾，颜色和那件大衣很搭配。妈妈问我："这条围巾怎么样？"我说："很好看，配你的大衣刚好。"妈妈高兴地又把围巾买了。回家的路上，妈妈对我说："幸亏你陪我来，帮我做决定。不然我还不知道要选到什么时候。"我说："不客气，能帮妈妈做事我很开心。"我们买到了满意的东西，高高兴兴地回家了。',
        'dialogues' => [
            ['who' => '妈妈', 'cn' => '小明，你看这件黑色的怎么样？', 'vi' => 'Tiểu Minh, con thấy cái màu đen này thế nào?'],
            ['who' => '王小明', 'cn' => '有点儿太长了，您再看看别的。', 'vi' => 'Hơi dài quá ạ, mẹ xem cái khác đi.'],
            ['who' => '妈妈', 'cn' => '这件灰色的呢？', 'vi' => 'Cái màu xám này thì sao?'],
            ['who' => '王小明', 'cn' => '颜色太暗了，您穿深蓝色的好看。', 'vi' => 'Màu tối quá, mẹ mặc màu xanh đậm thì đẹp.'],
            ['who' => '妈妈', 'cn' => '你帮我看看，哪件更好？', 'vi' => 'Con xem giúp mẹ, cái nào đẹp hơn?'],
            ['who' => '王小明', 'cn' => '深蓝色的那件最合适，就买这件吧。', 'vi' => 'Cái màu xanh đậm là hợp nhất, cứ mua cái này đi.'],
            ['who' => '妈妈', 'cn' => '真的好看吗？', 'vi' => 'Thật sự đẹp không?'],
            ['who' => '王小明', 'cn' => '真的好看，而且现在打七折，很便宜。', 'vi' => 'Thật sự đẹp, mà bây giờ giảm 30%, rất rẻ.'],
            ['who' => '妈妈', 'cn' => '好吧，就买这件。这条围巾也不错。', 'vi' => 'Được rồi, mua cái này. Cái khăn này cũng không tệ.'],
            ['who' => '王小明', 'cn' => '和您的大衣很搭配，一起买了吧。', 'vi' => 'Rất hợp với áo khoác của mẹ, mua luôn đi ạ.'],
        ],
        'grammar' => [
            ['point' => '就 (cứ / sẽ) — sự nhấn mạnh quyết định', 'explain' => '就 có nhiều nghĩa, trong bài này được dùng để nhấn mạnh sự quyết định hoặc lựa chọn cuối cùng. Cấu trúc: 就 + Động từ. Ví dụ: 就买这件吧 (Cứ mua cái này đi). 就 cũng có nghĩa là "ngay", "liền" hoặc "chỉ". Khi đặt trước động từ, 就 thể hiện sự kiên quyết hoặc chốt lại một lựa chọn. Thường đi kèm với 吧 ở cuối câu để tạo thành đề nghị hoặc quyết định. 就 còn dùng để chỉ sự sớm, nhanh: 我就来 (Tôi đến ngay).', 'examples' => ['就买这件吧。Cứ mua cái này đi.', '我就来。Tôi đến ngày.', '这就是我的家。Đây chính là nhà tôi.']],
            ['point' => 'Cấu trúc 了...了 (lặp lại hành động)', 'explain' => 'Để diễn tả hành động được lặp lại nhiều lần hoặc mất nhiều công sức, tiếng Trung dùng cấu trúc lặp lại động từ với 了: Động từ + 了 + lại + Động từ + 了. Ví dụ: 看了一件又一件 (Xem hết cái này đến cái khác), 试了又试 (Thử đi thử lại). Cấu trúc này nhấn mạnh sự lặp lại, thường dùng để chỉ sự do dự hoặc kiên trì. Một biến thể khác: 一次又一次 (Hết lần này đến lần khác).', 'examples' => ['她看了一件又一件。Cô ấy xem hết cái này đến cái khác.', '他试了又试。Anh ấy thử đi thử lại.', '我说了一遍又一遍。Tôi nói đi nói lại nhiều lần.']],
            ['point' => 'Tính từ + 得很 / Tính từ + 极了 (mức độ cao)', 'explain' => 'Để diễn tả mức độ cao ngoài việc dùng phó từ (很, 非常, 特别), tiếng Trung còn có hai cấu trúc: Tính từ + 得很 (mang nghĩa rất) và Tính từ + 极了 (mang nghĩa cực kỳ). Ví dụ: 好得很 (tốt lắm/rất tốt), 好吃极了 (ngon cực kỳ). 得很 dùng sau tính từ, phổ biến trong khẩu ngữ. 极了 mang sắc thái cảm thán mạnh hơn. Lưu ý: không phải tính từ nào cũng có thể kết hợp với cả hai.', 'examples' => ['这件好得很。Cái này tốt lắm.', '好吃极了！Ngon cực kỳ!', '漂亮极了。Đẹp vô cùng.']],
        ],
