    16 => [
        'title' => 'Bài 16: 大家互相帮助 - Mọi người giúp đỡ lẫn nhau',
        'text' => '我们班上有十五个同学，大家来自不同的国家。虽然每个人的汉语水平不一样，但是大家相处得很好。老师说："同学们要互相帮助，这样才能一起进步。"我们都觉得老师说得对。我的同桌是大卫，他的汉字写得不太好。有一天，大卫对我说："王小明，你能帮我看看我写的汉字吗？我觉得我写得不好。"我看了看他的作业本，说："你写得还不错，但是有些笔画不太对。你看这个字，"我"的第五画应该是提，不是横。"大卫仔细看了看，说："哦，我明白了。谢谢你！"我说："不客气，互相帮助是应该的。"安娜的听力和口语很好，但是她的语法不太好。她常常问我一些语法问题。比如她不知道什么时候用"了"，什么时候不用。我耐心地给她解释。安娜说："你解释得很清楚，谢谢你！"我笑着说："互相帮助嘛。以后我口语有问题，你也可以帮我。"安娜说："没问题！"班上的同学都很友好。有人在学习上遇到困难，其他同学都会主动帮忙。有的人帮忙纠正发音，有的人教大家写汉字，有的人分享学习经验。因为大家互相帮助，我们班的汉语水平提高得很快。老师看到了很高兴，对我们说："你们做得很好！学习语言最重要的就是互相帮助和互相鼓励。"我觉得在一个互相帮助的集体里学习，是一件很幸福的事情。',
        'dialogues' => [
            ['who' => '大卫', 'cn' => '王小明，你能帮我看看这个字怎么写吗？', 'vi' => 'Vương Tiểu Minh, bạn có thể giúp tôi xem chữ này viết thế nào không?'],
            ['who' => '王小明', 'cn' => '可以啊，哪个字？', 'vi' => 'Được chứ, chữ nào?'],
            ['who' => '大卫', 'cn' => '"谢谢"的"谢"字，我觉得写不好。', 'vi' => 'Chữ "tạ" trong "cảm ơn", tôi thấy viết không đẹp.'],
            ['who' => '王小明', 'cn' => '你看，这个字是左中右结构，要写紧凑一点儿。', 'vi' => 'Bạn xem, chữ này kết cấu trái giữa phải, phải viết chặt chẽ một chút.'],
            ['who' => '大卫', 'cn' => '哦，我明白了。你的解释真清楚。', 'vi' => 'Ồ, tôi hiểu rồi. Giải thích của bạn thật rõ ràng.'],
            ['who' => '王小明', 'cn' => '不客气，互相帮助是应该的。', 'vi' => 'Không có gì, giúp đỡ lẫn nhau là điều nên làm.'],
            ['who' => '安娜', 'cn' => '王小明，我有个语法问题想问你。', 'vi' => 'Vương Tiểu Minh, tôi có câu hỏi ngữ pháp muốn hỏi bạn.'],
            ['who' => '王小明', 'cn' => '你说，什么问题？', 'vi' => 'Bạn nói đi, vấn đề gì?'],
            ['who' => '安娜', 'cn' => '"了"什么时候用在句尾？什么时候用在动词后？', 'vi' => '"了" khi nào dùng ở cuối câu? Khi nào dùng sau động từ?'],
            ['who' => '王小明', 'cn' => '这是一个好问题。句尾的"了"表示变化，动词后的"了"表示完成。', 'vi' => 'Đây là một câu hỏi hay. "了" cuối câu chỉ sự thay đổi, "了" sau động từ chỉ sự hoàn thành.'],
            ['who' => '安娜', 'cn' => '我明白了，谢谢你！', 'vi' => 'Tôi hiểu rồi, cảm ơn bạn!'],
        ],
        'grammar' => [
            ['point' => 'Tân ngữ kép: 给 + Người + Vật', 'explain' => 'Một số động từ trong tiếng Trung có thể mang hai tân ngữ: tân ngữ chỉ người và tân ngữ chỉ vật. Cấu trúc: Động từ + Tân ngữ người + Tân ngữ vật. Các động từ phổ biến: 给 (cho), 告诉 (nói cho), 教 (dạy), 借 (cho mượn). Ví dụ: 我给你一本书 (Tôi cho bạn một cuốn sách). 老师教我们汉语 (Cô giáo dạy chúng tôi tiếng Trung). Tân ngữ chỉ người luôn đứng trước tân ngữ chỉ vật.', 'examples' => ['我给你一本书。Tôi cho bạn một cuốn sách.', '老师教我们汉语。Cô giáo dạy chúng tôi tiếng Trung.', '他告诉我一个消息。Anh ấy nói cho tôi một tin.']],
            ['point' => 'Cấu trúc 互相 + Động từ (lẫn nhau)', 'explain' => '互相 là phó từ mang nghĩa "lẫn nhau, qua lại", đứng trước động từ song âm tiết. Cấu trúc: 互相 + Động từ. Ví dụ: 互相帮助 (giúp đỡ lẫn nhau), 互相学习 (học tập lẫn nhau), 互相尊重 (tôn trọng lẫn nhau). 互相 không thể dùng với động từ đơn âm tiết. Với động từ đơn âm, dùng 相 tạo từ ghép như 相见 (gặp nhau), 相爱 (yêu nhau). 互相 là một trong những cách diễn đạt quan trọng thể hiện tinh thần tập thể.', 'examples' => ['我们要互相帮助。Chúng ta phải giúp đỡ lẫn nhau.', '同学们互相学习。Các bạn cùng lớp học tập lẫn nhau.', '他们互相不认识。Họ không quen biết nhau.']],
            ['point' => 'Cách dùng 给 (cho / tặng)', 'explain' => '给 là một động từ đa năng, nghĩa cơ bản là "cho, tặng". Nó có thể dùng làm động từ chính: 我给你一本书 (Tôi cho bạn một quyển sách). Hoặc dùng làm giới từ chỉ đối tượng: 我给你打电话 (Tôi gọi điện cho bạn). Trong cấu trúc 给 + Người + Động từ, 给 đóng vai trò giới từ chỉ người nhận hành động. Phân biệt: 送 (tặng — lịch sự hơn), 给 (cho — trung tính). 给我 thường được dùng như "cho tôi" trong yêu cầu.', 'examples' => ['我给他打电话。Tôi gọi điện cho anh ấy.', '请给我一杯水。Xin cho tôi một cốc nước.', '他送给我一本书。Anh ấy tặng tôi một cuốn sách.']],
        ],
        'pronunciation' => ['focus' => 'tone pairs 4-3', 'drill' => ['hàn yǔ', 'kè běn', 'fù xí', 'gù shì', 'hòu tiān', 'jì zhě', 'kè kǔ', 'mù biāo']],
        'vocab' => [
