            ['w' => '帮助', 'p' => 'bāngzhù', 'm' => 'giúp đỡ', 'pos' => '动词,名词', 'ex' => ['谢谢你的帮助。Cảm ơn sự giúp đỡ của bạn.', '同学之间应该互相帮助。Giữa các bạn học nên giúp đỡ lẫn nhau.']],
            ['w' => '同桌', 'p' => 'tóngzhuō', 'm' => 'bạn cùng bàn', 'pos' => '名词', 'ex' => ['他是我的同桌。Anh ấy là bạn cùng bàn của tôi.', '我和同桌关系很好。Tôi và bạn cùng bàn rất thân.']],
