    17 => [
        'title' => 'Bài 17: 每天坚持锻炼 - Mỗi ngày kiên trì rèn luyện',
        'text' => '我的爸爸今年四十五岁，以前他身体不太好，常常感冒。后来医生告诉他："你要多锻炼身体，这样才能更健康。"爸爸听了医生的话，决定每天坚持锻炼。一开始，爸爸每天早上六点起来去公园跑步。第一天他跑了不到一公里就跑不动了，气喘吁吁地回家。妈妈笑着说："你平时不运动，现在突然跑步，当然不行了。要慢慢来。"爸爸觉得妈妈说得有道理，于是改为快走。他每天快走四十分钟，坚持了一个月。一个月以后，他觉得自己的体力好了很多，又开始慢跑。从每天跑一公里到每天跑三公里，爸爸坚持了半年。半年后，爸爸的身体明显变好了，体重也减了五公斤。他高兴地对我和妈妈说："我现在觉得浑身有劲，工作的时候也不容易累了。"看到爸爸的变化，妈妈也开始运动了。妈妈选择去健身房，她每周去三次，做瑜伽和跳操。周末的时候，我们一家人经常一起去爬山或者骑自行车。体育运动不仅让我们的身体更健康，也让我们的家庭生活更加快乐。现在我每天放学后也会运动一会儿，打打篮球或者跑跑步。我觉得运动是一件很有意义的事情，要一直坚持下去。',
        'dialogues' => [
            ['who' => '爸爸', 'cn' => '医生说我应该多锻炼，我决定每天去跑步。', 'vi' => 'Bác sĩ nói tôi nên tập thể dục nhiều, tôi quyết định chạy bộ mỗi ngày.'],
            ['who' => '妈妈', 'cn' => '你以前从来不运动，能坚持吗？', 'vi' => 'Trước đây anh chưa bao giờ vận động, có kiên trì được không?'],
            ['who' => '爸爸', 'cn' => '为了健康，我一定要坚持。', 'vi' => 'Vì sức khỏe, tôi nhất định phải kiên trì.'],
            ['who' => '妈妈', 'cn' => '那你先快走开始，不要一下子跑太远。', 'vi' => 'Vậy anh bắt đầu bằng đi bộ nhanh trước, đừng chạy xa quá một lúc.'],
            ['who' => '王小明', 'cn' => '爸爸，我和你一起运动吧！', 'vi' => 'Bố, con cùng tập với bố nhé!'],
            ['who' => '爸爸', 'cn' => '好啊！以后我们父子一起锻炼。', 'vi' => 'Tốt quá! Từ nay hai bố con cùng rèn luyện.'],
            ['who' => '妈妈', 'cn' => '我去健身房做瑜伽，你们去不去？', 'vi' => 'Mẹ đến phòng tập làm yoga, các anh có đi không?'],
            ['who' => '爸爸', 'cn' => '我就不去了，我习惯在外面跑步。', 'vi' => 'Bố không đi đâu, bố quen chạy bộ ngoài trời.'],
            ['who' => '王小明', 'cn' => '周末我们一家人去爬山吧！', 'vi' => 'Cuối tuần cả nhà mình đi leo núi nhé!'],
            ['who' => '妈妈', 'cn' => '好主意！运动对身体好，对心情也好。', 'vi' => 'Ý kiến hay! Vận động tốt cho sức khỏe và tâm trạng.'],
        ],
        'grammar' => [
            ['point' => 'Cấu trúc 从...到... (từ... đến...)', 'explain' => '从...到... diễn tả phạm vi từ điểm đầu đến điểm cuối, có thể dùng cho thời gian, không gian hoặc số lượng. Cấu trúc: 从 + Điểm bắt đầu + 到 + Điểm kết thúc. Ví dụ: 从星期一到星期五 (từ thứ hai đến thứ sáu), 从北京到上海 (từ Bắc Kinh đến Thượng Hải). Khi dùng với thời gian, cấu trúc này diễn tả một khoảng thời gian liên tục. Cũng có thể dùng để chỉ mức độ: 从一到十 (từ một đến mười), 从好到坏 (từ tốt đến xấu).', 'examples' => ['从星期一到星期五我都上班。Từ thứ hai đến thứ sáu tôi đều đi làm.', '从北京到上海坐高铁很快。Từ Bắc Kinh đến Thượng Hải đi tàu cao tốc rất nhanh.', '他从早上八点工作到晚上六点。Anh ấy làm việc từ tám giờ sáng đến sáu giờ tối.']],
            ['point' => 'Kết quả bổ ngữ ( động từ + 到 / 完 / 好 )', 'explain' => 'Bổ ngữ kết quả là một cấu trúc quan trọng, theo sau động từ để chỉ kết quả của hành động. Các bổ ngữ thường gặp: 到 (đến nơi, đạt được), 完 (xong, hết), 好 (xong, hoàn thành tốt), 懂 (hiểu). Cấu trúc: Động từ + Bổ ngữ. Ví dụ: 看到 (nhìn thấy), 做完 (làm xong), 听懂 (nghe hiểu). Phủ định dùng 没: 没看到 (không thấy), 没做完 (chưa làm xong). Bổ ngữ kết quả là một trong những đặc điểm quan trọng của ngữ pháp tiếng Trung.', 'examples' => ['我看到了长城。Tôi đã nhìn thấy Vạn Lý Trường Thành.', '作业做完了。Bài tập làm xong rồi.', '我听懂了他的话。Tôi nghe hiểu lời anh ấy nói.']],
            ['point' => 'Cấu trúc 从...以后 / 以后 (sau khi)', 'explain' => '以后 có nghĩa là "sau", "sau khi", chỉ thời gian trong tương lai hoặc sau một mốc thời gian. Cấu trúc: Thời gian / Hành động + 以后. Ví dụ: 三个月以后 (ba tháng sau), 毕业以后 (sau khi tốt nghiệp). 以后 cũng có thể đứng một mình ở đầu câu mang nghĩa "về sau" hoặc "sau này". Lưu ý: 以后 chỉ tương lai, còn 后来 chỉ quá khứ. 以后 khác với 然后 (sau đó — chỉ thứ tự hành động).', 'examples' => ['三个月以后，他的身体变好了。Ba tháng sau, sức khỏe anh ấy đã tốt hơn.', '毕业以后我想去中国工作。Sau khi tốt nghiệp tôi muốn đi làm ở Trung Quốc.', '以后你要多锻炼。Sau này em phải tập thể dục nhiều hơn.']],
