    18 => [
        'title' => 'Bài 18: 让我考得不好 - Khiến tôi thi không tốt',
        'text' => '上个星期我们进行了期中考试，考试内容是之前学过的所有语法和词汇。为了这次考试，我复习了整整一个星期。每天放学回家以后，我都花两个小时复习功课。我把学过的生词写了好几遍，把语法点也重新看了一遍。我还做了很多练习题，觉得自己准备得还不错。考试那天，我有一点儿紧张。拿到试卷以后，我先看了一下题目，发现前面的部分不难，都是我会的。但是做到最后一部分的时候，我遇到了一篇很长的阅读理解，里面有很多我不认识的词。我看了半天也没有完全看懂。我有点儿着急了，心想："这篇怎么这么难？"因为太紧张了，我后面的题目也没有做好。考试结束以后，我很难过。我觉得自己考得不好。回家以后，我把考试的情况告诉了妈妈。妈妈安慰我说："不要难过，一次考试没有考好不代表什么。重要的是你要找到原因。"我想了想，发现自己平时阅读太少了，所以遇到长文章就看不懂。而且考试的时候太紧张，影响了我的发挥。妈妈建议我以后每天多读一些中文文章，提高阅读能力。从那天开始，我每天读一篇中文短文，还做读书笔记。我相信只要我坚持下去，下一次考试一定能考好。',
        'dialogues' => [
            ['who' => '王小明', 'cn' => '妈妈，我这次考试没考好。', 'vi' => 'Mẹ ơi, lần này con thi không tốt.'],
            ['who' => '妈妈', 'cn' => '怎么了？是题目太难了吗？', 'vi' => 'Sao vậy? Đề thi khó quá à?'],
            ['who' => '王小明', 'cn' => '后面的阅读题太难了，很多词我都不认识。', 'vi' => 'Phần đọc hiểu phía sau khó quá, nhiều từ con không biết.'],
            ['who' => '妈妈', 'cn' => '你复习的时候没有复习到吗？', 'vi' => 'Lúc ôn bài con không ôn đến à?'],
            ['who' => '王小明', 'cn' => '我复习了语法和生词，但是阅读需要平时的积累。', 'vi' => 'Con đã ôn ngữ pháp và từ mới, nhưng đọc hiểu cần tích lũy hàng ngày.'],
            ['who' => '妈妈', 'cn' => '没关系，找到原因就好了。以后多读一些中文文章吧。', 'vi' => 'Không sao, tìm được nguyên nhân là tốt rồi. Sau này con đọc thêm nhiều bài văn tiếng Trung nhé.'],
            ['who' => '王小明', 'cn' => '嗯，我打算每天读一篇中文短文。', 'vi' => 'Dạ, con dự tính mỗi ngày đọc một bài văn ngắn tiếng Trung.'],
            ['who' => '妈妈', 'cn' => '你能这样想就对了。妈妈相信你下次一定能考好。', 'vi' => 'Con nghĩ được vậy là đúng. Mẹ tin lần sau con nhất định sẽ thi tốt.'],
            ['who' => '王小明', 'cn' => '谢谢妈妈。我下次一定会努力的！', 'vi' => 'Cảm ơn mẹ. Lần sau con nhất định sẽ cố gắng!'],
        ],
        'grammar' => [
            ['point' => '让 + Người + Động từ (khiến / để cho)', 'explain' => '让 có hai nghĩa chính: (1) khiến, làm cho (gây ra kết quả) và (2) cho phép, để cho. Cấu trúc: 让 + Người + Động từ. Ví dụ: 让我考得不好 (Khiến tôi thi không tốt — nghĩa gây ra). 妈妈让我去超市 (Mẹ bảo tôi đi siêu thị — nghĩa sai khiến). 让我试试 (Để tôi thử — nghĩa cho phép). Trong câu bị động, 让 cũng được dùng như 被: 书让他拿走了 (Sách bị anh ấy lấy đi).', 'examples' => ['这件事让我很难过。Việc này làm tôi rất buồn.', '妈妈让我去买菜。Mẹ bảo tôi đi mua rau.', '让我想想。Để tôi nghĩ xem.']],
            ['point' => 'Bổ ngữ khả năng: Động từ + 得/不 + Bổ ngữ', 'explain' => 'Bổ ngữ khả năng biểu thị khả năng có thể hoặc không thể đạt được kết quả của hành động. Cấu trúc khẳng định: Động từ + 得 + Bổ ngữ. Phủ định: Động từ + 不 + Bổ ngữ. Ví dụ: 考得好 (thi tốt), 考不好 (thi không tốt), 看得懂 (xem hiểu), 看不懂 (xem không hiểu). Đây là một cấu trúc quan trọng khác biệt với bổ ngữ kết quả (chỉ kết quả thực tế). Bổ ngữ khả năng chỉ tiềm năng.', 'examples' => ['这次考试我考得不好。Kỳ thi này tôi thi không tốt.', '我看得懂中文。Tôi đọc hiểu tiếng Trung.', '他听不懂广东话。Anh ấy nghe không hiểu tiếng Quảng Đông.']],
            ['point' => 'Cách nói về kết quả: 考得怎么样?', 'explain' => 'Để hỏi về kết quả của một hành động, dùng cấu trúc: Động từ + 得 + 怎么样? Ví dụ: 考得怎么样? (Thi thế nào? / Kết quả thi ra sao?). Trong câu trả lời, dùng Động từ + 得 + Tính từ. Ví dụ: 考得很好 (thi rất tốt), 考得不好 (thi không tốt). Lưu ý sau 得 là tính từ hoặc cụm tính từ, không phải động từ. Cấu trúc này dùng để đánh giá kết quả hành động.', 'examples' => ['你考得怎么样？Bạn thi thế nào?', '他说得很好。Anh ấy nói rất tốt.', '你写得真漂亮！Bạn viết thật đẹp!']],
        ],
