            ['w' => '题目', 'p' => 'tímù', 'm' => 'đề mục, câu hỏi', 'pos' => '名词', 'ex' => ['这道题目很难。Câu hỏi này rất khó.', '一共有五个题目。Tổng cộng có năm câu hỏi.']],
