    19 => [
        'title' => 'Bài 19: 你家离公司远吗 - Nhà bạn cách công ty xa không',
        'text' => '我找到了一份新工作，在一家贸易公司做市场专员。公司地址在市中心，离我家很远。从我家到公司坐地铁需要一个小时，如果坐公交需要更长时间，大概一个半小时。第一天去上班的时候，我提前两个小时就出门了。我坐地铁到了公司附近的地铁站，然后走路十分钟就到公司了。到了公司以后，经理问我："你家离公司远吗？"我说："挺远的，坐地铁要一个小时。"经理说："那挺远的。你每天来回需要两个小时，累不累？"我说："还好，习惯了就好了。"经理告诉我公司有交通补贴，每个月可以报销一部分交通费。而且公司九点上班，我可以选择八点半到九点之间到。这样我可以避开地铁高峰时间。我问同事小张："你家离公司远不远？"小张说："我家就在公司附近，走路十五分钟就到了。所以我每天走路上下班，既环保又省钱。"我羡慕地说："真近啊！那你每天可以多睡一会儿了。"小张笑着说："是啊，所以我每天都很有精神。"后来我和几个同事聊天，发现大家住的地方都不一样。有的人住得近，有的人住得远。最远的同事住在郊区，每天坐火车来上班，单程就要两个小时。相比之下，我一个小时的路程还算可以的。我想，虽然路上花的时间多了一些，但是在地铁上我可以看书、听音乐，也可以复习当天学的汉语，也不算浪费时间。',
        'dialogues' => [
            ['who' => '经理', 'cn' => '王小明，你家离公司远吗？', 'vi' => 'Vương Tiểu Minh, nhà bạn cách công ty xa không?'],
            ['who' => '王小明', 'cn' => '挺远的，坐地铁要一个小时。', 'vi' => 'Khá xa, đi tàu điện ngầm mất một tiếng.'],
            ['who' => '经理', 'cn' => '那你每天怎么来上班？', 'vi' => 'Vậy bạn đến công ty bằng gì mỗi ngày?'],
            ['who' => '王小明', 'cn' => '我坐地铁来，出了地铁站走十分钟就到了。', 'vi' => 'Tôi đi tàu điện ngầm, ra khỏi ga đi bộ mười phút là đến.'],
            ['who' => '经理', 'cn' => '路上累不累？', 'vi' => 'Trên đường có mệt không?'],
            ['who' => '王小明', 'cn' => '还可以，我已经习惯了。', 'vi' => 'Cũng tạm được, tôi đã quen rồi.'],
            ['who' => '小张', 'cn' => '我家就在公司附近，走路十五分钟。', 'vi' => 'Nhà tôi ở gần công ty, đi bộ mười lăm phút.'],
            ['who' => '王小明', 'cn' => '真近啊！好羡慕你。', 'vi' => 'Gần thật! Thật ghen tị với bạn.'],
            ['who' => '小张', 'cn' => '是啊，我每天可以八点半起床。', 'vi' => 'Phải đấy, tôi có thể dậy lúc tám rưỡi mỗi ngày.'],
            ['who' => '王小明', 'cn' => '最远的同事住在哪儿？', 'vi' => 'Đồng nghiệp ở xa nhất sống ở đâu?'],
            ['who' => '同事', 'cn' => '我住在郊区，每天坐火车来上班。', 'vi' => 'Tôi sống ở ngoại ô, mỗi ngày đi tàu hỏa đến công ty.'],
        ],
        'grammar' => [
            ['point' => 'Cấu trúc với 离 (cách, xa)', 'explain' => '离 là giới từ chỉ khoảng cách giữa hai địa điểm. Cấu trúc: A + 离 + B + Tính từ / Số lượng. Ví dụ: 我家离公司很远 (Nhà tôi cách công ty rất xa). 学校离地铁站很近 (Trường học cách ga tàu điện ngầm rất gần). 离 cũng có thể dùng với thời gian hoặc trừu tượng: 离考试还有三天 (Còn ba ngày nữa là thi). Trong câu hỏi, dùng: A + 离 + B + 远不远/多远. Lưu ý: 离 chỉ khoảng cách, không phải hướng đi.', 'examples' => ['我家离公司很远。Nhà tôi cách công ty rất xa.', '学校离地铁站很近。Trường cách ga tàu điện ngầm rất gần.', '离考试还有三天。Còn ba ngày nữa là thi.']],
            ['point' => 'Cấu trúc 从...到... + 需要 + Thời gian', 'explain' => 'Để nói về thời gian di chuyển từ nơi này đến nơi khác, dùng: 从 + Địa điểm A + 到 + Địa điểm B + 需要 + Thời gian. Có thể lược bỏ 需要 và đặt thời gian sau 到. Ví dụ: 从家到公司需要一个小时 (Từ nhà đến công ty cần một tiếng). 从北京到上海坐高铁四个半小时 (Từ Bắc Kinh đến Thượng Hải đi tàu cao tốc mất bốn tiếng rưỡi). Cấu trúc này rất thông dụng khi nói về lộ trình và thời gian di chuyển.', 'examples' => ['从家到公司需要一个小时。Từ nhà đến công ty cần một tiếng.', '从北京到上海坐飞机两个小时。Từ Bắc Kinh đến Thượng Hải đi máy bay mất hai tiếng.', '从这里到地铁站走路五分钟。Từ đây đến ga tàu điện ngầm đi bộ năm phút.']],
            ['point' => 'A 跟 B + Tính từ + 差不多/一样 (so sánh ngang bằng)', 'explain' => 'Để diễn tả hai đối tượng giống nhau hoặc tương đương về một đặc điểm, dùng: A + 跟/和 + B + 一样/差不多 + Tính từ. 一样 (giống nhau) và 差不多 (gần giống, xấp xỉ). Ví dụ: 我的家和你的家差不多大 (Nhà tôi và nhà bạn lớn gần bằng nhau). 他跟我一样高 (Anh ấy cao bằng tôi). 跟 thường dùng trong khẩu ngữ hơn 和. Phủ định: 跟...不一样.', 'examples' => ['他跟我一样高。Anh ấy cao bằng tôi.', '这条路跟那条路差不多长。Con đường này dài xấp xỉ con đường kia.', '我的手机跟你的不一样。Điện thoại của tôi không giống của bạn.']],
        ],
