    20 => [
        'title' => 'Bài 20: 别找了，手机在桌子上 - Đừng tìm nữa, điện thoại ở trên bàn',
        'text' => '今天早上起床以后，我发现自己找不到手机了。我把书包翻了一遍，没有。又把衣服口袋都找了一遍，也没有。我有点儿着急了，因为手机里有很多重要的信息和联系方式。我在房间里到处找，床上、桌子下、抽屉里都找了，还是找不到。妈妈看到我在房间里转来转去，问我："你在找什么呢？"我说："妈妈，我的手机找不到了！我到处都找了，就是找不到。"妈妈笑着说："别找了，你的手机不是在桌子上吗？"我回头一看，手机就安安静静地躺在桌子上呢！原来昨天晚上我看完手机以后随手放在桌子上，忘了收起来。早上起来以后太着急，竟然没有看到。我松了一口气，对妈妈说："谢谢妈妈！我都急死了。"妈妈说："你看你，总是丢三落四的。重要的东西要放在固定的地方，这样就不会找不到了。"我觉得妈妈说得对。我常常找不到东西，有时候是钥匙，有时候是钱包，有时候是学生证。小张告诉我一个好方法：把常用的东西都放在固定的位置，用完了就放回去。这样下次用的时候就知道在哪儿找了。我听了小张的建议，把手机放在书桌右边抽屉里，钥匙挂在门口的挂钩上，钱包放在书包的同一个夹层里。这样一来，我就再也没有找不到东西了。这个好习惯让我的生活方便了很多。',
        'dialogues' => [
            ['who' => '王小明', 'cn' => '妈妈，我的手机找不到了！', 'vi' => 'Mẹ ơi, điện thoại của con tìm không thấy!'],
            ['who' => '妈妈', 'cn' => '别着急，你好好想想放哪儿了。', 'vi' => 'Đừng lo, con nghĩ xem để ở đâu rồi.'],
            ['who' => '王小明', 'cn' => '我到处都找了，床上、桌子上、书包里都没有。', 'vi' => 'Con tìm khắp nơi rồi, trên giường, trên bàn, trong cặp sách đều không có.'],
            ['who' => '妈妈', 'cn' => '你看，手机不是在桌子上吗？', 'vi' => 'Con xem, điện thoại không phải ở trên bàn à?'],
            ['who' => '王小明', 'cn' => '啊！真的在桌子上！我刚才怎么没看到。', 'vi' => 'A! Thật sự ở trên bàn! Sao lúc nãy con không nhìn thấy.'],
            ['who' => '妈妈', 'cn' => '你总是丢三落四的，以后要放好东西。', 'vi' => 'Con hay thất lạc đồ đạc quá, sau này phải để đồ cẩn thận.'],
            ['who' => '王小明', 'cn' => '我知道了。以后用完手机就放回原处。', 'vi' => 'Con biết rồi. Sau này dùng xong điện thoại sẽ để lại chỗ cũ.'],
            ['who' => '小张', 'cn' => '我也有个方法，把常用的东西放在固定的位置。', 'vi' => 'Tôi cũng có cách, để đồ hay dùng ở vị trí cố định.'],
            ['who' => '王小明', 'cn' => '好办法！这样下次就不会找不到了。', 'vi' => 'Cách hay! Vậy lần sau sẽ không tìm không thấy nữa.'],
            ['who' => '小张', 'cn' => '对，养成好习惯很重要。', 'vi' => 'Đúng vậy, hình thành thói quen tốt rất quan trọng.'],
        ],
        'grammar' => [
            ['point' => '别 + Động từ + 了 (đừng làm gì nữa)', 'explain' => '别 là phó từ phủ định mệnh lệnh, nghĩa là "đừng". Cấu trúc: 别 + Động từ (+ 了). 了 ở cuối câu thêm sắc thái "nữa" — ngăn cản một hành động đang xảy ra hoặc sắp xảy ra. Ví dụ: 别找了 (Đừng tìm nữa). 别哭了 (Đừng khóc nữa). 别去 (Đừng đi). 别 so với 不要: 不要 mang sắc thái mạnh hơn (không được), 别 nhẹ nhàng hơn. 别 cũng được dùng trong các câu khuyên bảo: 别担心 (Đừng lo), 别着急 (Đừng vội).', 'examples' => ['别找了，手机在这里。Đừng tìm nữa, điện thoại ở đây.', '别着急，慢慢来。Đừng vội, từ từ thôi.', '别说话了！Đừng nói chuyện nữa!']],
            ['point' => 'Cấu trúc tồn tại: Địa điểm + 有 / 是 + Người / Vật', 'explain' => 'Để nói về sự tồn tại của một đối tượng tại một địa điểm, dùng 有 hoặc 是. 有 ở địa điểm có: 桌子上有一本书 (Trên bàn có một cuốn sách). 是 ở địa điểm xác định: 桌子上是手机 (Trên bàn là cái điện thoại — ngụ ý không phải thứ khác). Khi dùng trong ngữ cảnh tìm đồ, 在 thường được dùng để chỉ vị trí cụ thể: 手机在桌子上 (Điện thoại ở trên bàn). 在 là động từ tồn tại chỉ vị trí.', 'examples' => ['桌子上有一本书。Trên bàn có một cuốn sách.', '手机在桌子上。Điện thoại ở trên bàn.', '书包里是什么？Trong cặp sách là gì?']],
            ['point' => 'Bổ ngữ xu hướng phức: 出来, 起来, 回去', 'explain' => 'Bổ ngữ xu hướng phức được tạo thành từ động từ xu hướng đơn + 来/去. Các bổ ngữ thường gặp: 出来 (ra ngoài — từ trong ra ngoài), 起来 (lên — từ thấp lên cao), 回去 (trở về), 进来 (vào trong), 出去 (đi ra). Ví dụ: 拿出来 (lấy ra), 站起来 (đứng lên), 走回去 (đi về). Các bổ ngữ này diễn tả hướng của hành động so với người nói. 起来 còn được dùng để chỉ sự bắt đầu một hành động: 笑起来 (cười lên), 说起来 (nói về).', 'examples' => ['请把书拿出来。Xin hãy lấy sách ra.', '他站起来了。Anh ấy đứng dậy rồi.', '我想起来了！Tôi nhớ ra rồi!']],
        ],
        'pronunciation' => ['focus' => 'tone pairs 2-2', 'drill' => ['píng shí', 'huán qián', 'míng nián', 'qián nián', 'rén mín', 'tí qián', 'wán chéng', 'xué xí']],
        'vocab' => [
            ['w' => '别', 'p' => 'bié', 'm' => 'đừng, chớ', 'pos' => '副词', 'ex' => ['别找了。Đừng tìm nữa.', '别着急，慢慢来。Đừng vội, từ từ thôi.']],
            ['w' => '找', 'p' => 'zhǎo', 'm' => 'tìm', 'pos' => '动词', 'ex' => ['我在找手机。Tôi đang tìm điện thoại.', '你找什么？Bạn tìm gì?']],
            ['w' => '手机', 'p' => 'shǒujī', 'm' => 'điện thoại di động', 'pos' => '名词', 'ex' => ['我的手机没电了。Điện thoại của tôi hết pin rồi.', '手机在桌子上。Điện thoại ở trên bàn.']],
            ['w' => '桌子', 'p' => 'zhuōzi', 'm' => 'cái bàn', 'pos' => '名词', 'ex' => ['桌子上有一本书。Trên bàn có một cuốn sách.', '把书放在桌子上。Để sách lên bàn.']],
            ['w' => '钥匙', 'p' => 'yàoshi', 'm' => 'chìa khóa', 'pos' => '名词', 'ex' => ['我找不到钥匙了。Tôi tìm không thấy chìa khóa.', '钥匙在门口挂着。Chìa khóa treo ở cửa.']],
