    21 => [
        'title' => 'Bài 21: 周末你有什么打算 - Cuối tuần bạn có dự định gì',
        'text' => '星期五下午，最后一节课结束以后，同学们都在讨论周末的安排。大卫问我："王小明，周末你有什么打算？"我说："这个周末我打算去图书馆看书，然后跟朋友一起去看电影。你呢？"大卫说："我打算去爬山。听说北京的香山公园风景很美，我想去看看。"安娜听到了我们的对话，走过来问："大卫，你打算怎么去香山？"大卫说："我打算坐公交车去。"安娜说："坐公交车太慢了，建议你坐地铁去。地铁很快，不会堵车。"大卫点点头说："好主意，那我就坐地铁去。"我问安娜："你周末有什么打算？"安娜说："我周末打算在家里复习汉语，下个星期有考试。"我说："你真认真啊。那周末我就不打扰你了，考完试我们再一起玩。"安娜说："好的，考完试我请你们吃饭。"大卫笑着说："那我可记住了！"大家都很开心。放学回家的路上，我又想了想周末的计划。除了看书和看电影，我还可以做点什么。对了，妈妈让我周末去超市买一些东西。我还有一篇作文没写，是老师布置的关于"我的梦想"的作文。看来这个周末的事情也不少。不过星期五晚上我是自由的，可以好好放松一下。',
        'dialogues' => [
            ['who' => '大卫', 'cn' => '王小明，周末你有什么打算？', 'vi' => 'Vương Tiểu Minh, cuối tuần bạn có dự định gì?'],
            ['who' => '王小明', 'cn' => '我打算去图书馆看书，然后去看电影。', 'vi' => 'Tôi định đi thư viện đọc sách, sau đó đi xem phim.'],
            ['who' => '大卫', 'cn' => '我想去香山公园爬山，你去过吗？', 'vi' => 'Tôi muốn đi Công viên Hương Sơn leo núi, bạn đã đi chưa?'],
            ['who' => '王小明', 'cn' => '去过一次，秋天的香山特别漂亮。', 'vi' => 'Đã đi một lần, Hương Sơn mùa thu rất đẹp.'],
            ['who' => '安娜', 'cn' => '大卫，你打算怎么去？', 'vi' => 'David, bạn định đi bằng gì?'],
