            ['who' => '大卫', 'cn' => '好，我听你的。安娜，你周末做什么？', 'vi' => 'Được, tôi nghe bạn. Anna, cuối tuần bạn làm gì?'],
            ['who' => '安娜', 'cn' => '我周末在家复习，下星期要考试。', 'vi' => 'Cuối tuần tôi ở nhà ôn bài, tuần sau có thi.'],
            ['who' => '王小明', 'cn' => '那你好好复习，考完试我们一起庆祝。', 'vi' => 'Vậy bạn ôn bài tốt nhé, thi xong chúng ta cùng ăn mừng.'],
        ],
        'grammar' => [
            ['point' => '打算 + Động từ (dự định làm gì)', 'explain' => '打算 vừa là động từ vừa là danh từ, mang nghĩa "dự định, có kế hoạch". Cấu trúc: 打算 + Động từ. Ví dụ: 我打算去北京 (Tôi dự định đi Bắc Kinh). 你周末打算做什么? (Cuối tuần bạn định làm gì?). 打算 khác với 计划: 计划 mang tính chính thức hơn, thường là kế hoạch cụ thể; 打算 mang tính dự định chung chung hơn. Câu hỏi thường gặp: 有什么打算? (Có dự định gì?).', 'examples' => ['我周末打算去图书馆。Cuối tuần tôi định đi thư viện.', '你有什么打算？Bạn có dự định gì?', '他打算明年去中国留学。Anh ấy dự định năm sau đi du học Trung Quốc.']],
            ['point' => 'Động từ lặp lại: 看看, 听听, 说说, 休息休息', 'explain' => 'Trong tiếng Trung, động từ có thể lặp lại để diễn tả hành động ngắn gọn, thử nghiệm hoặc nhẹ nhàng. Cách lặp: Động từ đơn âm: AA (看看 — xem xem, 听听 — nghe thử). Động từ song âm: ABAB (休息休息 — nghỉ ngơi một chút, 研究研究 — nghiên cứu thử). Lặp động từ làm cho câu nói trở nên mềm mại, thân thiện hơn. Thường dùng trong khẩu ngữ. Ví dụ: 让我看看 (Để tôi xem một chút).', 'examples' => ['让我看看。Để tôi xem một chút.', '我们出去走走。Chúng ta ra ngoài đi dạo.', '周末你可以好好休息休息。Cuối tuần bạn có thể nghỉ ngơi thư giãn.']],
            ['point' => 'Cấu trúc 除了...以外，还/也 (ngoài... ra, còn)', 'explain' => '除了...以外，还/也 biểu thị "ngoài cái đã nói ra, còn có cái khác". Cấu trúc: 除了 + Danh từ / Động từ + 以外，还/也 + Nội dung khác. Ví dụ: 除了看书，我还想去看电影 (Ngoài đọc sách, tôi còn muốn đi xem phim). 除了他以外，我们都去了 (Ngoài anh ấy ra, chúng tôi đều đi). Có thể lược bỏ 以外: 除了...还/也. Cấu trúc này rất thông dụng trong tiếng Trung.', 'examples' => ['除了看书，我还想看电影。Ngoài đọc sách, tôi còn muốn xem phim.', '除了他以外，我们都去了。Ngoài anh ấy ra, chúng tôi đều đi.', '除了汉语，他还会说英语。Ngoài tiếng Trung, anh ấy còn biết nói tiếng Anh.']],
        ],
