    22 => [
        'title' => 'Bài 22: 他什么时候回来 - Anh ấy khi nào trở về',
        'text' => '今天下午，我去了小李的家。小李是我的好朋友，我们约好了一起打球。可是到了他家以后，开门的却是小李的妈妈。阿姨对我说："小明来了啊！快进来坐。小李出去买东西了，还没回来。你先坐一会儿吧。"我进了屋，坐在沙发上等小李。等了一会儿，小李还没回来。我看了看时间，已经二十分钟了。我问阿姨："阿姨，小李什么时候出去的？"阿姨说："他半个小时以前出去的，说去买瓶水，怎么这么久还没回来？"我说："没关系，我再等一会儿。阿姨你知道他什么时候回来吗？"阿姨笑着说："他走的时候说一会儿就回来。估计快了吧。你先喝杯水，看看电视。"我喝了一杯水，看了会儿电视。又过了十分钟，小李终于回来了。他一进门就说："对不起对不起，路上遇到了另一个朋友，聊了一会儿，所以回来晚了。"我说："没关系，我还以为你出了什么事呢。"小李笑着说："我能出什么事啊。走吧，我们去打球！"我对阿姨说："阿姨，我们走了。"阿姨说："去吧，早点儿回来吃晚饭。"我说："知道了，阿姨再见！"到了球场，我问小李："你刚才去哪儿了？怎么去了那么久？"小李说："我去超市买水，遇到了小学同学张华，我们聊了很久。"我说："原来如此，难怪去了那么久。"',
