            ['who' => '王小明', 'cn' => '谢谢阿姨。阿姨，他什么时候回来？', 'vi' => 'Cảm ơn bác. Bác ơi, anh ấy khi nào về ạ?'],
            ['who' => '阿姨', 'cn' => '应该快了，你等一下。', 'vi' => 'Chắc sắp rồi, cháu đợi một lát.'],
