        'grammar' => [
            ['point' => 'Thời gian 以前 / 以后 (trước đây / sau này)', 'explain' => '以前 và 以后 được dùng để chỉ thời gian trước hoặc sau một mốc. Cấu trúc: Số lượng + Thời gian + 以前 (cách đây) hoặc Thời gian / Hành động + 以后 (sau khi). Ví dụ: 三天以前 (ba ngày trước), 半个小时以前 (nửa tiếng trước). 以后 có thể dùng ở đầu câu mang nghĩa "sau này": 以后你要注意 (Sau này bạn phải chú ý). 以后 đi sau mệnh đề chỉ thời gian: 毕业以后 (sau khi tốt nghiệp). Lưu ý: 以前 và 以后 trong cấu trúc thời gian tương đối linh hoạt.', 'examples' => ['半个小时以前他出去了。Nửa tiếng trước anh ấy đi ra ngoài.', '三天以前我见到了他。Ba ngày trước tôi gặp anh ấy.', '毕业以后我想去中国。Sau khi tốt nghiệp tôi muốn đi Trung Quốc.']],
            ['point' => 'Cấu trúc 不是...吗 (chẳng phải...sao?)', 'explain' => 'Cấu trúc 不是...吗 là câu hỏi phản vấn, mang hàm ý khẳng định ngược lại, nghĩa là "chẳng phải...sao?" hoặc "rõ ràng là...". Cấu trúc: 不是 + Thành phần + 吗? Ví dụ: 你不是走了吗? (Chẳng phải anh đã đi rồi sao?) — ngụ ý "tôi tưởng anh đã đi". 你的手机不是在桌子上吗? (Điện thoại của bạn chẳng phải ở trên bàn sao?) — ngụ ý "rõ ràng là ở trên bàn kìa". Câu này không cần trả lời, nó mang tính khẳng định.', 'examples' => ['你不是走了吗？Chẳng phải anh đã đi rồi sao?', '你的手机不是在桌子上吗？Điện thoại của bạn chẳng phải ở trên bàn sao?', '你不是中国人吗？难道不是吗？Chẳng phải bạn là người Trung Quốc sao?']],
            ['point' => 'Cách hỏi thời gian với 什么时候', 'explain' => '什么时候 là từ để hỏi về thời gian, nghĩa là "khi nào, lúc nào". Có thể đặt ở đầu câu hoặc cuối câu, hoặc sau chủ ngữ. Ví dụ: 他什么时候回来? (Anh ấy khi nào trở về?). 你什么时候去中国? (Bạn khi nào đi Trung Quốc?). 什么时候 khác với 几点: 几点 hỏi giờ cụ thể, 什么时候 hỏi thời gian nói chung (có thể là ngày, tháng, năm). Trong câu trả lời, dùng thời gian tương ứng.', 'examples' => ['他什么时候回来？Anh ấy khi nào trở về?', '你什么时候去中国？Bạn khi nào đi Trung Quốc?', '你什么时候有空？Bạn khi nào có thời gian rảnh?']],
