    23 => [
        'title' => 'Bài 23: 桌子上放着很多饮料 - Trên bàn để rất nhiều đồ uống',
        'text' => '今天是小李的生日，他邀请我们几个好朋友去他家开生日派对。下午三点，我和大卫、安娜一起来到小李家。小李的妈妈和爸爸很热情地欢迎我们。客厅的桌子上放着很多好吃的东西，有蛋糕、水果、饼干、糖果等等。桌子中间放着一个大蛋糕，上面写着"生日快乐"四个字。蛋糕旁边放着很多饮料，有可乐、雪碧、果汁和矿泉水，还有一瓶红酒。小李说："今天是我二十一岁生日，谢谢大家来参加我的派对。大家随便吃，不要客气！"大家都很开心地开始吃了起来。墙上挂着很多彩色气球，窗户上贴着小熊图案的窗花，整个客厅布置得很漂亮。桌子上还放着一个相册，里面是小李从小到大的照片。我们一边吃一边看照片。安娜看到小李小时候的照片，笑着说："你小时候好可爱啊！跟现在完全不一样。"大卫也开玩笑说："你看你小时候多瘦啊，现在胖多了。"小李假装生气地说："你们别取笑我了！"大家哈哈大笑。到了吃蛋糕的时候，小李许了一个愿望，然后吹灭了蜡烛。我们大家一起唱生日快乐歌，祝小李生日快乐。小李把蛋糕切成很多块，分给大家。蛋糕很甜很好吃。派对一直玩到晚上七点，我们才依依不舍地离开。',
        'dialogues' => [
            ['who' => '小李', 'cn' => '欢迎大家来参加我的生日派对！', 'vi' => 'Chào mừng mọi người đến dự tiệc sinh nhật của tôi!'],
            ['who' => '王小明', 'cn' => '生日快乐！这是送给你的礼物。', 'vi' => 'Sinh nhật vui vẻ! Đây là quà tặng cho bạn.'],
            ['who' => '小李', 'cn' => '谢谢！你太客气了。', 'vi' => 'Cảm ơn! Bạn khách sáo quá.'],
            ['who' => '安娜', 'cn' => '桌子上放着好多好吃的啊！', 'vi' => 'Trên bàn có nhiều đồ ăn ngon quá!'],
            ['who' => '小李', 'cn' => '大家别客气，随便吃。', 'vi' => 'Mọi người đừng khách sáo, cứ tự nhiên ăn nhé.'],
            ['who' => '大卫', 'cn' => '这是什么饮料？', 'vi' => 'Đây là đồ uống gì vậy?'],
            ['who' => '小李', 'cn' => '有可乐、雪碧、果汁，还有橙汁。', 'vi' => 'Có cola, sprite, nước trái cây và nước cam.'],
            ['who' => '安娜', 'cn' => '墙上挂着好多气球啊，真好看。', 'vi' => 'Trên tường treo nhiều bóng bay thật đẹp.'],
            ['who' => '小李', 'cn' => '是我和妈妈一起布置的。', 'vi' => 'Là tôi và mẹ cùng trang trí đấy.'],
            ['who' => '王小明', 'cn' => '快来切蛋糕吧！我们都等不及了。', 'vi' => 'Nhanh cắt bánh kem đi! Chúng tôi đều không chờ được nữa rồi.'],
            ['who' => '小李', 'cn' => '好，我先许个愿。', 'vi' => 'Được, tôi ước một điều đã.'],
        ],
        'grammar' => [
            ['point' => 'Cấu trúc tồn tại: Địa điểm + 着 + Người / Vật', 'explain' => 'Cấu trúc Địa điểm + Động từ + 着 + Người/Vật được dùng để miêu tả sự tồn tại hoặc trạng thái đang diễn ra tại một địa điểm. 着 biểu thị trạng thái tiếp diễn. Ví dụ: 桌子上放着很多饮料 (Trên bàn để rất nhiều đồ uống). 墙上挂着一张画 (Trên tường treo một bức tranh). 门口站着一个人 (Ở cửa đang đứng một người). Cấu trúc này thường dùng để mô tả khung cảnh, bố trí đồ đạc trong một không gian. Động từ thường là các động từ chỉ cách đặt, treo, để đồ.', 'examples' => ['桌子上放着很多饮料。Trên bàn để rất nhiều đồ uống.', '墙上挂着一张画。Trên tường treo một bức tranh.', '门口站着两个人。Ở cửa đang đứng hai người.']],
            ['point' => 'Cấu trúc 正在 / 在 + Động từ (đang làm gì)', 'explain' => '正在 và 在 được dùng để chỉ hành động đang diễn ra. 正在 nhấn mạnh hơn, 在 thông dụng hơn trong khẩu ngữ. Cấu trúc: Chủ ngữ + 正在/在 + Động từ. Ví dụ: 我正在吃饭 (Tôi đang ăn cơm). 他在看书 (Anh ấy đang đọc sách). Có thể thêm 呢 ở cuối câu: 他在看书呢。Phủ định: 没在 + Động từ. 正在 so với 着: 正在 nhấn mạnh hành động đang tiến hành, 着 nhấn mạnh trạng thái đang tiếp diễn.', 'examples' => ['我正在吃饭。Tôi đang ăn cơm.', '他在看书呢。Anh ấy đang đọc sách.', '别打扰他，他正在工作。Đừng làm phiền anh ấy, anh ấy đang làm việc.']],
            ['point' => 'Câu cảm thán với 好 / 多 / 真', 'explain' => 'Để bày tỏ cảm thán trong tiếng Trung, có thể dùng: 好 + Tính từ (好漂亮! — Đẹp quá!), 真 + Tính từ (真好看! — Thật đẹp!), 多 + Tính từ + 啊 (多漂亮啊! — Đẹp biết bao!). Các cấu trúc này thường đi kèm với 啊, 呀 ở cuối câu để tăng sắc thái cảm thán. 好 và 真 có thể dùng thay thế nhau trong nhiều trường hợp, nhưng 真 mang sắc thái mạnh hơn. Trong khẩu ngữ, 好 thông dụng hơn.', 'examples' => ['好漂亮啊！Đẹp quá!', '真好吃！Ngon thật!', '多可爱啊！Dễ thương biết bao!']],
        ],
        'pronunciation' => ['focus' => 'tone pairs 2-1', 'drill' => ['huí jiā', 'xué shēng', 'yóu dì', 'qián tiān', 'shí jiān', 'tú shū', 'wén zhāng', 'yán jiū']],
        'vocab' => [
