            ['w' => '放', 'p' => 'fàng', 'm' => 'đặt, để', 'pos' => '动词', 'ex' => ['桌子上放着蛋糕。Trên bàn để bánh kem.', '请把书放好。Xin hãy để sách gọn gàng.']],
            ['w' => '蛋糕', 'p' => 'dàngāo', 'm' => 'bánh kem, bánh gato', 'pos' => '名词', 'ex' => ['生日蛋糕很好吃。Bánh kem sinh nhật rất ngon.', '这个蛋糕很漂亮。Cái bánh kem này rất đẹp.']],
