            ['w' => '气球', 'p' => 'qìqiú', 'm' => 'bóng bay', 'pos' => '名词', 'ex' => ['墙上挂着彩色气球。Trên tường treo bóng bay màu sắc.', '小孩子喜欢气球。Trẻ em thích bóng bay.']],
            ['w' => '邀请', 'p' => 'yāoqǐng', 'm' => 'mời, yêu cầu', 'pos' => '动词', 'ex' => ['他邀请我去参加派对。Anh ấy mời tôi đi dự tiệc.', '谢谢你的邀请。Cảm ơn lời mời của bạn.']],
            ['w' => '参加', 'p' => 'cānjiā', 'm' => 'tham gia', 'pos' => '动词', 'ex' => ['我参加了他的生日派对。Tôi tham gia bữa tiệc sinh nhật của anh ấy.', '你想参加这个活动吗？Bạn muốn tham gia hoạt động này không?']],
            ['w' => '可爱', 'p' => 'kě\'ài', 'm' => 'đáng yêu, dễ thương', 'pos' => '形容词', 'ex' => ['这个小孩真可爱！Đứa bé này thật đáng yêu!', '你的猫很可爱。Mèo của bạn rất dễ thương.']],
            ['w' => '吹灭', 'p' => 'chuī miè', 'm' => 'thổi tắt', 'pos' => '动词', 'ex' => ['他吹灭了蜡烛。Anh ấy thổi tắt nến.', '请吹灭蜡烛再切蛋糕。Xin thổi tắt nến rồi cắt bánh.']],
            ['w' => '蜡烛', 'p' => 'làzhú', 'm' => 'nến', 'pos' => '名词', 'ex' => ['蛋糕上插着蜡烛。Trên bánh kem cắm nến.', '点蜡烛吧。Thắp nến đi.']],
            ['w' => '愿望', 'p' => 'yuànwàng', 'm' => 'ước nguyện', 'pos' => '名词', 'ex' => ['她许了一个愿望。Cô ấy đã ước một điều.', '希望你的愿望实现。Hy vọng ước nguyện của bạn thành hiện thực.']],
            ['w' => '布置', 'p' => 'bùzhì', 'm' => 'bày trí, trang trí', 'pos' => '动词', 'ex' => ['客厅布置得很漂亮。Phòng khách trang trí rất đẹp.', '我们一起布置会场。Chúng tôi cùng trang trí hội trường.']],
