    24 => [
        'title' => 'Bài 24: 她总是笑着跟客人说话 - Cô ấy luôn cười nói chuyện với khách',
        'text' => '我家小区门口有一家小超市，售货员是一位姓王的阿姨。王阿姨五十多岁，对人非常热情。她的脸上总是带着笑容，无论对谁都是笑眯眯的。每次我去买东西，她都会笑着跟我说："小朋友，今天想买什么呀？"她的服务态度特别好，所以附近的居民都喜欢去她的超市买东西。有一天，我陪妈妈去超市买东西。走进超市的时候，王阿姨正在笑着跟一位老奶奶说话。老奶奶问了很多问题，王阿姨一点儿也不着急，耐心地回答每一个问题，从头到尾都是笑着的。老奶奶买完东西以后很满意，对王阿姨说："你服务态度真好，我以后还来你这里买东西。"王阿姨笑着说："欢迎您下次再来！"妈妈对王阿姨说："您服务态度真好，怪不得生意这么好。"王阿姨笑着说："做生意就是要让客人开心。客人开心了，就会再来。"我听了以后觉得王阿姨说得很有道理。从那以后，我每次去超市都会跟王阿姨聊几句。王阿姨总是笑着跟我说话，让我觉得很温暖。她的笑容好像有魔力一样，让每一个来买东西的人都感到开心。我觉得王阿姨虽然做的是平凡的工作，但是她用自己的笑容温暖了很多人。我也要学王阿姨，做一个对人友好、常常微笑的人。',
        'dialogues' => [
            ['who' => '王阿姨', 'cn' => '小朋友，今天想买什么呀？', 'vi' => 'Cháu ơi, hôm nay muốn mua gì thế?'],
            ['who' => '王小明', 'cn' => '阿姨好！我买一瓶水。', 'vi' => 'Cháu chào bác! Cháu mua một chai nước.'],
            ['who' => '王阿姨', 'cn' => '好的，还要别的吗？', 'vi' => 'Được, còn cần gì nữa không?'],
            ['who' => '王小明', 'cn' => '不要了，谢谢阿姨。', 'vi' => 'Không ạ, cảm ơn bác.'],
            ['who' => '老奶奶', 'cn' => '姑娘，这个牛奶多少钱？', 'vi' => 'Cô ơi, sữa bò này bao nhiêu tiền?'],
            ['who' => '王阿姨', 'cn' => '这瓶牛奶八块钱。您还要别的吗？', 'vi' => 'Chai sữa này tám tệ. Bà còn cần gì nữa không?'],
            ['who' => '老奶奶', 'cn' => '有没有过期？', 'vi' => 'Có hết hạn không?'],
            ['who' => '王阿姨', 'cn' => '您放心，都是新鲜的，这周五才到期。', 'vi' => 'Bà yên tâm, đều tươi mới, đến thứ sáu này mới hết hạn.'],
            ['who' => '老奶奶', 'cn' => '好的，那我买两瓶。', 'vi' => 'Được, vậy tôi mua hai chai.'],
            ['who' => '王阿姨', 'cn' => '一共十六块。您慢走，欢迎下次再来！', 'vi' => 'Tổng cộng mười sáu tệ. Bà đi chậm nhé, chào mừng lần sau lại đến!'],
        ],
        'grammar' => [
            ['point' => 'Cấu trúc 总是 + Động từ (luôn luôn làm gì)', 'explain' => '总是 là phó từ chỉ tần suất, nghĩa là "luôn luôn", thường xuyên xảy ra. Đặt trước động từ hoặc tính từ. Cấu trúc: 总是 + Động từ / Tính từ. Ví dụ: 她总是笑 (Cô ấy luôn cười). 他总是迟到 (Anh ấy luôn đến muộn). 总是 khác với 一直 ở chỗ 总是 nhấn mạnh tần suất thường xuyên, còn 一直 nhấn mạnh trạng thái liên tục không gián đoạn. Trong câu phủ định, dùng 从不 (chưa bao giờ) hoặc 不常 (không thường xuyên).', 'examples' => ['她总是笑着跟客人说话。Cô ấy luôn cười nói chuyện với khách.', '他总是迟到。Anh ấy luôn đến muộn.', '我从来不抽烟。Tôi chưa bao giờ hút thuốc.']],
            ['point' => 'Động từ + 着 + Động từ (vừa làm gì vừa làm gì)', 'explain' => 'Cấu trúc Động từ 1 + 着 + Động từ 2 biểu thị hai hành động diễn ra đồng thời, trong đó động từ 1 là trạng thái của chủ thể khi thực hiện động từ 2. Ví dụ: 笑着说话 (cười nói chuyện — vừa cười vừa nói). 唱着歌做饭 (vừa hát vừa nấu ăn). 坐着看书 (ngồi đọc sách). Động từ 1 thường là động từ chỉ tư thế hoặc biểu cảm. Đây là một cấu trúc quan trọng diễn tả đồng thời hai hành động, khác với cấu trúc 一边...一边... cũng diễn tả hành động đồng thời.', 'examples' => ['她笑着跟客人说话。Cô ấy cười nói chuyện với khách.', '他坐着看书。Anh ấy ngồi đọc sách.', '我们听着音乐喝茶。Chúng tôi nghe nhạc uống trà.']],
            ['point' => 'Cấu trúc 无论...都... (bất luận...đều...)', 'explain' => '无论...都... diễn tả "bất luận thế nào, kết quả cũng như vậy". Cấu trúc: 无论 + Mệnh đề / Từ để hỏi + 都 + Kết quả. Ví dụ: 无论对谁都是笑眯眯的 (Bất luận với ai cũng đều cười tươi). 无论你去不去，我都去 (Dù bạn đi hay không, tôi cũng đi). 无论 đi kèm với các từ để hỏi như 谁, 什么, 怎么, 哪里 để tạo thành "bất kỳ ai/cái gì/thế nào/ở đâu... cũng...". Đây là cấu trúc nhấn mạnh tính phổ quát, không có ngoại lệ.', 'examples' => ['无论对谁她都很友好。Dù với ai cô ấy cũng rất thân thiện.', '无论多难，我都要学。Dù khó thế nào, tôi cũng phải học.', '无论你去哪里，我都跟你去。Dù bạn đi đâu, tôi cũng đi theo bạn.']],
        ],
        'pronunciation' => ['focus' => 'tone pairs 1-3', 'drill' => ['chū zǔ', 'fēi chǎng', 'sān diǎn', 'yīng yǔ', 'dāo zi', 'gōng sī', 'kāi shǐ', 'mā ma']],
        'vocab' => [
            ['w' => '总是', 'p' => 'zǒngshì', 'm' => 'luôn luôn', 'pos' => '副词', 'ex' => ['她总是笑着说话。Cô ấy luôn cười nói chuyện.', '他总是迟到。Anh ấy luôn đến muộn.']],
            ['w' => '笑着', 'p' => 'xiàozhe', 'm' => 'cười (đang cười)', 'pos' => '动词+着', 'ex' => ['她笑着跟我说话。Cô ấy cười nói chuyện với tôi.', '他笑着点了点头。Anh ấy cười gật đầu.']],
            ['w' => '态度', 'p' => 'tàidù', 'm' => 'thái độ', 'pos' => '名词', 'ex' => ['她的服务态度很好。Thái độ phục vụ của cô ấy rất tốt.', '你这是什么态度？Đây là thái độ gì của bạn?']],
            ['w' => '服务', 'p' => 'fúwù', 'm' => 'phục vụ, dịch vụ', 'pos' => '动词,名词', 'ex' => ['这家餐厅服务很好。Nhà hàng này phục vụ rất tốt.', '谢谢你的服务。Cảm ơn sự phục vụ của bạn.']],
            ['w' => '耐心', 'p' => 'nàixīn', 'm' => 'kiên nhẫn', 'pos' => '形容词,名词', 'ex' => ['她很有耐心。Cô ấy rất kiên nhẫn.', '你要耐心等待。Bạn phải kiên nhẫn chờ đợi.']],
