    25 => [
        'title' => 'Bài 25: 我最近越来越胖了 - Dạo này tôi càng ngày càng béo',
        'text' => '最近我发现自己越来越胖了。上个月买的裤子，现在穿起来有点儿紧了。我站在秤上一称，比上个月重了三公斤！我吓了一跳，心想："怎么胖了这么多？"我仔细想了想原因。首先，最近我吃得越来越多了。妈妈做的饭太好吃了，我每次都吃两碗米饭。而且最近我总是吃零食，尤其是晚上看电视的时候，不知不觉就吃了很多薯片和巧克力。其次，我运动越来越少了。以前我每天晚上都去跑步，但是这个月我几乎没有运动过。每天放学回家就坐在沙发上看手机，一看就是一两个小时。晚上还要吃夜宵，吃完就睡觉。这样不胖才怪呢！我决定要改变自己。从明天开始，我要少吃一点儿，每天只吃一碗米饭，不吃零食。我还要坚持运动，每天早上跑步半小时。周末的时候可以去游泳或者打球。我把这个计划告诉了妈妈。妈妈笑着说："你终于意识到要减肥了。但是减肥不能靠饿肚子，要科学饮食加运动。少吃零食，多吃水果蔬菜，主食可以适当减少，但不能不吃。"我觉得妈妈说得很对。于是我和妈妈一起制定了一个健康的减肥计划。我相信只要我坚持按照计划做，一定能瘦下来的。',
        'dialogues' => [
            ['who' => '王小明', 'cn' => '妈妈，我最近越来越胖了。', 'vi' => 'Mẹ ơi, dạo này con càng ngày càng béo.'],
            ['who' => '妈妈', 'cn' => '是吗？你上称了吗？', 'vi' => 'Thế à? Con lên cân chưa?'],
            ['who' => '王小明', 'cn' => '称了，比上个月重了三公斤。', 'vi' => 'Cân rồi, nặng hơn tháng trước ba kg.'],
            ['who' => '妈妈', 'cn' => '那你有没有想过为什么会胖？', 'vi' => 'Vậy con có nghĩ tại sao lại béo không?'],
            ['who' => '王小明', 'cn' => '我觉得是因为吃得多运动得少。', 'vi' => 'Con nghĩ là do ăn nhiều vận động ít.'],
            ['who' => '妈妈', 'cn' => '你知道原因就好。以后要少吃零食。', 'vi' => 'Con biết nguyên nhân là tốt. Sau này phải ăn ít đồ ăn vặt.'],
            ['who' => '王小明', 'cn' => '我打算从明天开始减肥。', 'vi' => 'Con dự tính từ ngày mai bắt đầu giảm cân.'],
            ['who' => '妈妈', 'cn' => '怎么减？说说你的计划。', 'vi' => 'Giảm thế nào? Nói kế hoạch của con nghe.'],
            ['who' => '王小明', 'cn' => '少吃米饭，不吃零食，每天运动。', 'vi' => 'Ăn ít cơm, không ăn vặt, vận động mỗi ngày.'],
            ['who' => '妈妈', 'cn' => '很好的计划，但是不能饿肚子。要健康减肥。', 'vi' => 'Kế hoạch tốt, nhưng không được để đói. Phải giảm cân lành mạnh.'],
            ['who' => '王小明', 'cn' => '我知道了！我会科学减肥的。', 'vi' => 'Con biết rồi! Con sẽ giảm cân khoa học.'],
        ],
        'grammar' => [
            ['point' => 'Cấu trúc 越来越 + Tính từ (càng ngày càng)', 'explain' => '越来越 được dùng để diễn tả sự thay đổi tăng dần theo thời gian, nghĩa là "càng ngày càng". Cấu trúc: 越来越 + Tính từ / Động từ tâm lý. Ví dụ: 越来越胖 (càng ngày càng béo), 天气越来越热 (thời tiết càng ngày càng nóng). 越来越 không thể dùng với động từ hành động cụ thể. Tính từ sau 越来越 có thể là tích cực hoặc tiêu cực. Đây là cấu trúc rất thông dụng để diễn tả xu hướng thay đổi. Lưu ý: 越来越 không đi kèm với 了 thường, nhưng có thể dùng trong ngữ cảnh phù hợp.', 'examples' => ['我越来越胖了。Tôi càng ngày càng béo.', '天气越来越热了。Thời tiết càng ngày càng nóng.', '他的汉语说得越来越好。Tiếng Trung của anh ấy càng ngày càng nói tốt.']],
            ['point' => 'Cấu trúc 越...越... (càng...càng...)', 'explain' => 'Cấu trúc 越...越... diễn tả hai sự việc thay đổi cùng chiều: sự việc thứ nhất càng tăng thì sự việc thứ hai càng thay đổi theo. Cấu trúc: 越 + Tính từ / Động từ + 越 + Tính từ / Động từ. Ví dụ: 越多越好 (càng nhiều càng tốt), 越来越 có thể coi là một dạng đặc biệt của 越...越... với 来 (đến). 越吃越胖 (càng ăn càng béo), 越学越聪明 (càng học càng thông minh). Cấu trúc này rất linh hoạt, có thể dùng với nhiều loại từ khác nhau.', 'examples' => ['越多越好。Càng nhiều càng tốt.', '他越跑越快。Anh ấy càng chạy càng nhanh.', '她越说越高兴。Cô ấy càng nói càng vui.']],
            ['point' => 'Cấu trúc 只要...就... (chỉ cần...là...)', 'explain' => '只要...就... diễn tả điều kiện đủ: chỉ cần điều kiện A xảy ra thì kết quả B sẽ xảy ra. Cấu trúc: 只要 + Điều kiện + 就 + Kết quả. Ví dụ: 只要坚持运动，就能瘦下来 (Chỉ cần kiên trì vận động, là có thể gầy xuống). 只要你努力，就一定能成功 (Chỉ cần bạn cố gắng, nhất định sẽ thành công). 只要 khác với 只有: 只要 chỉ điều kiện đủ, 只有 chỉ điều kiện cần (chỉ có...mới). 就 đứng trước kết quả, nhấn mạnh kết quả tất yếu khi điều kiện được đáp ứng.', 'examples' => ['只要努力，就能成功。Chỉ cần cố gắng là sẽ thành công.', '只要你来，我就高兴。Chỉ cần bạn đến là tôi vui.', '只要坚持，就一定能做到。Chỉ cần kiên trì, nhất định sẽ làm được.']],
        ],
