    26 => [
        'title' => 'Bài 26: 他是怎么知道的 - Anh ấy biết thế nào',
        'text' => '昨天发生了一件很奇怪的事情。早上我到教室的时候，发现桌子上放着一本我找了很久的书。那本《汉语语法大全》我已经找了一个月了，一直没找到。我问了同学，大家都说没看到。可是今天它突然出现在我的桌子上。我觉得很奇怪，心想："是谁帮我找到的呢？他又是怎么知道我在找这本书的？"我看了看周围，发现桌子上还有一张纸条，上面写着："这本书在图书馆的角落里，我帮你拿回来了。"纸条没有署名，我不知道是谁写的。我决定一定要找出这个好心人。我先去问了大卫："大卫，是不是你帮我找到了书？"大卫摇摇头说："我还没去图书馆呢。不是我。"我又去问了安娜："安娜，你知道是谁帮我找到书的吗？"安娜笑着说："我知道是谁，但是我不能说，那个人让我保密。"我更加好奇了，追问安娜："到底是谁啊？你快告诉我吧！"安娜说："你请我吃冰淇淋我就告诉你。"我答应了安娜的条件。安娜这才告诉我："是小李告诉我的。他说他昨天在图书馆看到了你的书，就帮你拿回来了。他不让我告诉你是他做的，怕你不好意思。"我听了以后很感动。原来小李一直在默默地帮助我。我去找小李，对他说："谢谢你帮我找到书！你是怎么知道我在找这本书的？"小李说："我上次听你说想买这本书，昨天在图书馆看到了，就帮你拿回来了。举手之劳而已。"我说："对你来说是举手之劳，对我可是帮了大忙！晚上我请你吃饭！"',
        'dialogues' => [
            ['who' => '王小明', 'cn' => '我的书怎么在桌子上？是谁帮我找到的？', 'vi' => 'Sách của tôi sao lại ở trên bàn? Ai tìm giúp tôi vậy?'],
            ['who' => '大卫', 'cn' => '不是我。我也刚来。', 'vi' => 'Không phải tôi. Tôi cũng vừa đến.'],
            ['who' => '王小明', 'cn' => '安娜，你知道是谁帮我找到的吗？', 'vi' => 'Anna, bạn có biết ai tìm giúp tôi không?'],
            ['who' => '安娜', 'cn' => '我知道，但是那个人让我保密。', 'vi' => 'Tôi biết, nhưng người đó bảo tôi giữ bí mật.'],
            ['who' => '王小明', 'cn' => '请告诉我吧！我请你吃冰淇淋。', 'vi' => 'Hãy nói cho tôi đi! Tôi mời bạn ăn kem.'],
            ['who' => '安娜', 'cn' => '好，是小李帮你拿回来的。', 'vi' => 'Được, là Tiểu Lý lấy giúp bạn đấy.'],
            ['who' => '王小明', 'cn' => '原来是小李！他是怎么知道我在找这本书的？', 'vi' => 'Hóa ra là Tiểu Lý! Anh ấy làm sao biết tôi đang tìm cuốn sách này?'],
            ['who' => '安娜', 'cn' => '上次你不是说想买吗？他记住了。', 'vi' => 'Lần trước bạn không phải nói muốn mua à? Anh ấy đã nhớ.'],
            ['who' => '王小明', 'cn' => '小李太够意思了！我得好好谢谢他。', 'vi' => 'Tiểu Lý tốt quá! Tôi phải cảm ơn anh ấy thật tốt.'],
        ],
        'grammar' => [
            ['point' => 'Câu hỏi với 怎么 (làm thế nào / tại sao)', 'explain' => '怎么 có nhiều nghĩa: (1) hỏi về phương thức: 你怎么去? (Bạn đi bằng cách nào?). (2) hỏi về nguyên nhân: 你怎么来了? (Sao bạn lại đến?). (3) hỏi về trạng thái: 你怎么了? (Bạn làm sao thế?). Cấu trúc: 怎么 + Động từ. Trong bài "他是怎么知道的", 怎么 hỏi về phương thức — anh ấy biết bằng cách nào. Trong khẩu ngữ, 怎么 thường dùng để hỏi về nguyên nhân bất ngờ. 怎么 không dùng với 吗, vì bản thân nó đã mang tính nghi vấn.', 'examples' => ['他是怎么知道的？Anh ấy biết thế nào?', '你怎么了？Bạn làm sao thế?', '你怎么不去？Sao bạn không đi?']],
            ['point' => 'Câu chữ 把 (cấu trúc 把)', 'explain' => 'Cấu trúc 把 được dùng để nhấn mạnh tân ngữ bị tác động bởi hành động. Cấu trúc: Chủ ngữ + 把 + Tân ngữ + Động từ + Các thành phần khác. Ví dụ: 我把书放在桌子上 (Tôi đặt sách lên bàn). 他把书拿回来了 (Anh ấy lấy sách về rồi). 把 nhấn mạnh sự thay đổi vị trí hoặc trạng thái của tân ngữ. Không phải động từ nào cũng dùng được với 把. Động từ phải có tính chủ động và gây ra thay đổi nơi tân ngữ. Cấu trúc 把 thường đi với bổ ngữ.', 'examples' => ['他把书拿回来了。Anh ấy lấy sách về rồi.', '请把门关上。Xin hãy đóng cửa lại.', '我把作业做完了。Tôi đã làm xong bài tập.']],
            ['point' => 'Cấu trúc câu gián tiếp với 说', 'explain' => 'Để thuật lại lời nói của người khác, tiếng Trung dùng: Người + 说 + Nội dung. Có thể dùng trực tiếp hoặc gián tiếp. Trực tiếp: 他说："我不去" (Anh ấy nói: "Tôi không đi"). Gián tiếp: 他说他不去 (Anh ấy nói anh ấy không đi). Trong câu gián tiếp, không thay đổi thì như tiếng Anh. Các động từ thuật khác: 告诉 (nói cho), 问 (hỏi), 回答 (trả lời). 告诉 thường dùng với tân ngữ: 我告诉他我不去 (Tôi nói với anh ấy tôi không đi).', 'examples' => ['他说他明天来。Anh ấy nói ngày mai anh ấy đến.', '我告诉了他这件事。Tôi đã nói với anh ấy việc này.', '他问我叫什么名字。Anh ấy hỏi tôi tên là gì.']],
        ],
        'pronunciation' => ['focus' => 'tone pairs 2-3', 'drill' => ['pí jiǔ', 'huí jiā', 'fáng jiān', 'qián miàn', 'tóng xué', 'shuǐ guǒ', 'yóu yǒng', 'píng guǒ']],
