            ['w' => '知道', 'p' => 'zhīdào', 'm' => 'biết', 'pos' => '动词', 'ex' => ['我知道这件事。Tôi biết việc này.', '你知道他叫什么吗？Bạn biết anh ấy tên gì không?']],
