    27 => [
        'title' => 'Bài 27: 我跟她都认识五年了 - Tôi và cô ấy quen nhau năm năm rồi',
        'text' => '今天在学校门口，我遇到了一个很久没见的老朋友。她叫王丽，是我中学时候的同学。我们已经五年没见面了，没想到今天能在大学门口遇到她。我一眼就认出了她，虽然她变了一些，比以前高了，也漂亮了。我走过去跟她打招呼："王丽！好久不见！你还记得我吗？"王丽看着我，愣了一下，然后笑着说："你是王小明吧？我们五年没见了，你变化也挺大的！"我们都很高兴能在大学里重逢。王丽说她也在这个大学读书，学的是英语专业，今年大四了。我说我是学中文的，今年也大四了。我们聊了很多以前的事情，想起了中学时的同学和老师。王丽问我："你还记得我们班的张老师吗？"我说："当然记得！张老师教我们数学，他讲课特别有意思。"王丽说："听说张老师现在已经退休了。"我有点儿惊讶："这么快？时间过得好快啊！"我跟王丽聊了大概半个小时，互相留了新的联系方式。王丽说："以后我们常联系吧！周末有空可以一起吃饭。"我说："好啊！这周末你有空吗？我们一起吃个饭，好好聊聊。"王丽说："这周末我有空，那我们星期六中午见吧。"我给了她一个大大的拥抱，然后各自去上课了。能在大学里遇到老朋友，真是一件让人开心的事情。跟老朋友聊天，就像回到了过去一样，感觉特别温暖。',
        'dialogues' => [
            ['who' => '王小明', 'cn' => '王丽！好久不见！你还记得我吗？', 'vi' => 'Vương Lệ! Lâu quá không gặp! Bạn còn nhớ tôi không?'],
            ['who' => '王丽', 'cn' => '王小明！五年没见了，你变化真大！', 'vi' => 'Vương Tiểu Minh! Năm năm không gặp, bạn thay đổi thật nhiều!'],
            ['who' => '王小明', 'cn' => '你也变了不少，比以前高多了！', 'vi' => 'Bạn cũng thay đổi nhiều, cao hơn trước nhiều!'],
            ['who' => '王丽', 'cn' => '你现在在哪个大学？学什么专业？', 'vi' => 'Bây giờ bạn ở trường đại học nào? Học chuyên ngành gì?'],
            ['who' => '王小明', 'cn' => '我也在这个大学，学中文专业。', 'vi' => 'Tôi cũng ở trường đại học này, học chuyên ngành tiếng Trung.'],
            ['who' => '王丽', 'cn' => '真巧啊！我也是这个大学的，学英语专业。', 'vi' => 'Thật trùng hợp! Tôi cũng ở trường này, học tiếng Anh.'],
            ['who' => '王小明', 'cn' => '你还记得张老师吗？', 'vi' => 'Bạn còn nhớ cô Trương không?'],
            ['who' => '王丽', 'cn' => '当然记得！张老师现在退休了。', 'vi' => 'Đương nhiên nhớ! Cô Trương bây giờ đã nghỉ hưu rồi.'],
            ['who' => '王小明', 'cn' => '时间过得太快了。周末有空一起吃个饭吧？', 'vi' => 'Thời gian trôi nhanh quá. Cuối tuần có rảnh cùng ăn cơm nhé?'],
            ['who' => '王丽', 'cn' => '好啊！星期六中午？', 'vi' => 'Được! Trưa thứ bảy nhé?'],
            ['who' => '王小明', 'cn' => '就这么定了！到时候联系。', 'vi' => 'Nhất định rồi! Đến lúc đó liên lạc nhé.'],
        ],
        'grammar' => [
            ['point' => 'Cấu trúc thời gian với 了 (đã...rồi)', 'explain' => 'Khi muốn nói một hành động hoặc trạng thái đã kéo dài bao lâu tính đến hiện tại, dùng: Thời gian + 了. Cấu trúc đầy đủ: Động từ + (Tân ngữ) + Thời gian + 了. Ví dụ: 认识五年了 (Quen nhau 5 năm rồi). 他来了三天了 (Anh ấy đến ba ngày rồi). 我学汉语三年了 (Tôi học tiếng Trung ba năm rồi). Lưu ý: 了 ở cuối câu biểu thị trạng thái kéo dài đến hiện tại, hành động vẫn tiếp diễn hoặc kết quả vẫn còn. Nếu hành động đã kết thúc, dùng cấu trúc khác.', 'examples' => ['我跟她都认识五年了。Tôi và cô ấy quen nhau năm năm rồi.', '我学汉语三年了。Tôi học tiếng Trung ba năm rồi.', '他来了三天了。Anh ấy đến ba ngày rồi.']],
            ['point' => 'Cấu trúc 好久不见 (Lâu quá không gặp)', 'explain' => '好久不见 là câu chào hỏi thông dụng khi gặp lại người quen sau một thời gian dài không gặp. Nghĩa: "Lâu quá không gặp". Có thể thêm các biến thể: 好久不见了, 好久没见了. Các cách đáp lại thường gặp: 是啊，好久不见 (Phải đấy, lâu quá không gặp), 真没想到会在这儿见到你 (Thật không ngờ sẽ gặp bạn ở đây). Trong câu hỏi về thời gian: 我们多久没见了? (Chúng ta bao lâu không gặp rồi?).', 'examples' => ['好久不见！Lâu quá không gặp!', '好久不见了，你还好吗？Lâu quá không gặp, bạn vẫn khỏe chứ?', '真没想到能在这里见到你。Thật không ngờ có thể gặp bạn ở đây.']],
            ['point' => 'Cấu trúc 记得 / 忘记 (nhớ / quên)', 'explain' => '记得 (nhớ) và 忘记 (quên) là hai động từ quan trọng. 记得 + Danh từ / Mệnh đề: 我记得他的名字 (Tôi nhớ tên anh ấy). 我记得他叫王明 (Tôi nhớ anh ấy tên là Vương Minh). 忘记 + Danh từ / Động từ: 我忘记了时间 (Tôi quên mất thời gian). 别忘了带钥匙 (Đừng quên mang chìa khóa). Phủ định của 记得 là 不记得 (không nhớ). "我忘了" được dùng phổ biến hơn "我忘记了" trong khẩu ngữ. 别忘了 là câu nhắc nhở thông dụng.', 'examples' => ['你还记得我吗？Bạn còn nhớ tôi không?', '我记得他。Tôi nhớ anh ấy.', '别忘了带手机。Đừng quên mang điện thoại.']],
        ],
        'pronunciation' => ['focus' => 'tone pairs 3-4', 'drill' => ['gǎn xiè', 'lǎo shì', 'nǔ lì', 'kě shì', 'lǚ yóu', 'měi lì', 'qǐng wèn', 'yǒng yuǎn']],
