            ['w' => '好久不见', 'p' => 'hǎojiǔ bùjiàn', 'm' => 'lâu quá không gặp', 'pos' => '短语', 'ex' => ['好久不见！你还好吗？Lâu quá không gặp! Bạn vẫn khỏe chứ?', '好久不见了。Lâu quá không gặp rồi.']],
            ['w' => '记得', 'p' => 'jìde', 'm' => 'nhớ', 'pos' => '动词', 'ex' => ['你还记得我吗？Bạn còn nhớ tôi không?', '我记得这件事。Tôi nhớ việc này.']],
