            ['w' => '重逢', 'p' => 'chóngféng', 'm' => 'tương phùng, gặp lại', 'pos' => '动词', 'ex' => ['我们十年后重逢了。Chúng tôi gặp lại sau mười năm.', '老朋友重逢很开心。Gặp lại bạn cũ rất vui.']],
            ['w' => '联系', 'p' => 'liánxì', 'm' => 'liên lạc', 'pos' => '动词,名词', 'ex' => ['我们常联系吧。Chúng ta thường xuyên liên lạc nhé.', '你有他的联系方式吗？Bạn có cách liên lạc với anh ấy không?']],
