            ['w' => '拥抱', 'p' => 'yōngbào', 'm' => 'ôm', 'pos' => '动词', 'ex' => ['他们拥抱了一下。Họ ôm nhau một cái.', '给你一个拥抱。Cho bạn một cái ôm.']],
