    28 => [
        'title' => 'Bài 28: 我马上让他来 - Tôi lập tức bảo anh ấy đến',
        'text' => '今天下午，我正在家里写作业，突然电话响了。我拿起电话，是妈妈打来的。妈妈说："小明，你现在在家吗？"我说："在家呢，妈妈。怎么了？"妈妈的声音听起来有点儿着急，她说："家里来了客人，是你爸爸的同事张叔叔。但是家里没有水果了，你快去楼下超市买一些水果回来。还有，你爸爸的公司打电话来说有急事，让你爸爸马上回公司一趟。你爸爸现在不在家，你帮我找到他，让他马上回来。"我说："好的，妈妈你别着急。爸爸去哪儿了？"妈妈说："他应该在小区门口的理发店理发。你去叫他马上回来。"我放下电话，先去楼下超市买了一些水果，有苹果、香蕉和葡萄。然后我赶紧跑到小区门口的理发店。果然，爸爸正在那里理发，头发已经理了一半。我对爸爸说："爸爸，妈妈让你马上回家！家里来客人了，而且公司有急事让你回公司。"爸爸说："好，我马上让理发师理完。你先回家帮妈妈招待客人。"我说："好的，那您快点儿。"我回到家，帮妈妈洗好水果，摆好盘子。很快爸爸也理完发回来了。他换了一身衣服，然后跟张叔叔聊了一会儿。张叔叔说："你们家小明真懂事。"爸爸笑着说："是啊，他长大了。"然后爸爸接到公司的电话，跟张叔叔说对不起，然后赶去公司了。我继续写我的作业。',
        'dialogues' => [
            ['who' => '妈妈', 'cn' => '小明，家里来客人了，你快去买些水果。', 'vi' => 'Tiểu Minh, nhà có khách, con mau đi mua ít trái cây.'],
            ['who' => '王小明', 'cn' => '好的妈妈，买什么水果？', 'vi' => 'Vâng mẹ, mua trái cây gì ạ?'],
            ['who' => '妈妈', 'cn' => '买苹果、香蕉和葡萄吧。还有，你爸爸去哪儿了？', 'vi' => 'Mua táo, chuối và nho nhé. Còn nữa, bố con đi đâu rồi?'],
            ['who' => '王小明', 'cn' => '爸爸应该在理发店理发。', 'vi' => 'Bố chắc đang ở tiệm cắt tóc.'],
            ['who' => '妈妈', 'cn' => '你去叫他马上回来，公司有急事。', 'vi' => 'Con đi gọi bố về ngay, công ty có việc gấp.'],
            ['who' => '王小明', 'cn' => '好的，我马上去。', 'vi' => 'Vâng, con đi ngay đây.'],
            ['who' => '王小明', 'cn' => '爸爸，妈妈让您马上回家！', 'vi' => 'Bố ơi, mẹ bảo bố về nhà ngay ạ!'],
            ['who' => '爸爸', 'cn' => '怎么了？出什么事了？', 'vi' => 'Sao thế? Có chuyện gì vậy?'],
            ['who' => '王小明', 'cn' => '家里来客人了，公司也有急事。', 'vi' => 'Nhà có khách, công ty cũng có việc gấp.'],
            ['who' => '爸爸', 'cn' => '好，我马上理完。你先回去帮妈妈。', 'vi' => 'Được, bố cắt xong ngay. Con về giúp mẹ trước đi.'],
        ],
        'grammar' => [
            ['point' => '让 + Người + Động từ (bảo/sai khiến ai làm gì)', 'explain' => '让 có nghĩa "bảo, sai khiến, yêu cầu" ai đó làm gì. Cấu trúc: Chủ ngữ + 让 + Người + Động từ. Ví dụ: 我让他来 (Tôi bảo anh ấy đến). 妈妈让我去买水果 (Mẹ bảo tôi đi mua trái cây). 让 mang tính sai khiến nhẹ hơn 叫 và 命令. Trong câu, người được sai khiến là tân ngữ, đứng giữa 让 và động từ. 让 cũng có thể dùng trong cấu trúc "cho phép": 让我试试 (Để tôi thử). 请 cho sắc thái lịch sự hơn, 让 cho sắc thái trung tính.', 'examples' => ['我马上让他来。Tôi lập tức bảo anh ấy đến.', '妈妈让我去买水果。Mẹ bảo tôi đi mua trái cây.', '老师让我们写作业。Cô giáo bảo chúng tôi viết bài.']],
            ['point' => 'Cấu trúc 马上 + Động từ (ngay lập tức)', 'explain' => '马上 là phó từ chỉ thời gian, nghĩa "ngay lập tức, ngay". Đứng trước động từ. Cấu trúc: 马上 + Động từ. Ví dụ: 我马上来 (Tôi đến ngay). 马上 khác với 立刻 (lập tức)—sắc thái mạnh hơn. 马上 thường dùng trong khẩu ngữ hàng ngày, linh hoạt hơn. Có thể kết hợp với 就 để nhấn mạnh: 马上就 (ngay liền). Ví dụ: 我马上就来 (Tôi đến ngay đây). 马上 cũng có nghĩa "sắp sửa": 马上要考试了 (Sắp thi rồi).', 'examples' => ['我马上让他来。Tôi lập tức bảo anh ấy đến.', '我马上就来。Tôi đến ngay đây.', '马上要下雨了。Sắp mưa rồi.']],
            ['point' => 'Cách nói điện thoại: 打电话 / 接电话', 'explain' => 'Các động từ liên quan đến điện thoại: 打电话 (gọi điện), 接电话 (nghe điện thoại), 回电话 (gọi lại), 挂电话 (cúp máy). Cấu trúc thông dụng: 给 + Người + 打电话 (gọi điện cho ai). Ví dụ: 妈妈给我打电话 (Mẹ gọi điện cho tôi). 我接了一个电话 (Tôi nghe một cuộc điện thoại). Trong hội thoại điện thoại, thường dùng: 喂 (a-lô), 请问 (xin hỏi), 请稍等 (xin chờ một chút). "电话响了" (Điện thoại reo) là cách diễn tả cuộc gọi đến.', 'examples' => ['妈妈给我打电话。Mẹ gọi điện cho tôi.', '请稍等，我马上让他接电话。Xin chờ một chút, tôi bảo anh ấy nghe điện ngay.', '电话响了。Điện thoại reo rồi.']],
        ],
        'pronunciation' => ['focus' => 'tone pairs 1-4', 'drill' => ['shēng bìng', 'zhōng wǔ', 'gōng zuò', 'chī fàn', 'dōng tiān', 'fēng jǐng', 'gāo xìng', 'jīng guò']],
