            ['w' => '让', 'p' => 'ràng', 'm' => 'bảo, để cho, khiến', 'pos' => '动词', 'ex' => ['我让他来。Tôi bảo anh ấy đến.', '妈妈让我买东西。Mẹ bảo tôi mua đồ.']],
            ['w' => '电话', 'p' => 'diànhuà', 'm' => 'điện thoại', 'pos' => '名词', 'ex' => ['电话响了。Điện thoại reo.', '我给你打电话。Tôi gọi điện cho bạn.']],
            ['w' => '客人', 'p' => 'kèrén', 'm' => 'khách, khách khứa', 'pos' => '名词', 'ex' => ['家里来客人了。Nhà có khách đến.', '客人请坐。Mời khách ngồi.']],
