    29 => [
        'title' => 'Bài 29: 她没说话，只是笑了笑 - Cô ấy không nói gì, chỉ cười',
        'text' => '昨天晚上，我和妈妈在客厅里看电视。这时候，电话响了。妈妈接起电话，说了几句话以后，脸色突然变得不太好。我担心地问妈妈："妈妈，怎么了？"妈妈没有回答我的问题，只是对我笑了笑，然后继续听电话。我心里更加担心了，不知道发生了什么事。过了一会儿，妈妈挂了电话。她还是没有说话，只是坐在沙发上发呆。我又问了一遍："妈妈，到底怎么了？您告诉我吧。"妈妈看了看我，叹了口气，然后说："你奶奶住院了。"我一听也很紧张，问："奶奶怎么了？严重吗？"妈妈说："医生说是高血压，需要住院观察几天。不过你不用担心，问题不大。"我松了一口气，说："那我们明天去医院看奶奶吧。"妈妈点了点头，没说话，只是笑了笑。我知道妈妈虽然笑着，但是心里一定很担心奶奶。妈妈是一个非常坚强的人，她不想让我太担心，所以才装作没事的样子。第二天一早，我和妈妈去医院看奶奶。奶奶躺在病床上，看到我们来了很高兴，笑着跟我们打招呼。我问奶奶："奶奶，您好点儿了吗？"奶奶笑着说："好多了，别担心。医生说再观察两天就能出院了。"我说："那就好。"奶奶拉着我的手说："小明长大了，知道关心奶奶了。"我不好意思地笑了笑。从医院回家的路上，妈妈对我说："奶奶没事儿了，你放心了吧？"我点点头，也笑了笑。',
        'dialogues' => [
            ['who' => '妈妈', 'cn' => '（接电话）喂？什么？真的吗？好的，我知道了。', 'vi' => '(Nghe điện thoại) A-lô? Gì cơ? Thật à? Được, tôi biết rồi.'],
            ['who' => '王小明', 'cn' => '妈妈，怎么了？出什么事了？', 'vi' => 'Mẹ ơi, sao thế? Có chuyện gì vậy?'],
            ['who' => '妈妈', 'cn' => '没事儿。（笑了笑）你去看电视吧。', 'vi' => 'Không có gì. (cười) Con đi xem tivi đi.'],
            ['who' => '王小明', 'cn' => '可是您的脸色不太好，到底怎么了？', 'vi' => 'Nhưng mặt mẹ không được tốt, rốt cuộc sao thế?'],
            ['who' => '妈妈', 'cn' => '你奶奶住院了，不过问题不大。', 'vi' => 'Bà nội con nhập viện rồi, nhưng vấn đề không lớn.'],
            ['who' => '王小明', 'cn' => '什么？奶奶怎么了？严重吗？', 'vi' => 'Sao? Bà làm sao ạ? Có nghiêm trọng không?'],
            ['who' => '妈妈', 'cn' => '高血压，医生说观察几天就好。', 'vi' => 'Cao huyết áp, bác sĩ nói theo dõi vài ngày là tốt.'],
            ['who' => '妈妈', 'cn' => '奶奶，您好点儿了吗？', 'vi' => 'Bà ơi, bà đỡ hơn chưa ạ?'],
            ['who' => '奶奶', 'cn' => '好多了！小明来看我，我就全好了。', 'vi' => 'Đỡ nhiều rồi! Tiểu Minh đến thăm, bà khỏe hẳn rồi.'],
            ['who' => '王小明', 'cn' => '奶奶您要好好休息。', 'vi' => 'Bà phải nghỉ ngơi tốt nhé.'],
        ],
        'grammar' => [
            ['point' => 'Cấu trúc 没 / 没有 + Động từ (phủ định hành động)', 'explain' => '没 / 没有 được dùng để phủ định hành động đã xảy ra (quá khứ) hoặc sự tồn tại. Cấu trúc: 没(有) + Động từ. Ví dụ: 他没说话 (Anh ấy không nói gì). 我没去 (Tôi đã không đi). 没有 cũng có thể phủ định sự tồn tại: 没有问题 (Không có vấn đề). Phân biệt với 不: 不 phủ định hiện tại/tương lai và ý chí chủ quan; 没 phủ định quá khứ và sự tồn tại. Ví dụ: 我不吃 (Tôi không ăn — không muốn), 我没吃 (Tôi chưa ăn/Tôi đã không ăn — sự thật).', 'examples' => ['她没说话，只是笑了笑。Cô ấy không nói gì, chỉ cười.', '我没去图书馆。Tôi đã không đi thư viện.', '没有关系。Không có vấn đề gì.']],
            ['point' => 'Cấu trúc 只是 (chỉ / chỉ là)', 'explain' => '只是 có hai cách dùng: (1) Phó từ chỉ phạm vi: "chỉ" — 她只是笑了笑 (Cô ấy chỉ cười). (2) Liên từ chỉ sự nhượng bộ: "chỉ là, có điều" — 这件衣服很好看，只是太贵了 (Cái áo này rất đẹp, chỉ là đắt quá). Trong nghĩa phó từ, 只是 đứng trước động từ: 只是 + Động từ. Tương tự 不过 nhưng 只是 nhẹ nhàng hơn. Khi 只是 được dùng với ý "chỉ là", nó làm giảm nhẹ mức độ của nhận xét trước đó.', 'examples' => ['她只是笑了笑。Cô ấy chỉ cười.', '我只是想帮你。Tôi chỉ muốn giúp bạn.', '这件很好，只是贵了点儿。Cái này rất tốt, chỉ là hơi đắt.']],
            ['point' => 'Cấu trúc 虽然...但是... (mặc dù...nhưng...)', 'explain' => '虽然...但是... biểu thị sự tương phản: mặc dù một điều đúng, nhưng điều khác lại trái ngược. Cấu trúc: 虽然 + Mệnh đề 1 + 但是/可是 + Mệnh đề 2. Ví dụ: 虽然妈妈笑着，但是心里很担心 (Mặc dù mẹ cười, nhưng trong lòng rất lo lắng). 虽然 khác với 即使: 虽然 chỉ sự việc có thật, 即使 chỉ giả định. 但是和可是 có thể dùng thay thế nhau, 但是 trang trọng hơn. Trong khẩu ngữ thường dùng 可是. Có thể chỉ dùng 虽然, bỏ 但是 nếu ngữ cảnh rõ.', 'examples' => ['虽然她笑着，但是心里很难过。Mặc dù cô ấy cười, nhưng trong lòng rất buồn.', '虽然很累，但是我很快乐。Dù rất mệt, nhưng tôi rất vui.', '虽然贵，但是质量好。Dù đắt, nhưng chất lượng tốt.']],
        ],
        'pronunciation' => ['focus' => 'neutral tone', 'drill' => ['māma', 'bàba', 'gēge', 'jiějie', 'péngyou', 'dìdi', 'mèimei', 'yǐzi']],
        'vocab' => [
            ['w' => '只是', 'p' => 'zhǐshì', 'm' => 'chỉ, chỉ là', 'pos' => '副词,连词', 'ex' => ['她只是笑了笑。Cô ấy chỉ cười.', '我只是问问。Tôi chỉ hỏi thôi.']],
            ['w' => '没', 'p' => 'méi', 'm' => 'không, chưa', 'pos' => '副词', 'ex' => ['他没说话。Anh ấy không nói gì.', '我没去。Tôi đã không đi.']],
            ['w' => '说话', 'p' => 'shuō huà', 'm' => 'nói chuyện, nói', 'pos' => '动词', 'ex' => ['她没说话。Cô ấy không nói gì.', '上课不要说话。Đừng nói chuyện trong giờ học.']],
            ['w' => '虽然', 'p' => 'suīrán', 'm' => 'mặc dù', 'pos' => '连词', 'ex' => ['虽然很累，但是很开心。Dù rất mệt nhưng rất vui.', '虽然贵，但是质量好。Dù đắt nhưng chất lượng tốt.']],
            ['w' => '但是', 'p' => 'dànshì', 'm' => 'nhưng', 'pos' => '连词', 'ex' => ['我想去，但是没时间。Tôi muốn đi, nhưng không có thời gian.', '他虽然聪明，但是不努力。Anh ấy tuy thông minh nhưng không cố gắng.']],
            ['w' => '住院', 'p' => 'zhù yuàn', 'm' => 'nhập viện', 'pos' => '动词', 'ex' => ['奶奶住院了。Bà nhập viện rồi.', '他住院三天了。Anh ấy nhập viện ba ngày rồi.']],
            ['w' => '担心', 'p' => 'dānxīn', 'm' => 'lo lắng', 'pos' => '动词', 'ex' => ['我很担心。Tôi rất lo.', '别担心，没事儿。Đừng lo, không sao.']],
            ['w' => '坚强', 'p' => 'jiānqiáng', 'm' => 'kiên cường', 'pos' => '形容词', 'ex' => ['妈妈很坚强。Mẹ rất kiên cường.', '你要坚强。Bạn phải kiên cường.']],
