            ['w' => '样子', 'p' => 'yàngzi', 'm' => 'dáng vẻ, bộ dạng', 'pos' => '名词', 'ex' => ['他装作没事的样子。Anh ấy giả vờ bộ dạng không sao.', '这是什么样子？Đây là bộ dạng gì vậy?']],
            ['w' => '出院', 'p' => 'chū yuàn', 'm' => 'xuất viện', 'pos' => '动词', 'ex' => ['医生说后天能出院。Bác sĩ nói ngày kia có thể xuất viện.', '他昨天出院了。Anh ấy hôm qua đã xuất viện.']],
