    30 => [
        'title' => 'Bài 30: 数学比历史难多了 - Toán khó hơn lịch sử nhiều',
        'text' => '这学期我们有很多门课，有汉语课、数学课、历史课、地理课和英语课。每门课的老师都不一样，上课的方式也各不相同。其中我觉得最难的是数学课，最容易的是历史课。数学真的比历史难多了。每次上数学课，我都觉得很头疼。数学老师讲课很快，常常一节课就讲了很多公式和定理。我还没弄明白上一个公式，老师已经开始讲下一个了。相比之下，历史课就轻松多了。历史老师讲得慢，而且总是给我们讲很多有趣的历史故事。我觉得历史很有意思，上课就像在听故事一样。昨天数学考试，我考得很不好。试卷上的题目我有一半都不会做。回到家我跟妈妈说："妈妈，我数学没考好。"妈妈问："为什么？你复习了吗？"我说："我复习了，但是数学太难了！数学比历史难多了！"妈妈笑着说："每个人擅长的科目不一样。你对历史这么感兴趣，但是数学要多下功夫。"爸爸在旁边听到了，说："数学其实不难，只要你掌握了方法。来，爸爸教你。"爸爸给我讲了几道题，我发现原来数学也没有那么难。爸爸说数学是有规律的，只要找到规律，就可以举一反三。听了爸爸的话，我开始重新学习数学。我发现自己以前没有好好理解公式的含义，只是死记硬背，所以遇到变化就不会了。现在我开始理解每一个公式的推导过程，数学好像真的变得容易了。',
        'dialogues' => [
            ['who' => '王小明', 'cn' => '妈妈，我数学没考好。', 'vi' => 'Mẹ ơi, con thi toán không tốt.'],
            ['who' => '妈妈', 'cn' => '你复习了吗？怎么还是没考好？', 'vi' => 'Con ôn bài chưa? Sao vẫn thi không tốt?'],
            ['who' => '王小明', 'cn' => '复习了，但是数学太难了！比其他科目难多了。', 'vi' => 'Ôn rồi, nhưng toán khó quá! Khó hơn các môn khác nhiều.'],
            ['who' => '爸爸', 'cn' => '数学比历史难吗？', 'vi' => 'Toán khó hơn lịch sử à?'],
            ['who' => '王小明', 'cn' => '当然！数学比历史难多了。历史容易多了。', 'vi' => 'Đương nhiên! Toán khó hơn lịch sử nhiều. Lịch sử dễ hơn nhiều.'],
            ['who' => '爸爸', 'cn' => '数学其实不难，是你没找对方法。', 'vi' => 'Toán thật ra không khó, là con chưa tìm đúng phương pháp.'],
            ['who' => '王小明', 'cn' => '真的吗？可是我怎么学都不会。', 'vi' => 'Thật không? Nhưng con học thế nào cũng không được.'],
            ['who' => '爸爸', 'cn' => '来，爸爸教你。数学是有规律的。', 'vi' => 'Đến đây, bố dạy con. Toán học có quy luật.'],
            ['who' => '王小明', 'cn' => '哦，我明白了！原来是这样算的。', 'vi' => 'Ồ, con hiểu rồi! Hóa ra tính như thế này.'],
            ['who' => '爸爸', 'cn' => '你看，只要掌握了方法，就不难了。', 'vi' => 'Con thấy không, chỉ cần nắm được phương pháp là không khó.'],
        ],
        'grammar' => [
            ['point' => 'So sánh cao hơn: A 比 B + Tính từ + 多了 / 得多', 'explain' => 'Để diễn tả mức độ chênh lệch lớn trong so sánh, dùng 多了 hoặc 得多 sau tính từ. Cấu trúc: A + 比 + B + Tính từ + 多了/得多. Ví dụ: 数学比历史难多了 (Toán khó hơn lịch sử nhiều). 我比他高多了 (Tôi cao hơn anh ấy nhiều). 多了 thường dùng trong khẩu ngữ, 得多 dùng trong cả văn nói và văn viết. 一点儿 chỉ chênh lệch ít. Cũng có thể dùng 很多: 大很多 (lớn hơn nhiều). Nếu muốn nói lượng cụ thể: 大两岁 (lớn hơn hai tuổi).', 'examples' => ['数学比历史难多了。Toán khó hơn lịch sử nhiều.', '今天比昨天冷多了。Hôm nay lạnh hơn hôm qua nhiều.', '他比我高得多。Anh ấy cao hơn tôi nhiều.']],
            ['point' => 'Cấu trúc 跟...一样 / 不一样 (giống / khác)', 'explain' => 'Để so sánh ngang bằng hoặc khác biệt, dùng: A + 跟/和 + B + 一样/不一样 (+ Tính từ). Ví dụ: 我跟她一样高 (Tôi cao bằng cô ấy). 我的想法跟你的不一样 (Ý nghĩ của tôi khác với của bạn). 一样 có thể đứng một mình (giống nhau) hoặc kết hợp với tính từ. Phủ định dùng 不一样 (không giống). Trong khẩu ngữ, 跟 thông dụng hơn 和. 相同 (giống nhau) mang sắc thái trang trọng hơn.', 'examples' => ['我跟她一样高。Tôi cao bằng cô ấy.', '我的书跟你的不一样。Sách của tôi khác với sách của bạn.', '这两个手机一样。Hai cái điện thoại này giống nhau.']],
            ['point' => 'Cấu trúc 只要...就... (chỉ cần...là...)', 'explain' => '只要...就... diễn tả điều kiện đủ: chỉ cần điều kiện A được thỏa mãn thì kết quả B sẽ xảy ra. Cấu trúc: 只要 + Điều kiện + 就 + Kết quả. Ví dụ: 只要掌握了方法，就不难 (Chỉ cần nắm được phương pháp thì không khó). 只要努力，就能成功 (Chỉ cần cố gắng là có thể thành công). 只要 khác với 只有 (chỉ có...mới): 只有强调条件唯一且必要, 只要强调条件足够. 就 đứng trước kết quả, có thể thêm 会/能 vào trước động từ.', 'examples' => ['只要努力，就能成功。Chỉ cần cố gắng là có thể thành công.', '只要你来，我就高兴。Chỉ cần bạn đến là tôi vui.', '只要坚持，就一定可以。Chỉ cần kiên trì, nhất định có thể.']],
        ],
        'pronunciation' => ['focus' => 'tone pairs 4-2', 'drill' => ['fàng xué', 'hù xiāng', 'kuài lè', 'lìng wài', 'wèn tí', 'zuò wén', 'shì qíng', 'jiè shào']],
        'vocab' => [
            ['w' => '比', 'p' => 'bǐ', 'm' => 'hơn (so sánh)', 'pos' => '介词', 'ex' => ['数学比历史难。Toán khó hơn lịch sử.', '今天比昨天冷。Hôm nay lạnh hơn hôm qua.']],
            ['w' => '难', 'p' => 'nán', 'm' => 'khó', 'pos' => '形容词', 'ex' => ['数学很难。Toán rất khó.', '这个问题不难。Câu hỏi này không khó.']],
            ['w' => '容易', 'p' => 'róngyì', 'm' => 'dễ dàng', 'pos' => '形容词', 'ex' => ['这个很容易。Cái này rất dễ.', '说起来容易做起来难。Nói thì dễ làm thì khó.']],
            ['w' => '数学', 'p' => 'shùxué', 'm' => 'toán học', 'pos' => '名词', 'ex' => ['数学是我的弱项。Toán là điểm yếu của tôi.', '数学老师讲得很快。Giáo viên toán giảng rất nhanh.']],
            ['w' => '历史', 'p' => 'lìshǐ', 'm' => 'lịch sử', 'pos' => '名词', 'ex' => ['我喜欢历史。Tôi thích lịch sử.', '历史课很有意思。Tiết lịch sử rất thú vị.']],
            ['w' => '科目', 'p' => 'kēmù', 'm' => 'môn học', 'pos' => '名词', 'ex' => ['这学期有几门科目？Học kỳ này có mấy môn?', '我最喜欢的科目是中文。Môn tôi thích nhất là tiếng Trung.']],
            ['w' => '公式', 'p' => 'gōngshì', 'm' => 'công thức', 'pos' => '名词', 'ex' => ['这个公式很难记。Công thức này rất khó nhớ.', '数学公式很多。Công thức toán rất nhiều.']],
            ['w' => '规律', 'p' => 'guīlǜ', 'm' => 'quy luật', 'pos' => '名词', 'ex' => ['数学是有规律的。Toán học có quy luật.', '找到规律就容易了。Tìm ra quy luật là dễ.']],
            ['w' => '掌握', 'p' => 'zhǎngwò', 'm' => 'nắm vững', 'pos' => '动词', 'ex' => ['掌握方法很重要。Nắm vững phương pháp rất quan trọng.', '你掌握了吗？Bạn nắm vững chưa?']],
            ['w' => '理解', 'p' => 'lǐjiě', 'm' => 'hiểu, lý giải', 'pos' => '动词', 'ex' => ['我理解了。Tôi hiểu rồi.', '你能理解吗？Bạn có thể hiểu không?']],
            ['w' => '方法', 'p' => 'fāngfǎ', 'm' => 'phương pháp', 'pos' => '名词', 'ex' => ['学习方法很重要。Phương pháp học tập rất quan trọng.', '换个方法试试。Đổi phương pháp thử xem.']],
            ['w' => '有趣', 'p' => 'yǒuqù', 'm' => 'có thú vị', 'pos' => '形容词', 'ex' => ['历史课很有趣。Tiết lịch sử rất thú vị.', '这个游戏很有趣。Trò chơi này rất thú vị.']],
            ['w' => '头疼', 'p' => 'tóuténg', 'm' => 'đau đầu', 'pos' => '形容词,动词', 'ex' => ['数学让我头疼。Toán làm tôi đau đầu.', '这个问题真让人头疼。Vấn đề này thật làm người ta đau đầu.']],
        ],
