                ['q' => '"我跟她一样高"的意思是什么？', 'opts' => ['Tôi cao hơn cô ấy', 'Tôi thấp hơn cô ấy', 'Tôi cao bằng cô ấy', 'Không so sánh'], 'a' => 2],
