    31 => [
        'title' => 'Bài 31: 简单的爱情 - Tình yêu giản dị',
        'text' => '我的邻居是一对老夫妻，他们已经结婚四十年了。我常常看到他们一起去超市买东西，一起去公园散步。他们的生活看起来很平淡，但是很幸福。有一天，我在楼下遇到了王爷爷。他正拿着一束花，我笑着说："王爷爷，您买花送给谁呀？"王爷爷不好意思地笑了笑说："今天是我和你奶奶结婚四十周年纪念日。虽然不是什么特别的日子，但是我想让她开心一下。"我说："您真浪漫！奶奶一定会喜欢的。"王爷爷说："其实爱情不需要多么浪漫，每天陪在对方身边，互相关心，互相照顾，就是最大的幸福。"听了王爷爷的话，我很有感触。是啊，真正的爱情不是轰轰烈烈的，而是在平平淡淡的生活中，有人陪你一起变老。这让我想起了我爸爸妈妈。他们也是平凡的人，过着平凡的生活。爸爸工作很忙，但是每天下班回来都会先问候妈妈。妈妈也会等爸爸回来一起吃晚饭。他们偶尔也会吵架，但是很快就会和好。我觉得这就是爱情最真实的样子。不需要太多的甜言蜜语，只需要在对方需要的时候，陪在他身边，给他一个拥抱，一句温暖的话。等我长大了，我也希望能找到这样一个简单而又温暖的爱情。',
        'dialogues' => [
            ['who' => '王小明', 'cn' => '王爷爷，您买花送给谁呀？', 'vi' => 'Ông Vương ơi, ông mua hoa tặng ai thế?'],
            ['who' => '王爷爷', 'cn' => '今天是我和你奶奶结婚四十周年纪念日。', 'vi' => 'Hôm nay là kỷ niệm bốn mươi năm ngày cưới của ông và bà.'],
            ['who' => '王小明', 'cn' => '真浪漫！奶奶一定会很开心的。', 'vi' => 'Thật lãng mạn! Bà nhất định sẽ rất vui.'],
            ['who' => '王爷爷', 'cn' => '其实爱情不一定要多浪漫，互相陪伴最重要。', 'vi' => 'Thực ra tình yêu không nhất thiết phải lãng mạn, quan trọng nhất là bầu bạn với nhau.'],
            ['who' => '王小明', 'cn' => '您和奶奶结婚这么多年，有什么秘诀吗？', 'vi' => 'Ông và bà kết hôn bao nhiêu năm nay, có bí quyết gì không?'],
            ['who' => '王爷爷', 'cn' => '秘诀就是互相包容，互相理解。', 'vi' => 'Bí quyết là bao dung lẫn nhau, thấu hiểu lẫn nhau.'],
            ['who' => '王小明', 'cn' => '您说得真对。谢谢您，我明白了。', 'vi' => 'Ông nói đúng quá. Cảm ơn ông, cháu hiểu rồi.'],
        ],
        'grammar' => [
            ['point' => 'Cấu trúc 虽然...但是... (mặc dù...nhưng...)', 'explain' => '虽然...但是... diễn tả quan hệ nhượng bộ, tương phản. 虽然 chỉ mệnh đề nhượng bộ (điều đã được thừa nhận), 但是 chỉ kết quả trái ngược với suy luận thông thường. Cấu trúc: 虽然 + Mệnh đề 1, 但是/可是 + Mệnh đề 2. Lưu ý: Trong tiếng Trung, 虽然 và 但是 có thể xuất hiện cùng nhau, không giống tiếng Việt (mặc dù...nhưng). Có thể bỏ 但是 nếu ngữ cảnh rõ ràng. 虽然 có thể đặt trước hoặc sau chủ ngữ.', 'examples' => ['虽然不是什么特别的日子，但是我想让她开心。Dù không phải ngày đặc biệt, nhưng tôi muốn làm cô ấy vui.', '虽然很累，但是他坚持工作。Dù rất mệt, nhưng anh ấy vẫn làm việc.', '虽然贵，但是质量好。Dù đắt, nhưng chất lượng tốt.']],
            ['point' => 'Cấu trúc 其实 (thực ra, kỳ thực)', 'explain' => '其实 là phó từ mang nghĩa "thực ra, kỳ thực", dùng để đưa ra sự thật tương phản với nhận định trước đó hoặc thông thường. Nó thường đứng đầu câu hoặc trước động từ. 其实 rất phổ biến trong khẩu ngữ, dùng để: (1) tiết lộ sự thật: 其实我没去 (Thực ra tôi đã không đi). (2) đính chính hiểu lầm: 其实他不是坏人 (Thực ra anh ấy không phải người xấu). (3) nêu ra quan điểm cá nhân: 其实爱情不需要多浪漫 (Thực ra tình yêu không cần quá lãng mạn).', 'examples' => ['其实爱情不需要多浪漫。Thực ra tình yêu không cần quá lãng mạn.', '其实他没告诉我。Thực ra anh ấy không nói với tôi.', '其实很简单。Thực ra rất đơn giản.']],
            ['point' => 'Cấu trúc 不是...而是... (không phải...mà là...)', 'explain' => '不是...而是... dùng để phủ định một điều và khẳng định một điều khác. Cấu trúc: 不是 + A + 而是 + B (không phải A mà là B). Ví dụ: 不是多浪漫，而是互相陪伴 (Không phải là lãng mạn, mà là bầu bạn với nhau). 这不是我的错，而是他的错 (Đây không phải lỗi của tôi mà là lỗi của anh ấy). Cấu trúc này nhấn mạnh sự đối lập giữa điều bị phủ định và điều được khẳng định. 而是 không thể thay thế bằng 但是 trong cấu trúc này.', 'examples' => ['不是多浪漫，而是互相陪伴。Không phải lãng mạn, mà là bầu bạn.', '不是我的错，而是他的。Không phải lỗi của tôi, mà là của anh ấy.', '不是不想去，而是没时间。Không phải không muốn đi, mà là không có thời gian.']],
        ],
