            ['w' => '浪漫', 'p' => 'làngmàn', 'm' => 'lãng mạn', 'pos' => '形容词', 'ex' => ['你真浪漫。Bạn thật lãng mạn.', '这个约会很浪漫。Buổi hẹn hò này rất lãng mạn.']],
            ['w' => '结婚', 'p' => 'jié hūn', 'm' => 'kết hôn', 'pos' => '动词', 'ex' => ['他们结婚四十年了。Họ kết hôn bốn mươi năm rồi.', '你结婚了吗？Bạn kết hôn chưa?']],
            ['w' => '纪念日', 'p' => 'jìniànrì', 'm' => 'ngày kỷ niệm', 'pos' => '名词', 'ex' => ['今天是结婚纪念日。Hôm nay là ngày kỷ niệm cưới.', '这个纪念日很有意义。Ngày kỷ niệm này rất ý nghĩa.']],
