    32 => [
        'title' => 'Bài 32: 真正的朋友 - Người bạn thực sự',
        'text' => '人们常说："在家靠父母，出门靠朋友。"朋友在我们的人生中扮演着非常重要的角色。但是什么样的朋友才是真正的朋友呢？我有一个从小一起长大的好朋友，叫陈刚。我们小学、中学都在一个学校，虽然大学不在一起，但是我们一直保持联系。上个月我遇到了一些困难，心情非常不好。我参加了一个重要的考试，但是没有通过。这让我很失落，觉得自己很失败。陈刚知道以后，专门从另一个城市坐火车来看我。他陪了我一整天，听我倾诉，安慰我，鼓励我。他说："失败是成功之母。这次没考好没关系，下次再努力。重要的是你已经尽力了。"他帮我分析失败的原因，还帮我制定了新的学习计划。那一刻我很感动，真正体会到了什么是朋友。真正的朋友不是锦上添花，而是雪中送炭。在你得意的时候，朋友为你高兴；在你失意的时候，朋友陪在你身边，给你鼓励和支持。其实我们不需要很多朋友，只要有几个真正的知己就足够了。我也希望自己能成为别人的好朋友，在朋友需要的时候，能够伸出援手，给他温暖和力量。朋友之间最重要的是真诚和信任。有了这些，友谊才能长久。',
        'dialogues' => [
            ['who' => '陈刚', 'cn' => '小明，听说你考试没通过，我过来看看你。', 'vi' => 'Tiểu Minh, nghe nói bạn thi không qua, tôi đến thăm bạn.'],
            ['who' => '王小明', 'cn' => '你怎么来了？这么远的路，太麻烦你了。', 'vi' => 'Sao bạn lại đến? Đường xa thế này, làm phiền bạn quá.'],
            ['who' => '陈刚', 'cn' => '朋友之间不要说麻烦。你还好吗？', 'vi' => 'Giữa bạn bè đừng nói phiền. Bạn vẫn ổn chứ?'],
            ['who' => '王小明', 'cn' => '说实话，我挺难受的。准备了那么久，还是没考好。', 'vi' => 'Nói thật, tôi khá khó chịu. Chuẩn bị lâu như vậy, vẫn thi không tốt.'],
            ['who' => '陈刚', 'cn' => '别灰心。一次失败不代表什么。我们一起分析一下原因。', 'vi' => 'Đừng nản lòng. Một lần thất bại không có nghĩa gì. Chúng ta cùng phân tích nguyên nhân.'],
            ['who' => '王小明', 'cn' => '你真好，特意过来陪我。', 'vi' => 'Bạn thật tốt, cố ý đến bầu bạn với tôi.'],
            ['who' => '陈刚', 'cn' => '这就是朋友应该做的。记住，真正的朋友会在你最需要的时候出现。', 'vi' => 'Đây là việc bạn bè nên làm. Hãy nhớ, bạn thực sự sẽ xuất hiện lúc bạn cần nhất.'],
            ['who' => '王小明', 'cn' => '谢谢你，陈刚。有你这个朋友真好。', 'vi' => 'Cảm ơn bạn, Trần Cương. Có người bạn như bạn thật tốt.'],
        ],
        'grammar' => [
            ['point' => 'Cấu trúc 不是...而是... (không phải...mà là...)', 'explain' => 'Cấu trúc này đã giới thiệu ở bài 31. Trong bài này: 不是锦上添花，而是雪中送炭 (Không phải thêm hoa trên gấm, mà là tặng than trong tuyết — giúp đỡ khi người gặp khó khăn). Đây là một cấu trúc phổ biến để đối lập hai khái niệm. 而是 không thể thay bằng 但是. Nếu muốn nối hai mệnh đề có quan hệ tương phản nhẹ, dùng 但是; nếu muốn phủ định cái trước và khẳng định cái sau, dùng 不是...而是...', 'examples' => ['不是锦上添花，而是雪中送炭。Không phải thêm hoa lên gấm, mà là gửi than trong tuyết.', '不是我不想帮你，而是我没办法。Không phải tôi không muốn giúp bạn, mà là tôi không có cách.', '这不是你的错，而是我的。Đây không phải lỗi của bạn, mà là của tôi.']],
            ['point' => 'Cấu trúc 只要...就... (chỉ cần...là...)', 'explain' => '只要...就... diễn tả điều kiện đủ. Trong bài: 只要有真诚和信任，友谊就能长久 (Chỉ cần có chân thành và tin tưởng, tình bạn mới có thể lâu dài). Lưu ý: 只要 + điều kiện, 就 + kết quả. Động từ sau 就 có thể ở dạng khẳng định hoặc phủ định. 只要 nhấn mạnh điều kiện là đủ, không cần điều kiện khác. So sánh: 只有...才... (chỉ có...mới...) mang tính điều kiện cần, mạnh hơn 只要...就...', 'examples' => ['只要努力，就一定能成功。Chỉ cần cố gắng, nhất định sẽ thành công.', '只要有朋友在，我就不怕。Chỉ cần có bạn bè ở đây, tôi không sợ.', '只要你开口，我就帮你。Chỉ cần bạn mở miệng, tôi sẽ giúp bạn.']],
            ['point' => 'Cấu trúc 在 + Địa điểm / Thời gian (ở / vào)', 'explain' => 'Giới từ 在 dùng để chỉ địa điểm, thời gian hoặc phạm vi. Trong bài: 在朋友需要的时候 (khi bạn bè cần). Cấu trúc: 在 + (Thời gian/Địa điểm) + Động từ. 在 có thể dùng với tân ngữ chỉ thời gian: 在早上 (vào buổi sáng), 在三天前 (ba ngày trước). Với địa điểm: 在学校 (ở trường). Trong câu tồn tại: 在 + Địa điểm + 有 + Người/Vật. Lưu ý: 在 cũng là động từ chỉ vị trí: 我在家 (Tôi ở nhà).', 'examples' => ['在朋友需要的时候帮助他。Giúp bạn bè khi họ cần.', '在学校里有很多朋友。Ở trường có rất nhiều bạn.', '在困难的时候不要放弃。Khi gặp khó khăn đừng từ bỏ.']],
        ],
        'pronunciation' => ['focus' => 'tone pairs 4-4', 'drill' => ['bì yè', 'dàn shì', 'fàng sōng', 'guì zhòng', 'jì huà', 'lì hai', 'mào yi', 'pèi hé']],
        'vocab' => [
            ['w' => '真正', 'p' => 'zhēnzhèng', 'm' => 'thực sự, đích thực', 'pos' => '形容词', 'ex' => ['真正的朋友是在你需要时出现。Bạn thực sự xuất hiện khi bạn cần.', '这是我真正想要的。Đây là điều tôi thực sự muốn.']],
            ['w' => '朋友', 'p' => 'péngyou', 'm' => 'bạn bè', 'pos' => '名词', 'ex' => ['真正的朋友很难得。Bạn thực sự rất khó có.', '我们是好朋友。Chúng tôi là bạn tốt.']],
            ['w' => '困难', 'p' => 'kùnnan', 'm' => 'khó khăn', 'pos' => '名词,形容词', 'ex' => ['遇到困难不要怕。Gặp khó khăn đừng sợ.', '克服困难才能成长。Vượt qua khó khăn mới trưởng thành.']],
            ['w' => '失败', 'p' => 'shībài', 'm' => 'thất bại', 'pos' => '动词,名词', 'ex' => ['失败是成功之母。Thất bại là mẹ thành công.', '从失败中学习。Học từ thất bại.']],
            ['w' => '鼓励', 'p' => 'gǔlì', 'm' => 'khuyến khích, động viên', 'pos' => '动词,名词', 'ex' => ['谢谢你的鼓励。Cảm ơn sự động viên của bạn.', '朋友之间要互相鼓励。Bạn bè phải động viên nhau.']],
