    33 => [
        'title' => 'Bài 33: 读书和教育 - Đọc sách và giáo dục',
        'text' => '从小父母就教育我，要多读书，读好书。他们认为读书是改变命运的重要途径。我的爸爸小时候家里很穷，没有钱上学，所以他很重视我的教育。他常常对我说："孩子，你要好好学习。知识改变命运，读书成就未来。"虽然这些话听起来很老套，但是随着我慢慢长大，我越来越理解了爸爸的意思。读书确实让人受益无穷。通过读书，我们可以了解世界各地的文化，学习前人的智慧和经验。每一本书都像一扇窗户，打开了我们的眼界。我小的时候不太喜欢读书，觉得书本很无聊。但是有一天，妈妈给我买了一本《哈利·波特》，我一下子就被吸引住了。从那以后，我迷上了阅读，开始读各种各样的书。有小说、历史书、科普书，还有人物传记。每一本书都带给我不同的感受和收获。现在我已经养成了每天读书的习惯。每天晚上睡觉前，我都会看半小时的书。这个习惯已经坚持了好几年了。读书不仅提高了我的语文水平，还让我学到了很多课本上学不到的知识。我还发现，当我心情不好的时候，读书可以让我静下心来。书就像一位好朋友，任何时候都不会离开你。我希望更多的人能爱上读书，享受阅读的乐趣。',
        'dialogues' => [
            ['who' => '爸爸', 'cn' => '孩子，作业写完了吗？', 'vi' => 'Con ơi, bài tập viết xong chưa?'],
            ['who' => '王小明', 'cn' => '写完了。爸爸，我能看会儿电视吗？', 'vi' => 'Viết xong rồi. Bố ơi, con có thể xem tivi một lát không?'],
            ['who' => '爸爸', 'cn' => '电视有什么好看的？不如去看看书。', 'vi' => 'Tivi có gì hay đâu? Thà đi đọc sách còn hơn.'],
            ['who' => '王小明', 'cn' => '可是我不太喜欢看书，觉得很无聊。', 'vi' => 'Nhưng con không thích đọc sách lắm, thấy rất chán.'],
            ['who' => '爸爸', 'cn' => '那是因为你没找到自己喜欢的书。多读几本试试。', 'vi' => 'Đó là vì con chưa tìm được sách mình thích. Đọc thử vài cuốn xem.'],
            ['who' => '王小明', 'cn' => '爸爸，您小时候喜欢读书吗？', 'vi' => 'Bố ơi, hồi nhỏ bố có thích đọc sách không?'],
            ['who' => '爸爸', 'cn' => '爸爸小时候家里穷，没机会读很多书。所以你要珍惜现在的机会。', 'vi' => 'Bố hồi nhỏ nhà nghèo, không có cơ hội đọc nhiều sách. Vì vậy con phải trân trọng cơ hội bây giờ.'],
            ['who' => '王小明', 'cn' => '我知道了。爸爸，您给我推荐一本书吧。', 'vi' => 'Con biết rồi. Bố ơi, bố giới thiệu cho con một cuốn sách đi.'],
            ['who' => '爸爸', 'cn' => '《小王子》就不错，你可以看看。', 'vi' => '"Hoàng tử bé" không tệ đâu, con có thể xem.'],
        ],
        'grammar' => [
            ['point' => 'Cấu trúc 不仅...还... (không chỉ...mà còn...)', 'explain' => '不仅...还/而且... diễn tả "không chỉ...mà còn...". Cấu trúc này dùng để nối hai nội dung cùng hướng, nội dung sau thường mạnh hơn. Ví dụ: 读书不仅提高了我的语文水平，还让我学到了很多知识 (Đọc sách không chỉ nâng cao trình độ tiếng Trung mà còn giúp tôi học được nhiều kiến thức). 不仅 có thể đặt trước chủ ngữ hoặc sau chủ ngữ. Khi hai mệnh đề có chung chủ ngữ, 不仅 đặt sau chủ ngữ. Khi chủ ngữ khác nhau, 不仅 đặt trước chủ ngữ thứ nhất.', 'examples' => ['读书不仅有趣，还有很多收获。Đọc sách không chỉ thú vị, mà còn có nhiều thu hoạch.', '他不仅聪明，而且很努力。Anh ấy không chỉ thông minh mà còn rất cố gắng.', '这不仅是你的事，也是我的事。Đây không chỉ là việc của bạn, mà còn là việc của tôi.']],
            ['point' => 'Cấu trúc 随着... (theo / cùng với)', 'explain' => '随着 là giới từ mang nghĩa "theo, cùng với, trong quá trình". Cấu trúc: 随着 + Danh từ / Mệnh đề. Ví dụ: 随着我慢慢长大 (Cùng với việc tôi lớn lên). 随着社会的发展 (Cùng với sự phát triển của xã hội). 随着 thường dùng trong văn viết, mang sắc thái trang trọng. Không dùng 随着 trong câu chỉ phương hướng vật lý (dùng 沿着 hoặc 跟着). 随着 thường kết hợp với 越来越 để diễn tả sự thay đổi đồng thời.', 'examples' => ['随着年龄的增长，我越来越理解父母。Cùng với tuổi tác tăng lên, tôi càng hiểu cha mẹ hơn.', '随着社会的发展，生活越来越好。Cùng với phát triển xã hội, cuộc sống càng tốt hơn.', '随着音乐的节奏跳舞。Nhảy theo nhịp điệu âm nhạc.']],
            ['point' => 'Cấu trúc 养成...的习惯 (hình thành thói quen...)', 'explain' => '养成...的习惯 có nghĩa "hình thành thói quen...". Cấu trúc: 养成 + Tính từ + 的 + 习惯. Ví dụ: 养成读书的习惯 (hình thành thói quen đọc sách). 养成好习惯 (hình thành thói quen tốt). Đây là cụm động từ cố định, rất thông dụng. Sau 养成 là danh từ chỉ thói quen. 养成 thường không dùng với thói quen xấu (với thói quen xấu dùng 养成 thường có sắc thái trung tính, hoặc dùng 染上 cho thói quen xấu).', 'examples' => ['我养成了每天读书的习惯。Tôi đã hình thành thói quen đọc sách mỗi ngày.', '要从小养成好习惯。Phải hình thành thói quen tốt từ nhỏ.', '他养成了早起的习惯。Anh ấy hình thành thói quen dậy sớm.']],
        ],
        'pronunciation' => ['focus' => 'tone pairs 2-4', 'drill' => ['qián miàn', 'shí jiàn', 'chéng shì', 'huán jìng', 'píng jià', 'xué xí', 'míng tiān', 'guó jiā']],
