            ['w' => '知识', 'p' => 'zhīshi', 'm' => 'kiến thức', 'pos' => '名词', 'ex' => ['知识改变命运。Kiến thức thay đổi số phận.', '学习知识很重要。Học kiến thức rất quan trọng.']],
