    34 => [
        'title' => 'Bài 34: 生活的味道 - Hương vị cuộc sống',
        'text' => '有人说生活就像一杯茶，有苦也有甜。以前我不太明白这句话的意思，但是经历了生活的酸甜苦辣以后，我才慢慢体会到其中的道理。每个人对生活的味道都有不同的感受。对于一个饥饿的人来说，一碗热腾腾的米饭就是最大的幸福。对于一个生病的人来说，健康就是他最渴望的东西。而对于一个忙碌的上班族来说，周末能好好睡个懒觉就是最奢侈的事情。我妈妈是一个普通的中年妇女，她的生活很忙碌。每天她都要早起给我们做早饭，然后去上班，下班回来还要做晚饭、做家务。看起来她的生活很辛苦，但是她从来没有抱怨过。有一天我问妈妈："妈妈，您每天这么忙，觉得辛苦吗？"妈妈笑了笑说："辛苦是辛苦，但是看到你和爸爸吃得开心，我就觉得很满足。生活的味道就是酸甜苦辣都要尝一尝。没有苦，哪里来的甜呢？"妈妈的话深深地印在了我的心里。是啊，生活本来就是酸甜苦辣都有。考试考好了是甜的，和朋友吵架了是酸的，遇到困难是苦的，受到批评是辣的。正是因为有了这些不同的味道，生活才变得丰富多彩。如果我们只想要甜，拒绝其他味道，那生活反而会变得单调。所以我们应该学会接受生活的各种味道，好好地品尝每一天。',
        'dialogues' => [
            ['who' => '王小明', 'cn' => '妈妈，您每天这么忙，觉得辛苦吗？', 'vi' => 'Mẹ ơi, mẹ mỗi ngày bận rộn thế này, có thấy vất vả không?'],
            ['who' => '妈妈', 'cn' => '辛苦是辛苦，但是看到你们开心，我就满足了。', 'vi' => 'Vất vả là vất vả, nhưng thấy các con vui là mẹ hài lòng rồi.'],
            ['who' => '王小明', 'cn' => '您觉得生活是什么味道的？', 'vi' => 'Mẹ thấy cuộc sống có vị gì?'],
            ['who' => '妈妈', 'cn' => '生活就像一道菜，酸甜苦辣都要尝。', 'vi' => 'Cuộc sống giống như một món ăn, chua ngọt đắng cay đều phải nếm.'],
            ['who' => '王小明', 'cn' => '可是我不喜欢苦的味道。', 'vi' => 'Nhưng con không thích vị đắng.'],
            ['who' => '妈妈', 'cn' => '没有苦，怎么知道甜的可贵呢？', 'vi' => 'Không có đắng, sao biết được quý giá của ngọt?'],
            ['who' => '王小明', 'cn' => '您说得对。每一种味道都值得体验。', 'vi' => 'Mẹ nói đúng. Mỗi một vị đều đáng trải nghiệm.'],
            ['who' => '妈妈', 'cn' => '是啊，好好享受生活的每一天吧。', 'vi' => 'Phải đấy, hãy tận hưởng mỗi ngày của cuộc sống.'],
        ],
        'grammar' => [
            ['point' => 'Cấu trúc 不仅没有...反而... (không những không...mà còn...)', 'explain' => 'Cấu trúc này diễn tả sự việc không chỉ không xảy ra theo hướng dự kiến, mà ngược lại còn đi theo hướng khác. 反而 có nghĩa "ngược lại". Cấu trúc: 不但/不仅 + 没有/不 + Mệnh đề 1 + 反而 + Mệnh đề 2. Ví dụ: 她不仅没有生气，反而笑了 (Cô ấy không những không giận, mà ngược lại còn cười). Cần phân biệt 反而 với 而且: 而且 chỉ bổ sung thêm, 反而 chỉ hướng ngược lại.', 'examples' => ['他不仅没有生气，反而笑了。Anh ấy không những không giận, mà còn cười.', '听了他的话，我反而更难过了。Nghe lời anh ấy, tôi càng buồn hơn.', '吃了药以后，病情反而更严重了。Uống thuốc xong, bệnh tình càng nặng hơn.']],
            ['point' => 'Cấu trúc 值得 + Động từ (đáng làm gì)', 'explain' => '值得 là động từ mang nghĩa "đáng, xứng đáng". Cấu trúc: 值得 + Động từ / Danh từ. Ví dụ: 值得体验 (đáng trải nghiệm), 值得尝试 (đáng thử). Lưu ý: 值得 không thể đứng một mình làm vị ngữ, phải đi kèm với thành phần khác. Phủ định: 不值得 (không đáng). Trong khẩu ngữ cũng có thể dùng 值或不值 để hỏi: 值不值得? (Có đáng không?) 值得 thường dùng trong đánh giá chủ quan về giá trị.', 'examples' => ['这本书值得一看。Cuốn sách này đáng đọc.', '这个地方值得去。Nơi này đáng đi.', '付出是值得的。Sự cống hiến là xứng đáng.']],
            ['point' => 'Cấu trúc 在...中 (trong...)', 'explain' => '在...中 dùng để chỉ phạm vi, môi trường, hoặc quá trình. Cấu trúc: 在 + Danh từ / Cụm danh từ + 中. Ví dụ: 在生活中 (trong cuộc sống), 在困难中 (trong khó khăn). 在...中 có thể thay thế bằng 在...里 trong nhiều trường hợp, nhưng 中 mang sắc thái trừu tượng hơn. Khi chỉ quá trình: 在发展中 (trong quá trình phát triển). Khi chỉ trạng thái: 在忙碌中 (trong bận rộn). 在...中 thường đứng đầu câu.', 'examples' => ['在生活中，我们会遇到很多困难。Trong cuộc sống, chúng ta sẽ gặp nhiều khó khăn.', '在忙碌中也要休息。Trong bận rộn cũng phải nghỉ ngơi.', '在学习中不断进步。Không ngừng tiến bộ trong học tập.']],
        ],
        'pronunciation' => ['focus' => 'tone pairs 3-3', 'drill' => ['yǔ fǎ', 'kě yǐ', 'nǐ hǎo', 'lǎo shī', 'yǒng gǎn', 'jiǎn dān', 'yǐng xiǎng', 'gǎn xiè']],
        'vocab' => [
            ['w' => '味道', 'p' => 'wèidào', 'm' => 'mùi vị, hương vị', 'pos' => '名词', 'ex' => ['生活的味道很丰富。Hương vị cuộc sống rất phong phú.', '这道菜味道不错。Món này hương vị không tệ.']],
            ['w' => '酸甜苦辣', 'p' => 'suān tián kǔ là', 'm' => 'chua ngọt đắng cay', 'pos' => '成语', 'ex' => ['人生有酸甜苦辣。Đời người có chua ngọt đắng cay.', '酸甜苦辣都要尝。Chua ngọt đắng cay đều phải nếm.']],
            ['w' => '经历', 'p' => 'jīnglì', 'm' => 'trải qua, kinh qua', 'pos' => '动词,名词', 'ex' => ['我经历了很多。Tôi đã trải qua nhiều điều.', '丰富的经历很宝贵。Kinh nghiệm phong phú rất quý.']],
            ['w' => '体会', 'p' => 'tǐhuì', 'm' => 'thể hội, cảm nhận', 'pos' => '动词', 'ex' => ['我体会到了生活的不易。Tôi cảm nhận được sự không dễ của cuộc sống.', '你体会过这种感觉吗？Bạn đã từng có cảm giác này chưa?']],
            ['w' => '感受', 'p' => 'gǎnshòu', 'm' => 'cảm nhận', 'pos' => '动词,名词', 'ex' => ['我感受到了幸福。Tôi cảm nhận được hạnh phúc.', '你有什么感受？Bạn có cảm nhận gì?']],
            ['w' => '满足', 'p' => 'mǎnzú', 'm' => 'thỏa mãn, hài lòng', 'pos' => '形容词,动词', 'ex' => ['我很满足。Tôi rất hài lòng.', '不要满足于现状。Đừng thỏa mãn với hiện trạng.']],
