            ['w' => '辛苦', 'p' => 'xīnkǔ', 'm' => 'vất vả, cực khổ', 'pos' => '形容词', 'ex' => ['你辛苦了！Bạn vất vả rồi!', '妈妈很辛苦。Mẹ rất vất vả.']],
