            ['w' => '接受', 'p' => 'jiēshòu', 'm' => 'tiếp nhận, chấp nhận', 'pos' => '动词', 'ex' => ['接受生活的挑战。Chấp nhận thử thách cuộc sống.', '我接受你的建议。Tôi chấp nhận lời khuyên của bạn.']],
            ['w' => '珍惜', 'p' => 'zhēnxī', 'm' => 'trân trọng', 'pos' => '动词', 'ex' => ['珍惜每一刻。Trân trọng từng khoảnh khắc.', '要珍惜身边的人。Phải trân trọng người bên cạnh.']],
            ['w' => '品尝', 'p' => 'pǐncháng', 'm' => 'nếm thử, thưởng thức', 'pos' => '动词', 'ex' => ['品尝生活的味道。Thưởng thức hương vị cuộc sống.', '请品尝这道菜。Xin hãy nếm thử món này.']],
            ['w' => '多彩', 'p' => 'duōcǎi', 'm' => 'nhiều màu sắc, đa dạng', 'pos' => '形容词', 'ex' => ['生活丰富多彩。Cuộc sống đa dạng màu sắc.', '世界是多彩的。Thế giới đầy màu sắc.']],
