    35 => [
        'title' => 'Bài 35: 工作的乐趣 - Niềm vui trong công việc',
        'text' => '很多人觉得工作只是为了赚钱，是一件不得不做的事情。但是我认为，如果能够找到一份自己喜欢的工作，工作就会变成一种享受。我的舅舅是一名摄影师，他从小就喜欢拍照。他说他每天去上班都充满了期待，因为他不知道今天会遇到什么样的人，拍出什么样的照片。他的工作虽然很辛苦，经常要扛着沉重的器材到处跑，有时候为了拍一张好照片还要等好几个小时。但是他觉得很值得，因为他做着自己热爱的工作。有一次我问舅舅："您觉得工作最大的乐趣是什么？"舅舅想了想说："工作的乐趣不是赚多少钱，而是当你完成一个作品的时候，那种成就感和满足感是金钱买不到的。而且通过工作，你可以认识不同的人，了解不同的文化，这些经历本身就是一种财富。"舅舅的话让我对工作有了新的认识。我也开始思考自己将来想做什么样的工作。我不想只是为了钱而工作，我想做一份能够发挥我的特长，同时也对社会有意义的工作。我现在正在努力学习，为了将来能实现自己的梦想。我相信只要朝着目标努力，总有一天能找到属于我的那份有意义的工作。工作不仅仅是为了生存，更是实现自我价值的方式。当我们热爱自己的工作，每天都会充满动力，生活也会变得更加充实和快乐。',
        'dialogues' => [
            ['who' => '王小明', 'cn' => '舅舅，您喜欢您的工作吗？', 'vi' => 'Cậu ơi, cậu có thích công việc của mình không?'],
            ['who' => '舅舅', 'cn' => '当然喜欢！如果我不喜欢，也不会坚持这么多年。', 'vi' => 'Đương nhiên thích! Nếu không thích, cậu cũng không kiên trì bao nhiêu năm nay.'],
            ['who' => '王小明', 'cn' => '当摄影师最开心的是什么？', 'vi' => 'Làm nhiếp ảnh gia, điều vui nhất là gì?'],
            ['who' => '舅舅', 'cn' => '最开心的是拍出让自己满意的照片，看到别人喜欢你的作品。', 'vi' => 'Vui nhất là chụp được bức ảnh mình hài lòng và thấy người khác thích tác phẩm của mình.'],
