        'grammar' => [
            ['point' => 'Cấu trúc 如果...就... (nếu...thì...)', 'explain' => '如果...就... diễn tả điều kiện và kết quả. Cấu trúc: 如果 + Điều kiện + 就 + Kết quả. Ví dụ: 如果我能找到喜欢的工作，工作就会变成享受 (Nếu tôi có thể tìm được công việc yêu thích, công việc sẽ trở thành sự hưởng thụ). 有时候 如果 có thể lược bỏ, chỉ dùng 就. Trong văn nói, 如果 thường được thay bằng 要是. Phân biệt: 如果 giả định có khả năng xảy ra, 假如 giả định khó xảy ra hơn. 就 đứng trước kết quả, có thể thêm 会/能.', 'examples' => ['如果你努力，就一定能成功。Nếu bạn cố gắng, nhất định sẽ thành công.', '如果明天下雨，我就不去了。Nếu ngày mai mưa, tôi sẽ không đi.', '要是你喜欢，就拿去吧。Nếu bạn thích, hãy lấy đi.']],
            ['point' => 'Cấu trúc 为了... (để / vì mục đích...)', 'explain' => '为了 chỉ mục đích, nghĩa "để, vì". Cấu trúc: 为了 + Mục đích + Hành động. Ví dụ: 为了梦想而努力 (Cố gắng vì ước mơ). 为了健康，我每天运动 (Vì sức khỏe, tôi vận động mỗi ngày). 为了 có thể đứng trước hoặc sau chủ ngữ. Phân biệt 为了 và 因为: 因为 chỉ nguyên nhân (quá khứ), 为了 chỉ mục đích (tương lai). Ví dụ: 因为下雨，所以没去 (Vì mưa, nên không đi) — nguyên nhân. 为了学中文，我来了中国 (Để học tiếng Trung, tôi đến Trung Quốc) — mục đích.', 'examples' => ['为了梦想而努力。Cố gắng vì ước mơ.', '为了健康，我每天运动。Vì sức khỏe, tôi tập thể dục mỗi ngày.', '为了学好汉语，我每天练习。Để học tốt tiếng Trung, tôi luyện tập mỗi ngày.']],
            ['point' => 'Cấu trúc 只要...就... (chỉ cần...là...)', 'explain' => 'Như đã giới thiệu ở bài trước, 只要...就... diễn tả điều kiện đủ. Trong bài: 只要朝着目标努力，总有一天能找到 (Chỉ cần hướng tới mục tiêu cố gắng, một ngày nào đó sẽ tìm được). Cấu trúc nhấn mạnh điều kiện là đủ để mang lại kết quả. 只要 thường dùng với ý khích lệ, động viên. 总有一天 (một ngày nào đó) là cụm từ phổ biến, thường xuất hiện cùng 只要 để chỉ kết quả trong tương lai không xác định nhưng chắc chắn.', 'examples' => ['只要努力，总有一天会成功。Chỉ cần cố gắng, một ngày nào đó sẽ thành công.', '只要坚持，就能实现梦想。Chỉ cần kiên trì, có thể thực hiện ước mơ.', '只要不放弃，就有希望。Chỉ cần không từ bỏ, là có hy vọng.']],
        ],
        'pronunciation' => ['focus' => 'tone pairs 4-3', 'drill' => ['diàn nǎo', 'fù mǔ', 'gù shi', 'hàn yǔ', 'jì zhě', 'mèi mei', 'nài xīn', 'pèi hé']],
        'vocab' => [
