            ['w' => '动力', 'p' => 'dònglì', 'm' => 'động lực', 'pos' => '名词', 'ex' => ['热爱是最好的动力。Yêu thích là động lực tốt nhất.', '我需要动力。Tôi cần động lực.']],
            ['w' => '充实', 'p' => 'chōngshí', 'm' => 'phong phú, đầy đặn', 'pos' => '形容词,动词', 'ex' => ['生活很充实。Cuộc sống rất phong phú.', '读书充实了我的生活。Đọc sách làm phong phú cuộc sống của tôi.']],
