    36 => [
        'title' => 'Bài 36: 健康与运动 - Sức khỏe và vận động',
        'text' => '健康是我们生活中最重要的事情之一。没有健康的身体，就很难享受生活的乐趣。我的医生告诉我，每天运动三十分钟对健康非常有好处。他建议我每周至少运动三次，可以跑步、游泳或者打篮球。我以前不太喜欢运动，觉得运动很累。但是自从开始运动以后，我发现自己的身体越来越好了，精神也越来越好。我现在每天早上起床后都会去公园跑步半小时。公园里空气新鲜，有很多人在晨练，有的打太极拳，有的跳舞，有的跑步。看到大家都在努力保持健康，我也更有动力了。除了运动，饮食也很重要。医生建议我们多吃蔬菜水果，少吃油腻和甜食。还要多喝水，保证充足的睡眠。健康的生活方式不仅让我们的身体更健康，也让心情更愉快。我决定要坚持运动，注意饮食，保持健康的生活习惯。希望每个人都能拥有健康的身体和快乐的生活。运动和不运动的人生是完全不一样的，健康的身体是实现一切梦想的基础。',
        'dialogues' => [
            ['who' => '医生', 'cn' => '你的身体怎么样？最近有没有运动？', 'vi' => 'Sức khỏe của bạn thế nào? Gần đây có tập thể dục không?'],
            ['who' => '王小明', 'cn' => '最近比较忙，没有时间运动。', 'vi' => 'Gần đây khá bận, không có thời gian vận động.'],
            ['who' => '医生', 'cn' => '运动对健康非常重要，建议你每周至少运动三次。', 'vi' => 'Vận động rất quan trọng cho sức khỏe, khuyên bạn mỗi tuần ít nhất vận động ba lần.'],
            ['who' => '王小明', 'cn' => '什么样的运动比较好呢？', 'vi' => 'Loại vận động nào tốt hơn?'],
            ['who' => '医生', 'cn' => '跑步、游泳、打太极拳都不错，选择你喜欢的就好。', 'vi' => 'Chạy bộ, bơi lội, tập thái cực quyền đều tốt, chọn môn bạn thích là được.'],
            ['who' => '王小明', 'cn' => '我决定明天开始跑步。', 'vi' => 'Tôi quyết định từ ngày mai bắt đầu chạy bộ.'],
            ['who' => '医生', 'cn' => '很好！坚持最重要，不要三天打鱼两天晒网。', 'vi' => 'Rất tốt! Kiên trì là quan trọng nhất, đừng ba ngày đánh cá hai ngày phơi lưới.'],
            ['who' => '王小明', 'cn' => '饮食方面需要注意什么？', 'vi' => 'Về ăn uống cần chú ý gì?'],
            ['who' => '医生', 'cn' => '多吃蔬菜水果，少吃油腻的，多喝水。', 'vi' => 'Ăn nhiều rau củ quả, ăn ít đồ dầu mỡ, uống nhiều nước.'],
            ['who' => '王小明', 'cn' => '好的，我记住了，谢谢医生！', 'vi' => 'Vâng, tôi nhớ rồi, cảm ơn bác sĩ!'],
        ],
        'grammar' => [
            ['point' => 'Cấu trúc 建议 + ai + động từ (khuyên ai làm gì)', 'explain' => '建议 có nghĩa là "khuyên, đề nghị". Cấu trúc: Chủ ngữ + 建议 + người + động từ. Ví dụ: 医生建议我每天运动 (Bác sĩ khuyên tôi vận động mỗi ngày). Có thể nói 建议 + V而不 nói rõ người. 建议 theo sau có thể là một mệnh đề hoặc cụm động từ. Phân biệt với 劝: 劝 mang tính thuyết phục, khuyên can nhiều hơn.', 'examples' => ['医生建议我多运动。Bác sĩ khuyên tôi vận động nhiều.', '我建议你早点休息。Tôi khuyên bạn nghỉ ngơi sớm.', '老师建议我们多练习。Thầy khuyên chúng tôi luyện tập nhiều.']],
            ['point' => 'Cấu trúc 越来越... (càng ngày càng...)', 'explain' => '越来越... diễn tả sự thay đổi dần dần theo thời gian. Cấu trúc: 越来越 + Tính từ / Động từ tâm lý. Ví dụ: 身体越来越好 (Sức khỏe càng ngày càng tốt). 天气越来越热 (Thời tiết càng ngày càng nóng). Không dùng 很 hoặc 非常 sau 越来越. Có thể lặp lại: 身体越来越好，精神也越来越好.', 'examples' => ['天气越来越热。Thời tiết càng ngày càng nóng.', '身体越来越好。Sức khỏe càng ngày càng tốt.', '中文越来越难。Tiếng Trung càng ngày càng khó.']],
            ['point' => 'Cấu trúc 不仅...也/还... (không chỉ...mà còn...)', 'explain' => 'Cấu trúc này diễn tả "không chỉ...mà còn...". 不仅 + A + 也/还 + B. Ví dụ: 不仅让身体更健康，也让心情更愉快 (Không chỉ làm sức khỏe tốt hơn, mà còn làm tâm trạng vui vẻ hơn). A và B phải có cấu trúc tương đương. Có thể dùng 不但...而且... mang tính trang trọng hơn. 不仅 thường được dùng trong văn nói.', 'examples' => ['他不仅学习好，还喜欢运动。Anh ấy không chỉ học giỏi mà còn thích thể thao.', '不仅对身体好，对心情也好。Không chỉ tốt cho sức khỏe mà còn tốt cho tâm trạng.', '她不仅漂亮，而且聪明。Cô ấy không chỉ xinh đẹp mà còn thông minh.']],
        ],
        'pronunciation' => ['focus' => 'j/q/x differentiation', 'drill' => ['jī', 'qī', 'xī', 'jiā', 'qià', 'xià', 'jǔ', 'qù']],
