    37 => [
        'title' => 'Bài 37: 文化与传统 - Văn hóa và truyền thống',
        'text' => '中国是一个有着五千年历史的国家，有着丰富的传统文化。春节是中国最重要的传统节日，每年的农历正月初一就是春节。春节的时候，全家人都会聚在一起吃团圆饭，看春节联欢晚会。人们还会贴春联、放鞭炮、发红包。小孩子最喜欢春节，因为他们可以收到压岁钱。除了春节，还有很多传统节日，比如中秋节、端午节、元宵节等等。每个节日都有自己独特的习俗和故事。中秋节人们吃月饼、赏月；端午节吃粽子、赛龙舟；元宵节看花灯、猜灯谜。中国的传统文化不仅包括节日，还包括书法、国画、京剧、武术等。书法是中国特有的艺术形式，写毛笔字需要耐心和技巧。京剧是中国传统戏曲的代表，有着两百多年的历史。现在越来越多的外国人开始学习中国的传统文化，他们对中国的书法和武术特别感兴趣。作为一个中国人，我为自己的文化感到自豪。我们应该传承和发扬优秀的传统文化，让更多的人了解和喜爱中国文化。',
        'dialogues' => [
            ['who' => '大卫', 'cn' => '王小明，你能给我介绍一下春节吗？', 'vi' => 'Vương Tiểu Minh, bạn có thể giới thiệu cho tôi về Tết Nguyên Đán không?'],
            ['who' => '王小明', 'cn' => '当然可以。春节是中国最重要的节日，是一家人团聚的日子。', 'vi' => 'Đương nhiên có thể. Tết Nguyên Đán là ngày lễ quan trọng nhất của Trung Quốc, là ngày gia đình đoàn tụ.'],
            ['who' => '大卫', 'cn' => '春节一般做什么呢？', 'vi' => 'Tết Nguyên Đán thường làm gì?'],
            ['who' => '王小明', 'cn' => '贴春联、吃团圆饭、发红包、放鞭炮等等。', 'vi' => 'Dán câu đối xuân, ăn cơm đoàn viên, phát bao lì xì, đốt pháo v.v.'],
            ['who' => '大卫', 'cn' => '太有意思了！中秋节呢？', 'vi' => 'Thú vị quá! Thế Tết Trung Thu thì sao?'],
            ['who' => '王小明', 'cn' => '中秋节吃月饼、赏月，月亮又大又圆，代表团圆。', 'vi' => 'Tết Trung Thu ăn bánh trung thu, ngắm trăng, trăng tròn và to, tượng trưng cho đoàn viên.'],
            ['who' => '大卫', 'cn' => '你们还有端午节对吗？', 'vi' => 'Các bạn còn có Tết Đoan Ngọ đúng không?'],
            ['who' => '王小明', 'cn' => '是的，端午节吃粽子、赛龙舟，是为了纪念伟大的诗人屈原。', 'vi' => 'Đúng vậy, Tết Đoan Ngọ ăn bánh ú, đua thuyền rồng, để tưởng nhớ nhà thơ vĩ đại Khuất Nguyên.'],
            ['who' => '大卫', 'cn' => '中国的文化真是太丰富了！', 'vi' => 'Văn hóa Trung Quốc thật phong phú!'],
        ],
        'grammar' => [
            ['point' => 'Cấu trúc 除了...还... (ngoài...còn...)', 'explain' => '除了...还... có nghĩa "ngoài...còn...". 除了 + A + 还 + B, ý nói ngoài A ra còn có B. Ví dụ: 除了春节，还有很多传统节日 (Ngoài Tết Nguyên Đán, còn có nhiều ngày lễ truyền thống). Phân biệt 除了...以外 (cũng tương tự, mang tính trang trọng hơn).', 'examples' => ['除了中文，他还会说英语。Ngoài tiếng Trung, anh ấy còn nói được tiếng Anh.', '除了跑步，我还喜欢游泳。Ngoài chạy bộ, tôi còn thích bơi lội.', '除了春节，中秋节也是重要节日。Ngoài Tết Nguyên Đán, Tết Trung Thu cũng là ngày lễ quan trọng.']],
            ['point' => 'Cấu trúc 对...感兴趣 (cảm thấy hứng thú với...)', 'explain' => '对...感兴趣 là cụm từ cố định, nghĩa "cảm thấy hứng thú với...". 对 + đối tượng + 感兴趣. Ví dụ: 对书法感兴趣 (Cảm thấy hứng thú với thư pháp). Chủ ngữ có thể là người hoặc nhóm người. Phủ định thêm 不 trước 感: 不感兴趣.', 'examples' => ['我对中国文化很感兴趣。Tôi rất hứng thú với văn hóa Trung Quốc.', '他对书法不感兴趣。Anh ấy không hứng thú với thư pháp.', '外国人对武术很感兴趣。Người nước ngoài rất hứng thú với võ thuật.']],
            ['point' => 'Cấu trúc 为...感到自豪 (tự hào về...)', 'explain' => '为...感到自豪 diễn tả niềm tự hào về điều gì. 为 + đối tượng + 感到自豪. Ví dụ: 为自己的文化感到自豪 (Tự hào về văn hóa của mình). Có thể thay 自豪 bằng 骄傲 (cũng nghĩa tự hào, nhưng 骄傲 còn có nghĩa kiêu ngạo).', 'examples' => ['我为中国感到自豪。Tôi tự hào về Trung Quốc.', '父母为孩子感到骄傲。Cha mẹ tự hào về con cái.', '我们为祖国感到自豪。Chúng tôi tự hào về tổ quốc.']],
        ],
        'pronunciation' => ['focus' => 'an/ang distinction', 'drill' => ['bān', 'bāng', 'pán', 'páng', 'mán', 'máng', 'fán', 'fáng']],
        'vocab' => [
            ['w' => '文化', 'p' => 'wénhuà', 'm' => 'văn hóa', 'pos' => '名词', 'ex' => ['中国文化很丰富。Văn hóa Trung Quốc rất phong phú.', '学习不同的文化。Học các nền văn hóa khác nhau.']],
            ['w' => '传统', 'p' => 'chuántǒng', 'm' => 'truyền thống', 'pos' => '名词,形容词', 'ex' => ['传统节日很重要。Ngày lễ truyền thống rất quan trọng.', '保持传统美德。Giữ gìn mỹ đức truyền thống.']],
            ['w' => '节日', 'p' => 'jiérì', 'm' => 'ngày lễ', 'pos' => '名词', 'ex' => ['春节是重要节日。Tết Nguyên Đán là ngày lễ quan trọng.', '节日快乐！Chúc mừng ngày lễ!']],
            ['w' => '春节', 'p' => 'Chūn Jié', 'm' => 'Tết Nguyên Đán', 'pos' => '名词', 'ex' => ['春节全家团圆。Tết Nguyên Đán cả nhà đoàn tụ.', '春节快乐！Chúc mừng năm mới!']],
            ['w' => '团聚', 'p' => 'tuánjù', 'm' => 'đoàn tụ', 'pos' => '动词', 'ex' => ['春节是团聚的日子。Tết Nguyên Đán là ngày đoàn tụ.', '一家人团聚很开心。Cả nhà đoàn tụ rất vui.']],
