            ['w' => '粽子', 'p' => 'zòngzi', 'm' => 'bánh ú, bánh tét', 'pos' => '名词', 'ex' => ['端午节吃粽子。Tết Đoan Ngọ ăn bánh ú.', '我喜欢吃肉粽子。Tôi thích bánh ú nhân thịt.']],
