            ['w' => '武术', 'p' => 'wǔshù', 'm' => 'võ thuật', 'pos' => '名词', 'ex' => ['中国武术很有名。Võ thuật Trung Quốc rất nổi tiếng.', '他在学武术。Anh ấy đang học võ thuật.']],
