    38 => [
        'title' => 'Bài 38: 科技与生活 - Khoa học công nghệ và cuộc sống',
        'text' => '现代社会，科技发展非常迅速。智能手机、电脑、互联网已经成为我们生活中不可或缺的一部分。我记得小时候，人们还使用固定的电话，现在几乎人人都有手机。手机不仅用来打电话，还可以上网、拍照、购物、看视频、听音乐等等。互联网让世界变得更小了。以前人们要面对面交流，现在通过微信或QQ就可以随时随地和朋友聊天。在网上可以找到各种各样的信息，学习新的知识。电子商务的发展改变了人们的购物方式。现在人们可以在网上买东西，快递直接送到家门口，非常方便。不过科技发展也带来了一些问题。很多人花太多时间在手机上，沉迷于网络游戏和社交媒体，忽略了和家人朋友的面对面交流。长时间看屏幕也会影响眼睛健康。我认为科技是工具，我们应该合理使用它，既享受科技带来的便利，又不被科技控制。科技应该为生活服务，让人们的生活更美好。我们要学会平衡科技和生活的关系。',
        'dialogues' => [
            ['who' => '小红', 'cn' => '小明，你每天花多少时间在手机上？', 'vi' => 'Tiểu Minh, mỗi ngày cậu dành bao nhiêu thời gian trên điện thoại?'],
            ['who' => '王小明', 'cn' => '大概两三个小时吧，看新闻、聊天、学习。', 'vi' => 'Khoảng hai ba tiếng, xem tin tức, chat, học tập.'],
            ['who' => '小红', 'cn' => '我有时候会刷抖音刷很久，不知不觉就过了两个小时。', 'vi' => 'Tôi có lúc lướt Douyin lâu, không biết là đã qua hai tiếng.'],
            ['who' => '王小明', 'cn' => '是啊，手机太吸引人了。不过也要注意控制时间。', 'vi' => 'Đúng vậy, điện thoại quá thu hút. Nhưng cũng phải chú ý kiểm soát thời gian.'],
            ['who' => '小红', 'cn' => '你说得对。科技方便了生活，但是不能沉迷。', 'vi' => 'Cậu nói đúng. Công nghệ tiện lợi cho cuộc sống, nhưng không thể sa đà.'],
            ['who' => '王小明', 'cn' => '你最近在网上买东西了吗？', 'vi' => 'Gần đây cậu có mua đồ trên mạng không?'],
            ['who' => '小红', 'cn' => '买了！快递昨天就到了，特别快。', 'vi' => 'Có mua! Hàng chuyển phát nhanh hôm qua đã đến, nhanh đặc biệt.'],
            ['who' => '王小明', 'cn' => '网上购物确实方便，但是也要理性消费。', 'vi' => 'Mua sắm trên mạng quả thật tiện lợi, nhưng cũng phải tiêu dùng lý trí.'],
        ],
        'grammar' => [
            ['point' => 'Cấu trúc 不仅...还可以... (không chỉ...mà còn có thể...)', 'explain' => 'Cấu trúc mở rộng của 不仅...还/也..., thêm 可以 để chỉ khả năng. Ví dụ: 手机不仅用来打电话，还可以上网 (Điện thoại không chỉ dùng để gọi điện, mà còn có thể lên mạng). A và B đều là động từ hoặc cụm động từ. Cấu trúc này thường dùng để liệt kê nhiều chức năng.', 'examples' => ['他不仅学习好，还可以参加比赛。Anh ấy không chỉ học giỏi mà còn có thể tham gia thi đấu.', '手机不仅方便，还可以帮助我们学习。Điện thoại không chỉ tiện lợi mà còn có thể giúp chúng ta học tập.', '这家店不仅东西多，还可以送货上门。Cửa hàng này không chỉ nhiều đồ mà còn có thể giao hàng tận nhà.']],
            ['point' => 'Cấu trúc 随时随地 (bất cứ lúc nào, bất cứ nơi đâu)', 'explain' => '随时随地 là thành ngữ cố định, nghĩa "bất cứ lúc nào cũng có thể, mọi lúc mọi nơi". 随时 (bất cứ lúc nào) + 随地 (bất cứ nơi đâu). Ví dụ: 随时随地和朋友聊天 (Nói chuyện với bạn bè mọi lúc mọi nơi). Cấu trúc thường đứng trước động từ, làm trạng ngữ.', 'examples' => ['现在可以随时随地上网。Bây giờ có thể lên mạng mọi lúc mọi nơi.', '手机让我随时随地听音乐。Điện thoại cho tôi nghe nhạc mọi lúc mọi nơi.', '我们可以随时随地和家人联系。Chúng ta có thể liên lạc với gia đình mọi lúc mọi nơi.']],
            ['point' => 'Cấu trúc 既...又... (vừa...vừa...)', 'explain' => 'Cấu trúc 既...又... diễn tả hai đặc điểm cùng tồn tại. Ví dụ: 既享受科技带来的便利，又不被科技控制 (Vừa tận hưởng tiện ích công nghệ mang lại, vừa không bị công nghệ kiểm soát). Cả hai vế thường là tính từ hoặc động từ. Khác với 又...又... thường dùng cùng loại từ.', 'examples' => ['他既聪明又努力。Anh ấy vừa thông minh vừa chăm chỉ.', '这件衣服既便宜又好看。Cái áo này vừa rẻ vừa đẹp.', '既方便又快捷。Vừa tiện lợi vừa nhanh chóng.']],
        ],
        'pronunciation' => ['focus' => 'ui/ei distinction', 'drill' => ['huí', 'hēi', 'guì', 'gěi', 'duì', 'děi', 'kuí', 'léi']],
        'vocab' => [
            ['w' => '科技', 'p' => 'kējì', 'm' => 'khoa học công nghệ', 'pos' => '名词', 'ex' => ['科技发展很快。Khoa học công nghệ phát triển rất nhanh.', '科技改变生活。Công nghệ thay đổi cuộc sống.']],
            ['w' => '发达', 'p' => 'fādá', 'm' => 'phát triển, tiên tiến', 'pos' => '形容词', 'ex' => ['现代社会很发达。Xã hội hiện đại rất phát triển.', '科技越来越发达。Khoa học công nghệ càng ngày càng phát triển.']],
            ['w' => '互联网', 'p' => 'hùliánwǎng', 'm' => 'internet', 'pos' => '名词', 'ex' => ['互联网很方便。Internet rất tiện lợi.', '互联网让世界变小了。Internet làm thế giới nhỏ lại.']],
            ['w' => '上网', 'p' => 'shàngwǎng', 'm' => 'lên mạng', 'pos' => '动词', 'ex' => ['我喜欢上网看新闻。Tôi thích lên mạng xem tin tức.', '每天上网一小时。Mỗi ngày lên mạng một tiếng.']],
            ['w' => '购物', 'p' => 'gòuwù', 'm' => 'mua sắm', 'pos' => '动词', 'ex' => ['网上购物很方便。Mua sắm trên mạng rất tiện.', '我喜欢去超市购物。Tôi thích đi siêu thị mua sắm.']],
            ['w' => '快递', 'p' => 'kuàidì', 'm' => 'chuyển phát nhanh', 'pos' => '名词', 'ex' => ['快递送到了门口。Chuyển phát nhanh giao tới cửa.', '我在等快递。Tôi đang đợi chuyển phát nhanh.']],
            ['w' => '方便', 'p' => 'fāngbiàn', 'm' => 'tiện lợi, thuận tiện', 'pos' => '形容词', 'ex' => ['手机很方便。Điện thoại rất tiện lợi.', '这里交通方便。Ở đây giao thông thuận tiện.']],
            ['w' => '工具', 'p' => 'gōngjù', 'm' => 'công cụ', 'pos' => '名词', 'ex' => ['科技是工具。Công nghệ là công cụ.', '学习工具很重要。Công cụ học tập rất quan trọng.']],
            ['w' => '沉迷', 'p' => 'chénmí', 'm' => 'sa đà, đắm chìm', 'pos' => '动词', 'ex' => ['不要沉迷游戏。Đừng sa đà vào game.', '沉迷网络不好。Đắm chìm vào mạng không tốt.']],
            ['w' => '忽略', 'p' => 'hūlüè', 'm' => 'bỏ qua, coi nhẹ', 'pos' => '动词', 'ex' => ['忽略了家人。Coi nhẹ gia đình.', '不要忽略健康。Đừng bỏ qua sức khỏe.']],
            ['w' => '屏幕', 'p' => 'píngmù', 'm' => 'màn hình', 'pos' => '名词', 'ex' => ['长时间看屏幕不好。Xem màn hình lâu không tốt.', '手机屏幕很大。Màn hình điện thoại rất lớn.']],
            ['w' => '合理', 'p' => 'hélǐ', 'm' => 'hợp lý', 'pos' => '形容词', 'ex' => ['合理使用时间。Sử dụng thời gian hợp lý.', '这很合理。Điều này rất hợp lý.']],
            ['w' => '控制', 'p' => 'kòngzhì', 'm' => 'kiểm soát', 'pos' => '动词', 'ex' => ['控制使用手机的时间。Kiểm soát thời gian dùng điện thoại.', '学会控制自己。Học cách kiểm soát bản thân.']],
            ['w' => '平衡', 'p' => 'pínghéng', 'm' => 'cân bằng', 'pos' => '动词,名词', 'ex' => ['平衡科技和生活。Cân bằng công nghệ và cuộc sống.', '保持平衡很重要。Giữ cân bằng rất quan trọng.']],
            ['w' => '联系', 'p' => 'liánxì', 'm' => 'liên lạc', 'pos' => '动词,名词', 'ex' => ['保持联系。Giữ liên lạc.', '我们经常联系。Chúng tôi thường xuyên liên lạc.']],
