    39 => [
        'title' => 'Bài 39: 环境与保护 - Môi trường và bảo vệ',
        'text' => '地球是我们共同的家园，保护环境是每一个人的责任。近年来，环境污染越来越严重，特别是空气污染和水污染。很多城市经常出现雾霾天气，影响人们的健康。河流和湖泊也被污染了，很多鱼类无法生存。面对这些问题，我们应该采取行动。首先，要减少使用塑料袋和一次性餐具，尽量使用环保袋和可重复使用的物品。其次，要节约用水和用电。比如，洗完手要关紧水龙头，离开房间要关灯。还有，我们应该多乘坐公共交通工具，少开私家车，减少汽车尾气的排放。垃圾分类也是非常重要的环保措施。把可回收的垃圾、厨余垃圾和其他垃圾分开投放，可以提高资源的利用率。我在学校和家里都积极参与环保活动。我和同学们一起去公园捡垃圾，向人们宣传环保知识。虽然一个人的力量很小，但是如果每个人都能为环保做出一点点贡献，我们的地球就会变得更美好。让我们从现在做起，从身边的小事做起，共同保护我们的家园。',
        'dialogues' => [
            ['who' => '老师', 'cn' => '同学们，你们知道什么是环境保护吗？', 'vi' => 'Các em, các em có biết bảo vệ môi trường là gì không?'],
            ['who' => '王小明', 'cn' => '我知道，保护环境就是要让我们的地球更干净、更健康。', 'vi' => 'Em biết, bảo vệ môi trường là làm cho trái đất của chúng ta sạch hơn, khỏe hơn.'],
            ['who' => '老师', 'cn' => '很好！那么我们可以做些什么来保护环境呢？', 'vi' => 'Rất tốt! Vậy chúng ta có thể làm gì để bảo vệ môi trường?'],
            ['who' => '小红', 'cn' => '我们可以少用塑料袋，多坐公交车。', 'vi' => 'Chúng ta có thể dùng ít túi nilon hơn, đi xe buýt nhiều hơn.'],
            ['who' => '王小明', 'cn' => '还要节约用水用电，进行垃圾分类。', 'vi' => 'Còn phải tiết kiệm nước điện, phân loại rác.'],
            ['who' => '老师', 'cn' => '说得很对。每个人都可以为环保做出贡献。', 'vi' => 'Nói rất đúng. Mỗi người đều có thể đóng góp cho bảo vệ môi trường.'],
            ['who' => '王小明', 'cn' => '老师，下周末我们组织去公园捡垃圾好不好？', 'vi' => 'Thưa thầy, cuối tuần sau chúng em tổ chức đi nhặt rác ở công viên được không ạ?'],
            ['who' => '老师', 'cn' => '非常好的主意！我们一起行动起来。', 'vi' => 'Ý kiến rất hay! Chúng ta cùng hành động nhé.'],
        ],
        'grammar' => [
            ['point' => 'Cấu trúc 越来越 + adj (càng ngày càng...)', 'explain' => 'Như đã học, 越来越 diễn tả sự thay đổi tăng dần. Trong bài: 环境污染越来越严重 (Ô nhiễm môi trường càng ngày càng nghiêm trọng). Có thể kết hợp với tính từ hoặc động từ tâm lý. Lưu ý: sau 越来越 không dùng 很/非常. Có thể dùng 越来越 + động từ: 越来越喜欢 (càng ngày càng thích).', 'examples' => ['天气越来越热。Thời tiết càng ngày càng nóng.', '环境越来越差。Môi trường càng ngày càng kém.', '越来越多的人关注环保。Càng ngày càng nhiều người quan tâm bảo vệ môi trường.']],
            ['point' => 'Cấu trúc 首先...其次...最后... (trước hết...sau đó...cuối cùng...)', 'explain' => 'Đây là cấu trúc liệt kê các bước hoặc ý theo thứ tự. 首先 (trước hết), 其次 (sau đó/thứ hai), 最后 (cuối cùng). Có thể dùng 第一...第二...第三... Dùng khi trình bày nhiều ý hoặc hướng dẫn các bước.', 'examples' => ['首先洗脸，其次刷牙，最后吃早餐。Trước hết rửa mặt, sau đó đánh răng, cuối cùng ăn sáng.', '首先节约用水，其次减少使用塑料袋，最后进行垃圾分类。Trước hết tiết kiệm nước, sau đó giảm dùng túi nilon, cuối cùng phân loại rác.']],
            ['point' => 'Lượng từ 一点儿 (một chút) + so sánh', 'explain' => '一点儿 có nghĩa "một chút", thường đi sau tính từ để chỉ mức độ nhẹ. Trong câu so sánh: nếu 前 + 比 + Vế sau + 一点儿 có nghĩa "hơn một chút". Nếu 一点儿 đứng trước tính từ: 做一点点贡献 (đóng góp một chút). Cấu trúc: 一点点 + danh từ.', 'examples' => ['做一点贡献。Đóng góp một chút.', '好一点儿。Tốt hơn một chút.', '多一点努力。Cố gắng thêm một chút.']],
        ],
        'pronunciation' => ['focus' => 'in/ing distinction', 'drill' => ['jīn', 'jīng', 'pín', 'píng', 'mín', 'míng', 'xīn', 'xīng']],
        'vocab' => [
            ['w' => '环境', 'p' => 'huánjìng', 'm' => 'môi trường', 'pos' => '名词', 'ex' => ['保护环境很重要。Bảo vệ môi trường rất quan trọng.', '环境污染很严重。Ô nhiễm môi trường rất nghiêm trọng.']],
            ['w' => '保护', 'p' => 'bǎohù', 'm' => 'bảo vệ', 'pos' => '动词', 'ex' => ['保护地球。Bảo vệ trái đất.', '保护环境人人有责。Bảo vệ môi trường ai cũng có trách nhiệm.']],
            ['w' => '污染', 'p' => 'wūrǎn', 'm' => 'ô nhiễm', 'pos' => '动词,名词', 'ex' => ['空气污染很严重。Ô nhiễm không khí rất nghiêm trọng.', '不要污染河流。Đừng làm ô nhiễm sông ngòi.']],
            ['w' => '雾霾', 'p' => 'wùmái', 'm' => 'sương mù dày đặc', 'pos' => '名词', 'ex' => ['今天有雾霾。Hôm nay có sương mù.', '雾霾影响健康。Sương mù ảnh hưởng sức khỏe.']],
            ['w' => '减少', 'p' => 'jiǎnshǎo', 'm' => 'giảm bớt', 'pos' => '动词', 'ex' => ['减少使用塑料袋。Giảm dùng túi nilon.', '减少污染从我做起。Giảm ô nhiễm từ tôi bắt đầu.']],
            ['w' => '节约', 'p' => 'jiéyuē', 'm' => 'tiết kiệm', 'pos' => '动词', 'ex' => ['节约用水。Tiết kiệm nước.', '节约用电很重要。Tiết kiệm điện rất quan trọng.']],
            ['w' => '垃圾', 'p' => 'lājī', 'm' => 'rác thải', 'pos' => '名词', 'ex' => ['垃圾分类。Phân loại rác.', '不要乱扔垃圾。Đừng vứt rác bừa bãi.']],
            ['w' => '分类', 'p' => 'fēnlèi', 'm' => 'phân loại', 'pos' => '动词', 'ex' => ['垃圾分类很重要。Phân loại rác rất quan trọng.', '把垃圾分开投放。Bỏ rác riêng biệt.']],
            ['w' => '回收', 'p' => 'huíshōu', 'm' => 'thu hồi, tái chế', 'pos' => '动词', 'ex' => ['可回收垃圾。Rác có thể tái chế.', '回收再利用。Tái chế và tái sử dụng.']],
            ['w' => '排放', 'p' => 'páifàng', 'm' => 'thải ra, xả thải', 'pos' => '动词', 'ex' => ['减少尾气排放。Giảm xả khí thải.', '工厂排放污水。Nhà máy xả nước thải.']],
            ['w' => '公共', 'p' => 'gōnggòng', 'm' => 'công cộng', 'pos' => '形容词', 'ex' => ['公共交通很方便。Giao thông công cộng rất tiện.', '公共场所禁止吸烟。Nơi công cộng cấm hút thuốc.']],
            ['w' => '交通', 'p' => 'jiāotōng', 'm' => 'giao thông', 'pos' => '名词', 'ex' => ['公共交通很方便。Giao thông công cộng rất tiện.', '交通越来越发达。Giao thông càng ngày càng phát triển.']],
            ['w' => '贡献', 'p' => 'gòngxiàn', 'm' => 'cống hiến, đóng góp', 'pos' => '动词,名词', 'ex' => ['做出一份贡献。Đóng góp một phần.', '为环保做贡献。Đóng góp cho bảo vệ môi trường.']],
            ['w' => '参与', 'p' => 'cānyù', 'm' => 'tham gia', 'pos' => '动词', 'ex' => ['积极参与环保活动。Tích cực tham gia hoạt động bảo vệ môi trường.', '欢迎大家参与。Chào mừng mọi người tham gia.']],
            ['w' => '力量', 'p' => 'lìliàng', 'm' => 'sức lực, sức mạnh', 'pos' => '名词', 'ex' => ['一个人的力量很小。Sức mạnh một người rất nhỏ.', '团结就是力量。Đoàn kết là sức mạnh.']],
        ],
        'exercises' => [
            'fill_blank' => [
                ['s' => '保____环境人人有责。', 'a' => '护'],
                ['s' => '环境污____越来越严重。', 'a' => '染'],
