                ['q' => '王小明和同学们组织了什么活动？', 'opts' => ['植树', '捡垃圾', '宣传环保', '打扫教室'], 'a' => 1],
                ['q' => '文中提到少开私家车是因为什么？', 'opts' => ['堵车', '停车难', '减少尾气排放', '油价高'], 'a' => 2],
            ],
            'translation' => [
