    40 => [
        'title' => 'Bài 40: 梦想与未来 - Ước mơ và tương lai',
        'text' => '每个人都有自己的梦想。有的人想当科学家，有的人想当医生，有的人想当老师。梦想是我们前进的动力。没有梦想的人生就像没有方向的船，只能在海上漂泊。我从小就有一个梦想，就是成为一名作家。我喜欢读书，也喜欢写作。每当我读到一本好书，就会被书中的故事深深吸引。我想写出动人的故事，让更多的人感受到文字的力量。为了实现这个梦想，我一直在努力。我每天坚持读书一个小时，学习作家的写作技巧。我还参加了学校的文学社，和同学们一起讨论作品，互相学习。老师告诉我，当作家不仅要会写，还要有丰富的生活经验。所以我也积极参加各种活动，去不同的地方旅行，认识不同的人。我相信只要坚持努力，总有一天我会实现自己的梦想。梦想不一定都能实现，但是在追求梦想的过程中，我们学会了很多东西，这也是很宝贵的财富。希望每个人都能坚持自己的梦想，勇敢地走向未来。',
        'dialogues' => [
            ['who' => '老师', 'cn' => '王小明，你长大后想做什么？', 'vi' => 'Vương Tiểu Minh, lớn lên em muốn làm gì?'],
            ['who' => '王小明', 'cn' => '我想当一名作家。', 'vi' => 'Em muốn làm một nhà văn.'],
            ['who' => '老师', 'cn' => '噢？为什么想当作家呢？', 'vi' => 'Ồ? Tại sao muốn làm nhà văn?'],
            ['who' => '王小明', 'cn' => '因为我喜欢读书和写作，想写出动人的故事。', 'vi' => 'Vì em thích đọc sách và viết lách, muốn viết ra những câu chuyện cảm động.'],
            ['who' => '老师', 'cn' => '这是个很好的梦想。你为了这个梦想做了什么准备？', 'vi' => 'Đó là một ước mơ rất tốt. Em đã chuẩn bị gì cho ước mơ này?'],
            ['who' => '王小明', 'cn' => '我每天读书，参加文学社，还去各地旅行。', 'vi' => 'Em đọc sách mỗi ngày, tham gia câu lạc bộ văn học, còn đi du lịch nhiều nơi.'],
            ['who' => '老师', 'cn' => '非常好！作家需要有丰富的生活经验。', 'vi' => 'Rất tốt! Nhà văn cần có kinh nghiệm cuộc sống phong phú.'],
            ['who' => '王小明', 'cn' => '老师，您小时候的梦想是什么？', 'vi' => 'Thưa thầy, ước mơ hồi nhỏ của thầy là gì?'],
            ['who' => '老师', 'cn' => '我小时候想当科学家，后来当了老师，但也觉得很幸福。', 'vi' => 'Hồi nhỏ thầy muốn làm nhà khoa học, sau này làm giáo viên, nhưng cũng thấy rất hạnh phúc.'],
        ],
        'grammar' => [
            ['point' => 'Cấu trúc 就像...一样 (giống như...)', 'explain' => '就像...一样 dùng để so sánh, nghĩa "giống như...". Cấu trúc: A + 就像 + B + 一样. Ví dụ: 没有梦想的人生就像没有方向的船 (Cuộc đời không có ước mơ giống như con thuyền không có hướng đi). 一样 có thể lược bỏ trong văn nói. Có thể thay 就像 bằng 好像 hoặc 仿佛.', 'examples' => ['时间就像流水一样。Thời gian giống như dòng nước chảy.', '他就像我的哥哥一样。Anh ấy giống như anh trai tôi vậy.', '人生就像一场旅行。Cuộc đời giống như một chuyến du lịch.']],
            ['point' => 'Cấu trúc 被 (bị / được)', 'explain' => '被 là giới từ chỉ thể bị động, nghĩa "bị/được". Cấu trúc: Chủ ngữ + 被 + tác nhân + động từ. Trong bài: 被书中的故事深深吸引 (Bị câu chuyện trong sách thu hút sâu sắc). Nếu không cần nêu tác nhân, có thể nói: 被 + động từ. 被 thường dùng cho việc không mong muốn, nhưng cũng có thể dùng cho việc tích cực (被吸引).', 'examples' => ['我被这本书吸引了。Tôi bị cuốn sách này thu hút.', '他被老师表扬了。Anh ấy được thầy khen.', '作业被完成了。Bài tập đã được hoàn thành.']],
            ['point' => 'Cấu trúc 只要...总有一天... (chỉ cần...một ngày nào đó...)', 'explain' => 'Đây là cấu trúc mở rộng của 只要...就... 只要 + điều kiện + 总有一天 + kết quả trong tương lai. 总有一天 nhấn mạnh vào một thời điểm không xác định trong tương lai nhưng chắc chắn kết quả sẽ xảy ra. Bài: 只要坚持努力，总有一天我会实现梦想 (Chỉ cần kiên trì cố gắng, một ngày nào đó tôi sẽ thực hiện được ước mơ).', 'examples' => ['只要不放弃，总有一天会成功。Chỉ cần không từ bỏ, một ngày nào đó sẽ thành công.', '只要努力，总有一天会实现目标。Chỉ cần cố gắng, một ngày nào đó sẽ đạt được mục tiêu.']],
        ],
