    41 => [
        'title' => 'Bài 41: 旅行与见闻 - Du lịch và kiến văn',
        'text' => '去年暑假，我和家人去云南旅行了一次。这是我第一次去云南，那里的风景让我终生难忘。我们先坐飞机到了昆明，昆明被称为"春城"，因为这里四季如春，气候非常舒适。我们在昆明游览了石林和滇池，石林的石头奇形怪状，非常壮观。然后我们去了大理古城，古城里有很多古老的建筑和特色小店。在大理，我们品尝了当地的美食，比如过桥米线和乳扇。我最喜欢的是丽江古城，那里的小桥流水、古朴的街道让人感觉仿佛回到了古代。我们还去了玉龙雪山，山上的雪景非常美丽，空气清新。这次旅行让我深刻体会到了中国的地大物博。每个地方都有自己独特的自然风光和人文特色。旅行不仅能让我们放松心情，还能增长见识，开阔眼界。我决定以后每年都要去一个不同的地方旅行，去发现更多美好的事物。旅行的意义不在于去了多少地方，而在于在旅途中收获了多少感动和回忆。我希望有一天能走遍中国的大好河山。',
        'dialogues' => [
            ['who' => '小红', 'cn' => '王小明，听说你去年暑假去云南了？', 'vi' => 'Vương Tiểu Minh, nghe nói cậu đi Vân Nam hè năm ngoái?'],
            ['who' => '王小明', 'cn' => '是的，我和家人一起去的，非常棒！', 'vi' => 'Ừ, tớ và gia đình đi, rất tuyệt!'],
            ['who' => '小红', 'cn' => '云南哪些地方最好玩？', 'vi' => 'Vân Nam những chỗ nào đẹp nhất?'],
            ['who' => '王小明', 'cn' => '昆明、大理、丽江都很有特色，特别是丽江古城。', 'vi' => 'Côn Minh, Đại Lý, Lệ Giang đều có nét đặc sắc, nhất là phố cổ Lệ Giang.'],
            ['who' => '小红', 'cn' => '丽江古城是什么样的？', 'vi' => 'Phố cổ Lệ Giang thế nào?'],
            ['who' => '王小明', 'cn' => '小桥流水，古色古香，像画一样美。', 'vi' => 'Cầu nhỏ nước chảy, cổ kính, đẹp như tranh vẽ.'],
            ['who' => '小红', 'cn' => '听起来太美了！我也想去。', 'vi' => 'Nghe thật đẹp! Tớ cũng muốn đi.'],
            ['who' => '王小明', 'cn' => '一定要去一次，不会让你失望的。', 'vi' => 'Nhất định phải đi một lần, sẽ không làm cậu thất vọng đâu.'],
            ['who' => '小红', 'cn' => '你们吃了什么当地美食吗？', 'vi' => 'Các cậu có ăn món ngon địa phương không?'],
            ['who' => '王小明', 'cn' => '吃了过桥米线，味道好极了！', 'vi' => 'Có ăn mì quá kiều, vị ngon tuyệt!'],
        ],
        'grammar' => [
            ['point' => 'Cấu trúc 被称为 / 叫做 (được gọi là)', 'explain' => 'Trong tiếng Trung, 被称为 (bị/được gọi là) hoặc 叫做 (gọi là) dùng để định danh. Cấu trúc: A + 被称为 + B. Bài: 昆明被称为"春城" (Côn Minh được gọi là "Xuân Thành"). 被称为 thường dùng trong phong cách trang trọng. 叫做 dùng trong văn nói hàng ngày.', 'examples' => ['北京被称为首都。Bắc Kinh được gọi là thủ đô.', '这叫做乐观。Cái này gọi là lạc quan.', '四川被称为天府之国。Tứ Xuyên được gọi là vùng đất trù phú.']],
            ['point' => 'Cấu trúc 不仅...还... (không chỉ...mà còn...)', 'explain' => 'Ôn tập cấu trúc. 不仅...还... liên kết hai ý bổ sung. Trong bài: 旅行不仅能放松心情，还能增长见识 (Du lịch không chỉ có thể thư giãn tâm trạng, mà còn có thể mở mang kiến thức). Có thể thay 还 bằng 而且, 并且. 不仅 có thể đặt trước chủ ngữ.', 'examples' => ['他不仅聪明，还努力。Anh ấy không chỉ thông minh mà còn chăm chỉ.', '云南不仅风景美，美食也多。Vân Nam không chỉ phong cảnh đẹp, đồ ăn ngon cũng nhiều.']],
            ['point' => 'Cấu trúc 不在于...而在于... (không nằm ở...mà nằm ở...)', 'explain' => 'Cấu trúc này dùng để nhấn mạnh sự khác biệt giữa hai điều. 不在于 + A + 而在于 + B. Ví dụ: 旅行的意义不在于去了多少地方，而在于在旅途中收获了多少感动和回忆 (Ý nghĩa của du lịch không nằm ở việc đã đi bao nhiêu nơi, mà nằm ở việc đã thu hoạch được bao nhiêu cảm động và kỷ niệm trong chuyến đi). Cấu trúc này thường dùng trong văn nghị luận.', 'examples' => ['成功不在于天赋，而在于努力。Thành công không nằm ở thiên phú mà nằm ở nỗ lực.', '幸福不在于拥有多少，而在于满足多少。Hạnh phúc không nằm ở có bao nhiêu mà nằm ở hài lòng bao nhiêu.']],
        ],
        'pronunciation' => ['focus' => 'ian/üan distinction', 'drill' => ['qián', 'quán', 'xiǎn', 'xuǎn', 'jiàn', 'juàn', 'lián', 'luán']],
        'vocab' => [
            ['w' => '旅行', 'p' => 'lǚxíng', 'm' => 'du lịch', 'pos' => '动词,名词', 'ex' => ['我喜欢旅行。Tôi thích du lịch.', '去云南旅行。Du lịch đến Vân Nam.']],
            ['w' => '风景', 'p' => 'fēngjǐng', 'm' => 'phong cảnh', 'pos' => '名词', 'ex' => ['风景很美。Phong cảnh rất đẹp.', '欣赏风景。Thưởng thức phong cảnh.']],
            ['w' => '终生', 'p' => 'zhōngshēng', 'm' => 'suốt đời', 'pos' => '名词', 'ex' => ['终生难忘。Suốt đời khó quên.', '终生受益。Ích lợi suốt đời.']],
            ['w' => '古城', 'p' => 'gǔchéng', 'm' => 'cổ trấn, thành cổ', 'pos' => '名词', 'ex' => ['大理古城。Cổ trấn Đại Lý.', '古城很有特色。Cổ trấn rất đặc sắc.']],
            ['w' => '特色', 'p' => 'tèsè', 'm' => 'nét đặc sắc', 'pos' => '名词', 'ex' => ['地方特色。Nét đặc sắc địa phương.', '很有特色。Rất có nét đặc sắc.']],
            ['w' => '当地', 'p' => 'dāngdì', 'm' => 'địa phương', 'pos' => '名词', 'ex' => ['当地美食。Món ngon địa phương.', '当地人很热情。Người địa phương rất nhiệt tình.']],
            ['w' => '美食', 'p' => 'měishí', 'm' => 'món ngon', 'pos' => '名词', 'ex' => ['品尝当地美食。Thưởng thức món ngon địa phương.', '中国美食很多。Món ngon Trung Quốc nhiều.']],
            ['w' => '仿佛', 'p' => 'fǎngfú', 'm' => 'như thể, dường như', 'pos' => '副词', 'ex' => ['仿佛回到了古代。Như thể trở về thời cổ đại.', '仿佛在梦里。Như thể trong mơ.']],
            ['w' => '体会', 'p' => 'tǐhuì', 'm' => 'thể hội, cảm nhận', 'pos' => '动词', 'ex' => ['深刻的体会。Cảm nhận sâu sắc.', '我体会到旅行的意义。Tôi cảm nhận được ý nghĩa của du lịch.']],
            ['w' => '地大物博', 'p' => 'dì dà wù bó', 'm' => 'đất rộng của nhiều', 'pos' => '成语', 'ex' => ['中国地大物博。Trung Quốc đất rộng của nhiều.', '地大物博的国家。Đất nước rộng lớn giàu tài nguyên.']],
