    42 => [
        'title' => 'Bài 42: 教育与学习 - Giáo dục và học tập',
        'text' => '教育对于一个人的成长非常重要。通过教育，我们不仅可以获得知识，还可以学会怎么做人。在中国，每个孩子都有接受九年义务教育的权利。学校是我们学习知识的地方，也是培养品格的地方。在课堂上，老师教我们语文、数学、英语等各门课程。除了课堂学习，课外活动也很重要。参加社团活动可以培养我们的兴趣爱好，锻炼我们的能力。我的语文老师曾经说过："学习是一辈子的事情，不要以为毕业了就不用学习了。"这句话让我深受启发。确实，走出学校以后，我们还需要不断学习新的知识和技能，才能适应社会的发展。现在科技日新月异，不学习就会被淘汰。终身学习的概念越来越被人们接受。很多人工作以后还在利用业余时间学习，有的考资格证书，有的学习外语，有的学习编程。学习不仅是为了找一份好工作，更是为了丰富自己，让自己变得更加优秀。我相信，只有不断学习的人，才能跟上时代的步伐。',
        'dialogues' => [
            ['who' => '王小明', 'cn' => '老师，您觉得学习最重要的是什么？', 'vi' => 'Thưa thầy, thầy thấy học tập quan trọng nhất là gì?'],
            ['who' => '老师', 'cn' => '最重要的是保持好奇心和求知欲。', 'vi' => 'Quan trọng nhất là giữ lòng hiếu kỳ và ham muốn tri thức.'],
            ['who' => '王小明', 'cn' => '怎么才能保持学习的动力呢？', 'vi' => 'Làm thế nào để giữ động lực học tập?'],
            ['who' => '老师', 'cn' => '找到学习的乐趣，把学习当作一种享受而不是负担。', 'vi' => 'Tìm niềm vui trong học tập, coi học tập là hưởng thụ chứ không phải gánh nặng.'],
            ['who' => '王小明', 'cn' => '课外活动对学习有帮助吗？', 'vi' => 'Hoạt động ngoại khóa có giúp ích cho học tập không?'],
            ['who' => '老师', 'cn' => '当然有。课外活动可以培养兴趣，锻炼能力。', 'vi' => 'Đương nhiên có. Hoạt động ngoại khóa có thể bồi dưỡng sở thích, rèn luyện năng lực.'],
            ['who' => '王小明', 'cn' => '毕业后还需要继续学习吗？', 'vi' => 'Sau khi tốt nghiệp còn cần tiếp tục học không?'],
            ['who' => '老师', 'cn' => '当然需要。终身学习是现在社会的趋势。', 'vi' => 'Đương nhiên cần. Học tập suốt đời là xu thế của xã hội hiện nay.'],
            ['who' => '王小明', 'cn' => '我明白了，谢谢老师！', 'vi' => 'Em hiểu rồi, cảm ơn thầy!'],
        ],
        'grammar' => [
            ['point' => 'Cấu trúc 通过...可以... (thông qua...có thể...)', 'explain' => '通过 + danh từ/động từ + 可以 + kết quả. Nghĩa "thông qua...có thể...". Ví dụ: 通过教育我们可以获得知识 (Thông qua giáo dục chúng ta có thể thu nhận tri thức). 通过 có thể đứng đầu câu hoặc giữa câu. 通过 khác với 经过: 通过 chỉ phương thức, 经过 chỉ quá trình.', 'examples' => ['通过学习，我们可以提高自己。Thông qua học tập, chúng ta có thể nâng cao bản thân.', '通过旅行，我开阔了眼界。Thông qua du lịch, tôi mở rộng tầm mắt.']],
            ['point' => 'Cấu trúc 把...当作... (coi...là...)', 'explain' => 'Cấu trúc 把 + A + 当作 + B, nghĩa "coi A là B". Ví dụ: 把学习当作一种享受 (Coi học tập là một sự hưởng thụ). 当作 có thể thay bằng 作为 hoặc 看成. 把 là giới từ đưa tân ngữ lên trước động từ.', 'examples' => ['把老师当作朋友。Coi thầy cô là bạn.', '把困难当作挑战。Coi khó khăn là thách thức.', '不要把学习当作负担。Đừng coi học tập là gánh nặng.']],
            ['point' => 'Cấu trúc 只有...才... (chỉ có...mới...)', 'explain' => 'Cấu trúc này diễn tả điều kiện duy nhất để có kết quả. 只有 + Điều kiện + 才 + Kết quả. Bài: 只有不断学习的人，才能跟上时代的步伐 (Chỉ có người không ngừng học tập, mới có thể theo kịp nhịp bước thời đại). 只有 nhấn mạnh điều kiện mang tính bắt buộc. Phân biệt với 只要...就...: 只要 chỉ cần, điều kiện đủ; 只有 chỉ duy nhất, điều kiện cần.', 'examples' => ['只有努力，才能成功。Chỉ có nỗ lực mới thành công.', '只有坚持学习，才能进步。Chỉ có kiên trì học tập, mới tiến bộ.']],
        ],
        'pronunciation' => ['focus' => 'en/eng distinction', 'drill' => ['mén', 'méng', 'fēn', 'fēng', 'gēn', 'gēng', 'zhēn', 'zhēng']],
        'vocab' => [
            ['w' => '教育', 'p' => 'jiàoyù', 'm' => 'giáo dục', 'pos' => '名词,动词', 'ex' => ['教育很重要。Giáo dục rất quan trọng.', '教育孩子。Giáo dục trẻ em.']],
            ['w' => '知识', 'p' => 'zhīshi', 'm' => 'tri thức', 'pos' => '名词', 'ex' => ['学习知识。Học tri thức.', '知识改变命运。Tri thức thay đổi vận mệnh.']],
            ['w' => '培养', 'p' => 'péiyǎng', 'm' => 'bồi dưỡng', 'pos' => '动词', 'ex' => ['培养兴趣。Bồi dưỡng sở thích.', '培养能力。Bồi dưỡng năng lực.']],
            ['w' => '品格', 'p' => 'pǐngé', 'm' => 'phẩm cách', 'pos' => '名词', 'ex' => ['培养品格。Bồi dưỡng phẩm cách.', '高尚的品格。Phẩm cách cao thượng.']],
            ['w' => '课程', 'p' => 'kèchéng', 'm' => 'khóa trình, môn học', 'pos' => '名词', 'ex' => ['各门课程。Các môn học.', '课程很有用。Khóa trình rất hữu ích.']],
            ['w' => '课外', 'p' => 'kèwài', 'm' => 'ngoại khóa', 'pos' => '名词', 'ex' => ['课外活动。Hoạt động ngoại khóa.', '课外阅读。Đọc sách ngoại khóa.']],
            ['w' => '社团', 'p' => 'shètuán', 'm' => 'câu lạc bộ, đoàn thể', 'pos' => '名词', 'ex' => ['参加社团。Tham gia câu lạc bộ.', '社团活动很丰富。Hoạt động câu lạc bộ rất phong phú.']],
            ['w' => '启发', 'p' => 'qǐfā', 'm' => 'gợi mở, khai sáng', 'pos' => '动词', 'ex' => ['深受启发。Được khai sáng sâu sắc.', '启发思考。Gợi mở suy nghĩ.']],
            ['w' => '适应', 'p' => 'shìyìng', 'm' => 'thích ứng', 'pos' => '动词', 'ex' => ['适应社会。Thích ứng xã hội.', '适应新环境。Thích ứng môi trường mới.']],
