    43 => [
        'title' => 'Bài 43: 社会与责任 - Xã hội và trách nhiệm',
        'text' => '作为社会的一员，我们每个人都有责任为社会发展做出贡献。责任感是一个人成熟的标志。从小父母就教育我要做一个有责任心的人。在学校要尊敬老师，团结同学；在家里要孝敬父母，帮助做家务；在社会上要遵守规则，关心他人。志愿者活动是培养责任感的好方式。上个月我参加了学校组织的敬老院志愿者活动。我们帮老人们打扫卫生、陪他们聊天、表演节目。一位老奶奶拉着我的手说："孩子们来了，我们就高兴了。"她的笑容让我感到非常温暖。通过这次活动，我深刻体会到帮助别人是一件很快乐的事情。社会就像一个大机器，我们每个人都是机器上的一个零件。如果每个零件都发挥好自己的作用，机器就能正常运转。相反，如果有些人没有责任感，就会影响整个社会的发展。所以我们要从小事做起，从自己做起，做一个有责任感的公民。只有每个人都承担起自己的责任，社会才会变得更加和谐美好。',
        'dialogues' => [
            ['who' => '妈妈', 'cn' => '小明，今天学校有什么活动吗？', 'vi' => 'Tiểu Minh, hôm nay trường có hoạt động gì không?'],
            ['who' => '王小明', 'cn' => '妈妈，我们这周末要去敬老院做志愿者。', 'vi' => 'Mẹ ơi, cuối tuần này chúng con đến viện dưỡng lão làm tình nguyện.'],
            ['who' => '妈妈', 'cn' => '很好啊！做志愿者很有意义。', 'vi' => 'Tốt quá! Làm tình nguyện rất có ý nghĩa.'],
            ['who' => '王小明', 'cn' => '我们帮老人们打扫卫生、聊天、表演节目。', 'vi' => 'Chúng con giúp các cụ dọn vệ sinh, trò chuyện, biểu diễn tiết mục.'],
            ['who' => '妈妈', 'cn' => '你觉得参加这样的活动有什么收获？', 'vi' => 'Con thấy tham gia hoạt động như thế có thu hoạch gì?'],
            ['who' => '王小明', 'cn' => '我觉得帮助别人很快乐，也学会了怎么关心老人。', 'vi' => 'Con thấy giúp đỡ người khác rất vui, cũng học được cách quan tâm người già.'],
            ['who' => '妈妈', 'cn' => '是啊，责任感就是在这样的活动中培养起来的。', 'vi' => 'Phải đấy, trách nhiệm chính là được bồi dưỡng từ những hoạt động như thế này.'],
            ['who' => '王小明', 'cn' => '妈妈，我以后要多参加这样的活动。', 'vi' => 'Mẹ ơi, sau này con sẽ tham gia nhiều hoạt động như thế hơn.'],
        ],
        'grammar' => [
            ['point' => 'Cấu trúc 作为... (với tư cách là... / là...)', 'explain' => '作为 + danh từ, nghĩa "với tư cách là / là một...". Đưa ra vị thế hoặc vai trò trước khi đưa ra nhận xét. Bài: 作为社会的一员 (Là một thành viên của xã hội). Cấu trúc thường đặt ở đầu câu, ngăn cách với mệnh đề chính bằng dấu phẩy.', 'examples' => ['作为学生，要好好学习。Là học sinh, phải học tập tốt.', '作为公民，要遵守法律。Là công dân, phải tuân thủ pháp luật.', '作为志愿者，要帮助他人。Là tình nguyện viên, phải giúp đỡ người khác.']],
            ['point' => 'Cấu trúc 如果...就... (nếu...thì...) - điều kiện giả định', 'explain' => '如果...就... diễn tả giả định. 如果 + giả định + 就 + kết quả. Bài: 如果没有责任感，就会影响社会 (Nếu không có trách nhiệm, sẽ ảnh hưởng xã hội). Cấu trúc này thường dùng trong lập luận. Có thể lược bỏ 如果 và thay bằng 要是. 就 phải đặt trước kết quả.', 'examples' => ['如果大家都不负责任，社会就会乱。Nếu mọi người đều vô trách nhiệm, xã hội sẽ loạn.', '如果每个人都努力，世界会更好。Nếu mỗi người đều cố gắng, thế giới sẽ tốt hơn.']],
            ['point' => 'Cấu trúc 只有...才... (chỉ có...mới...) - điều kiện duy nhất', 'explain' => 'Ôn tập: 只有 + điều kiện + 才 + kết quả. Trong bài: 只有每个人都承担起自己的责任，社会才会变得更加和谐美好 (Chỉ có mỗi người đều gánh vác trách nhiệm của mình, xã hội mới trở nên hài hòa tốt đẹp hơn). So với 只要...就...: 只要 chỉ cần (điều kiện đủ), 只有 chỉ có (điều kiện cần duy nhất).', 'examples' => ['只有团结，才能战胜困难。Chỉ có đoàn kết mới vượt qua khó khăn.', '只有付出，才有收获。Chỉ có cống hiến mới có thu hoạch.']],
        ],
        'pronunciation' => ['focus' => 'ou/uo distinction', 'drill' => ['dōu', 'duō', 'gòu', 'guò', 'kǒu', 'kuò', 'shōu', 'shuō']],
        'vocab' => [
            ['w' => '责任', 'p' => 'zérèn', 'm' => 'trách nhiệm', 'pos' => '名词', 'ex' => ['负责任。Chịu trách nhiệm.', '社会责任感。Trách nhiệm xã hội.']],
            ['w' => '贡献', 'p' => 'gòngxiàn', 'm' => 'cống hiến, đóng góp', 'pos' => '动词,名词', 'ex' => ['为社会做贡献。Đóng góp cho xã hội.', '无私奉献。Cống hiến vô tư.']],
            ['w' => '成熟', 'p' => 'chéngshú', 'm' => 'chín muồi, trưởng thành', 'pos' => '形容词', 'ex' => ['思想成熟。Tư tưởng trưởng thành.', '成熟的标志。Dấu hiệu trưởng thành.']],
            ['w' => '标志', 'p' => 'biāozhì', 'm' => 'dấu hiệu, tiêu chí', 'pos' => '名词', 'ex' => ['成熟的标志。Dấu hiệu trưởng thành.', '交通标志。Biển báo giao thông.']],
            ['w' => '尊敬', 'p' => 'zūnjìng', 'm' => 'tôn kính', 'pos' => '动词', 'ex' => ['尊敬老师。Tôn kính thầy cô.', '尊敬长辈。Tôn kính người lớn tuổi.']],
            ['w' => '孝敬', 'p' => 'xiàojìng', 'm' => 'hiếu kính', 'pos' => '动词', 'ex' => ['孝敬父母。Hiếu kính cha mẹ.', '孝敬老人。Hiếu kính người già.']],
            ['w' => '遵守', 'p' => 'zūnshǒu', 'm' => 'tuân thủ', 'pos' => '动词', 'ex' => ['遵守规则。Tuân thủ quy tắc.', '遵守法律。Tuân thủ pháp luật.']],
            ['w' => '志愿者', 'p' => 'zhìyuànzhě', 'm' => 'tình nguyện viên', 'pos' => '名词', 'ex' => ['做志愿者。Làm tình nguyện viên.', '志愿者活动。Hoạt động tình nguyện.']],
            ['w' => '敬老院', 'p' => 'jìnglǎoyuàn', 'm' => 'viện dưỡng lão', 'pos' => '名词', 'ex' => ['去敬老院。Đến viện dưỡng lão.', '敬老院的老人。Các cụ ở viện dưỡng lão.']],
            ['w' => '打扫', 'p' => 'dǎsǎo', 'm' => 'dọn dẹp', 'pos' => '动词', 'ex' => ['打扫卫生。Dọn dẹp vệ sinh.', '打扫房间。Dọn dẹp phòng.']],
            ['w' => '表演', 'p' => 'biǎoyǎn', 'm' => 'biểu diễn', 'pos' => '动词', 'ex' => ['表演节目。Biểu diễn tiết mục.', '表演很精彩。Biểu diễn rất xuất sắc.']],
            ['w' => '温暖', 'p' => 'wēnnuǎn', 'm' => 'ấm áp', 'pos' => '形容词,名词', 'ex' => ['感到温暖。Cảm thấy ấm áp.', '温暖的阳光。Ánh nắng ấm áp.']],
            ['w' => '零件', 'p' => 'língjiàn', 'm' => 'linh kiện, bộ phận', 'pos' => '名词', 'ex' => ['机器零件。Linh kiện máy móc.', '每个零件都很重要。Mỗi bộ phận đều quan trọng.']],
            ['w' => '运转', 'p' => 'yùnzhuǎn', 'm' => 'vận hành', 'pos' => '动词', 'ex' => ['正常运转。Vận hành bình thường.', '机器在运转。Máy móc đang vận hành.']],
            ['w' => '和谐', 'p' => 'héxié', 'm' => 'hài hòa', 'pos' => '形容词', 'ex' => ['和谐社会。Xã hội hài hòa.', '相处和谐。Cư xử hài hòa.']],
        ],
        'exercises' => [
            'fill_blank' => [
