            'multiple_choice' => [
                ['q' => '责任感是一个人的什么标志？', 'opts' => ['年龄', '成熟', '学历', '财富'], 'a' => 1],
                ['q' => '王小明参加了什么志愿者活动？', 'opts' => ['植树', '敬老院', '支教', '环保'], 'a' => 1],
