    44 => [
        'title' => 'Bài 44: 文学与艺术 - Văn học và nghệ thuật',
        'text' => '文学和艺术是人类精神生活的重要组成部分。它们不仅能丰富我们的内心世界，还能陶冶情操。中国有着悠久的文学传统，从古代的唐诗宋词到现代的小说散文，每个时代都有杰出的作品。我最喜欢的文学作品是《红楼梦》。这本书描写了一个大家族的兴衰，人物形象生动，情节引人入胜。每读一遍都会有新的理解。除了文学作品，我还喜欢欣赏国画和书法。中国画讲究意境，画家通过笔墨表达自己的情感和思想。书法也是一种独特的艺术，不同的字体有不同的风格，有的刚劲有力，有的柔美流畅。音乐和舞蹈同样重要。中国传统音乐使用古筝、二胡、笛子等乐器，听起来悠扬动听。舞蹈则通过身体语言表达情感。艺术来源于生活又高于生活。通过欣赏艺术作品，我们可以了解不同时代人们的思想和情感。艺术让我们的生活变得更加丰富多彩。我希望将来有机会系统地学习一门艺术，比如书法或者国画，让自己的生活更有品味。',
        'dialogues' => [
            ['who' => '小红', 'cn' => '王小明，你最近在读什么书？', 'vi' => 'Vương Tiểu Minh, gần đây cậu đang đọc sách gì?'],
            ['who' => '王小明', 'cn' => '我在看《红楼梦》，真的很好看。', 'vi' => 'Tớ đang xem "Hồng Lâu Mộng", thực sự rất hay.'],
            ['who' => '小红', 'cn' => '《红楼梦》是中国四大名著之一吧？', 'vi' => '"Hồng Lâu Mộng" là một trong tứ đại danh tác của Trung Quốc phải không?'],
            ['who' => '王小明', 'cn' => '是的，它描写了一个大家族的兴衰。', 'vi' => 'Phải, nó miêu tả sự hưng suy của một đại gia tộc.'],
            ['who' => '小红', 'cn' => '除了看书，你还喜欢什么艺术？', 'vi' => 'Ngoài đọc sách, cậu còn thích nghệ thuật gì?'],
            ['who' => '王小明', 'cn' => '我喜欢书法，觉得写毛笔字很有意思。', 'vi' => 'Tớ thích thư pháp, thấy viết chữ bút lông rất thú vị.'],
            ['who' => '小红', 'cn' => '我也想学书法，但是觉得很难。', 'vi' => 'Tớ cũng muốn học thư pháp, nhưng thấy rất khó.'],
            ['who' => '王小明', 'cn' => '刚开始确实难，但是坚持练习就会进步。', 'vi' => 'Ban đầu quả thật khó, nhưng kiên trì luyện tập sẽ tiến bộ.'],
            ['who' => '小红', 'cn' => '你说得对，那我这周末就开始练！', 'vi' => 'Cậu nói đúng, vậy cuối tuần này tớ bắt đầu luyện!'],
        ],
        'grammar' => [
            ['point' => 'Cấu trúc 除了...还... (ngoài...còn...) - bổ sung', 'explain' => '除了 + A + 还 + B, ý nói A và B đều có. Trong bài: 除了文学作品，我还喜欢欣赏国画和书法 (Ngoài tác phẩm văn học, tôi còn thích thưởng thức quốc họa và thư pháp). 除了...还... và 除了...也... đều bổ sung, nhưng 还 mang ý mạnh hơn. 除了...以外 là phiên bản trang trọng hơn.', 'examples' => ['除了书法，他还喜欢国画。Ngoài thư pháp, anh ấy còn thích quốc họa.', '除了阅读，我也喜欢写作。Ngoài đọc sách, tôi cũng thích viết lách.']],
            ['point' => 'Cấu trúc 通过...可以... (thông qua...có thể...)', 'explain' => '通过 + phương thức + 可以 + kết quả. Bài: 通过欣赏艺术作品，我们可以了解不同时代人们的思想和情感 (Thông qua thưởng thức tác phẩm nghệ thuật, chúng ta có thể hiểu tư tưởng và tình cảm của con người ở các thời đại khác nhau). 通过 thường đứng đầu câu, sau đó là chủ ngữ.', 'examples' => ['通过读书，我们可以增长知识。Thông qua đọc sách, chúng ta có thể tăng tri thức.', '通过旅行，我们可以开阔眼界。Thông qua du lịch, chúng ta có thể mở rộng tầm mắt.']],
            ['point' => 'Cấu trúc 从...到... (từ...đến...) - phạm vi', 'explain' => '从 + A + 到 + B, chỉ phạm vi từ A đến B. Bài: 从古代的唐诗宋词到现代的小说散文 (Từ thơ Đường từ Tống cổ đại đến tiểu thuyết tản văn hiện đại). Có thể chỉ thời gian, không gian hoặc phạm vi. 从...到... + 都 được dùng để nhấn mạnh.', 'examples' => ['从古至今，文学都在发展。Từ xưa đến nay, văn học vẫn đang phát triển.', '从老师到学生，都很喜欢这本书。Từ thầy đến trò, đều thích cuốn sách này.']],
        ],
        'pronunciation' => ['focus' => 'ao/ou distinction', 'drill' => ['hǎo', 'hǒu', 'dào', 'dòu', 'lǎo', 'lǒu', 'zhào', 'zhòu']],
        'vocab' => [
