    45 => [
        'title' => 'Bài 45: 经济与发展 - Kinh tế và phát triển',
        'text' => '改革开放以来，中国的经济发展非常迅速。几十年前，人们的生活水平还很低，很多家庭买不起电视和冰箱。现在，中国已经成为世界第二大经济体，人民的生活水平得到了极大的提高。城市化进程加快，高楼大厦拔地而起。高铁、移动支付、网购被称为中国的新四大发明，改变着人们的生活方式。经济高速发展的同时，也面临着一些挑战。贫富差距、环境污染、资源短缺等问题需要我们重视。我认为经济发展不能只追求速度，更要注重质量。可持续发展是未来的方向。我们要发展绿色经济，使用清洁能源，保护生态环境。同时还要促进区域协调发展，让更多的人分享经济发展的成果。作为一个学生，我现在要努力学习经济知识，将来为国家的经济发展贡献自己的力量。只有经济发展了，国家才能富强，人民才能过上更好的生活。经济繁荣是国家繁荣的基础，也是人民幸福的保障。',
        'dialogues' => [
            ['who' => '爸爸', 'cn' => '小明，你知道中国经济发展有多快吗？', 'vi' => 'Tiểu Minh, con biết kinh tế Trung Quốc phát triển nhanh thế nào không?'],
            ['who' => '王小明', 'cn' => '我知道，中国现在是世界第二大经济体。', 'vi' => 'Con biết, Trung Quốc hiện là nền kinh tế lớn thứ hai thế giới.'],
            ['who' => '爸爸', 'cn' => '是啊，爸爸小时候家里很穷，现在的生活条件好多了。', 'vi' => 'Phải đấy, hồi nhỏ bố nhà nghèo, điều kiện sống bây giờ tốt hơn nhiều.'],
            ['who' => '王小明', 'cn' => '高铁和移动支付真的很方便。', 'vi' => 'Tàu cao tốc và thanh toán di động thực sự rất tiện lợi.'],
            ['who' => '爸爸', 'cn' => '经济发展也给环境带来了压力，要注意保护环境。', 'vi' => 'Phát triển kinh tế cũng tạo áp lực cho môi trường, phải chú ý bảo vệ môi trường.'],
            ['who' => '王小明', 'cn' => '可持续发展是不是就是既要经济效益又要环保？', 'vi' => 'Phát triển bền vững có phải là vừa có hiệu quả kinh tế vừa bảo vệ môi trường không?'],
            ['who' => '爸爸', 'cn' => '对，不能只顾眼前利益，要考虑长远发展。', 'vi' => 'Đúng, không thể chỉ lo lợi ích trước mắt, phải xét phát triển lâu dài.'],
            ['who' => '王小明', 'cn' => '我明白了，发展也要讲平衡。', 'vi' => 'Con hiểu rồi, phát triển cũng phải nói đến cân bằng.'],
        ],
        'grammar' => [
            ['point' => 'Cấu trúc 从...以来 (từ khi...đến nay)', 'explain' => '从 + mốc thời gian + 以来, nghĩa "từ khi... đến nay". Bài: 改革开放以来，中国的经济发展非常迅速 (Từ khi cải cách mở cửa đến nay, kinh tế Trung Quốc phát triển rất nhanh). 以来 chỉ một khoảng thời gian từ quá khứ đến hiện tại. Có thể dùng 以来 riêng lẻ, ví dụ 自古以来 (từ xưa đến nay).', 'examples' => ['开学以来，我学习很努力。Từ khi khai giảng đến nay, tôi học tập rất chăm chỉ.', '自古以来，中国人就重视教育。Từ xưa đến nay, người Trung Quốc coi trọng giáo dục.']],
            ['point' => 'Cấu trúc 不能只...更要... (không thể chỉ...mà càng phải...)', 'explain' => 'Cấu trúc này diễn tả "không thể chỉ làm A, mà càng phải làm B". A là điều cơ bản, B là quan trọng hơn. Bài: 经济发展不能只追求速度，更要注重质量 (Phát triển kinh tế không thể chỉ theo đuổi tốc độ, mà càng phải chú trọng chất lượng). 更 nhấn mạnh mức độ cao hơn. Có thể dùng 还要 thay thế.', 'examples' => ['学习不能只记答案，更要理解方法。Học không thể chỉ nhớ đáp án, càng phải hiểu phương pháp.', '生活不能只追求物质，更要追求精神。Sống không thể chỉ theo đuổi vật chất, càng phải theo đuổi tinh thần.']],
            ['point' => 'Cấu trúc 只有...才... (chỉ có...mới...)', 'explain' => 'Nhấn mạnh điều kiện tiên quyết. 只有 + điều kiện + 才 + kết quả. Bài: 只有经济发展了，国家才能富强 (Chỉ có kinh tế phát triển, đất nước mới giàu mạnh). Đây là cấu trúc điều kiện mang tính bắt buộc. Kết hợp với 了 để chỉ điều kiện đã hoàn thành.', 'examples' => ['只有努力学习，才能考上大学。Chỉ có học tập chăm chỉ mới thi đỗ đại học.', '只有保护环境，才能持续发展。Chỉ có bảo vệ môi trường mới phát triển bền vững.']],
        ],
        'pronunciation' => ['focus' => 'ian/iang distinction', 'drill' => ['nián', 'niáng', 'liǎn', 'liǎng', 'jiān', 'jiāng', 'qián', 'qiáng']],
