    46 => [
        'title' => 'Bài 46: 科学与社会 - Khoa học và xã hội',
        'text' => '科学技术是第一生产力。在当今社会，科学发展对人类的进步起着至关重要的作用。从蒸汽机的发明到互联网的出现，每一次科技革命都极大地改变了人类的生活方式。现代科技已经渗透到我们生活的方方面面。人工智能、大数据、云计算、物联网等新技术正在改变着各行各业。在医疗领域，AI辅助诊断可以帮助医生更准确地发现疾病。在交通领域，无人驾驶技术正在快速发展。在教育领域，在线教育让优质教育资源可以共享。然而，科技发展也带来了一些伦理和安全隐患。比如，基因编辑技术的应用需要谨慎对待，数据隐私的保护也越来越受到关注。我们既要享受科技带来的便利，也要警惕科技可能带来的风险。作为一名学生，我要努力学习科学知识，培养科学素养。同时也要有批判性思维，不被信息迷惑。科学是一把双刃剑，正确地使用科技才能造福人类。',
        'dialogues' => [
            ['who' => '王小明', 'cn' => '老师，您觉得人工智能会让很多人失业吗？', 'vi' => 'Thưa thầy, thầy có nghĩ trí tuệ nhân tạo sẽ làm nhiều người thất nghiệp không?'],
            ['who' => '老师', 'cn' => '人工智能确实会替代一些工作，但也会创造新的工作。', 'vi' => 'Trí tuệ nhân tạo quả thật sẽ thay thế một số công việc, nhưng cũng sẽ tạo ra công việc mới.'],
            ['who' => '王小明', 'cn' => '那我们应该怎么面对科技的发展？', 'vi' => 'Vậy chúng ta nên đối mặt với phát triển khoa học thế nào?'],
            ['who' => '老师', 'cn' => '要不断学习新知识，跟上时代的步伐。', 'vi' => 'Phải không ngừng học tri thức mới, theo kịp nhịp bước thời đại.'],
            ['who' => '王小明', 'cn' => '科技发展会不会带来安全问题？', 'vi' => 'Phát triển khoa học có mang lại vấn đề an toàn không?'],
            ['who' => '老师', 'cn' => '会的，比如数据隐私保护就是一个大问题。', 'vi' => 'Có, ví dụ bảo vệ quyền riêng tư dữ liệu là một vấn đề lớn.'],
            ['who' => '王小明', 'cn' => '我们应该怎样正确使用科技？', 'vi' => 'Chúng ta nên sử dụng khoa học đúng đắn thế nào?'],
            ['who' => '老师', 'cn' => '要发挥科技的优势，同时控制风险。', 'vi' => 'Phải phát huy ưu thế của khoa học, đồng thời kiểm soát rủi ro.'],
        ],
        'grammar' => [
            ['point' => 'Cấu trúc 从...到... (từ...đến...)', 'explain' => '从...到... liệt kê một phạm vi. Bài: 从蒸汽机的发明到互联网的出现 (Từ phát minh máy hơi nước đến sự xuất hiện của internet). 从...到... có thể chỉ thời gian, không gian, hoặc sự chuyển biến. Có thể kết hợp 都 để nhấn mạnh: 从...到...都.', 'examples' => ['从早上到晚上都在学习。Từ sáng đến tối đều học.', '从老师到学生都关注科技。Từ thầy đến trò đều quan tâm khoa học công nghệ.']],
            ['point' => 'Cấu trúc 既...也... (vừa...lại vừa...)', 'explain' => 'Cấu trúc song song, cả hai vế đều đúng. Bài: 既要享受科技带来的便利，也要警惕科技可能带来的风险 (Vừa phải tận hưởng tiện ích khoa học mang lại, lại vừa phải cảnh giác rủi ro khoa học có thể mang lại). 既...又... cũng tương tự. 既...也... và 既...又... có thể thay thế cho nhau.', 'examples' => ['既要努力，也要方法。Vừa phải cố gắng, lại vừa phải có phương pháp.', '既要发展经济，也要保护环境。Vừa phải phát triển kinh tế, lại vừa phải bảo vệ môi trường.']],
            ['point' => 'Cấu trúc 只有...才... (chỉ có...mới...)', 'explain' => 'Điều kiện tiên quyết. Bài: 正确地使用科技才能造福人类 (Sử dụng khoa học đúng đắn mới có thể mang lợi cho nhân loại). Đây là cách dùng 只有...才... rút gọn: 只有 + điều kiện + 才 + kết quả.', 'examples' => ['只有努力学习，才能有好成绩。Chỉ có học chăm mới có kết quả tốt.', '只有不断创新，才能保持领先。Chỉ có không ngừng sáng tạo mới giữ vị trí dẫn đầu.']],
        ],
        'pronunciation' => ['focus' => 'uan/üan distinction', 'drill' => ['duàn', 'duàn', 'luàn', 'luàn', 'suān', 'xuān', 'zhuàn', 'zhuǎn']],
        'vocab' => [
