            ['w' => '生产', 'p' => 'shēngchǎn', 'm' => 'sản xuất', 'pos' => '动词', 'ex' => ['生产力。Sức sản xuất.', '生产产品。Sản xuất sản phẩm.']],
            ['w' => '人类', 'p' => 'rénlèi', 'm' => 'nhân loại', 'pos' => '名词', 'ex' => ['人类的进步。Sự tiến bộ của nhân loại.', '造福人类。Mang lợi cho nhân loại.']],
            ['w' => '革命', 'p' => 'gémìng', 'm' => 'cách mạng', 'pos' => '名词', 'ex' => ['科技革命。Cách mạng khoa học kỹ thuật.', '工业革命。Cách mạng công nghiệp.']],
            ['w' => '人工智能', 'p' => 'réngōng zhìnéng', 'm' => 'trí tuệ nhân tạo', 'pos' => '名词', 'ex' => ['人工智能发展很快。Trí tuệ nhân tạo phát triển rất nhanh.', 'AI是人工智能的缩写。AI là viết tắt của trí tuệ nhân tạo.']],
            ['w' => '数据', 'p' => 'shùjù', 'm' => 'dữ liệu', 'pos' => '名词', 'ex' => ['大数据。Dữ liệu lớn.', '数据分析。Phân tích dữ liệu.']],
            ['w' => '医疗', 'p' => 'yīliáo', 'm' => 'y tế', 'pos' => '名词', 'ex' => ['医疗领域。Lĩnh vực y tế.', '医疗技术。Kỹ thuật y tế.']],
            ['w' => '辅助', 'p' => 'fǔzhù', 'm' => 'hỗ trợ, phụ trợ', 'pos' => '动词', 'ex' => ['AI辅助诊断。Chẩn đoán hỗ trợ AI.', '辅助工具。Công cụ hỗ trợ.']],
            ['w' => '诊断', 'p' => 'zhěnduàn', 'm' => 'chẩn đoán', 'pos' => '动词,名词', 'ex' => ['疾病诊断。Chẩn đoán bệnh.', '医生正在诊断。Bác sĩ đang chẩn đoán.']],
            ['w' => '无人驾驶', 'p' => 'wúrén jiàshǐ', 'm' => 'tự lái, không người lái', 'pos' => '名词', 'ex' => ['无人驾驶技术。Kỹ thuật tự lái.', '无人驾驶汽车。Xe không người lái.']],
