    47 => [
        'title' => 'Bài 47: 历史与传统 - Lịch sử và truyền thống',
        'text' => '历史是一面镜子，让我们了解过去，也让我们更好地理解现在。中国是一个有着五千年文明历史的古国，在这漫长的历史长河中，产生了许多伟大的思想家、科学家、文学家和艺术家。孔子是中国古代最著名的思想家，他的思想影响了中国两千多年。孔子提倡"仁"和"礼"，教导人们要善良、有礼貌、尊重长辈。除了孔子，还有老子、孟子、庄子等哲学家，他们各自创立了不同的学派，形成了"百家争鸣"的局面。历史上还有四大发明：造纸术、印刷术、火药和指南针。这些发明不仅推动了中国的发展，也影响了全世界。读历史让我们明白，每一个时代都有它的特点和价值。从古代的鼎盛到近代的衰落，再到今天的复兴，中国的历史告诉我们要珍惜现在的和平与发展。历史也是最好的老师，它教会我们总结经验教训，避免走弯路。我们应该以史为鉴，开创更美好的未来。',
        'dialogues' => [
            ['who' => '王小明', 'cn' => '老师，为什么我们要学习历史？', 'vi' => 'Thưa thầy, tại sao chúng ta phải học lịch sử?'],
            ['who' => '老师', 'cn' => '学习历史可以让我们了解过去，明白现在。', 'vi' => 'Học lịch sử có thể giúp chúng ta hiểu quá khứ, rõ hiện tại.'],
            ['who' => '王小明', 'cn' => '孔子和老子哪个更早？', 'vi' => 'Khổng Tử và Lão Tử ai sớm hơn?'],
            ['who' => '老师', 'cn' => '孔子和老子差不多是同时代的人，都是春秋时期的思想家。', 'vi' => 'Khổng Tử và Lão Tử gần như cùng thời đại, đều là nhà tư tưởng thời Xuân Thu.'],
            ['who' => '王小明', 'cn' => '四大发明是什么？', 'vi' => 'Tứ đại phát minh là gì?'],
            ['who' => '老师', 'cn' => '造纸术、印刷术、火药和指南针。', 'vi' => 'Kỹ thuật làm giấy, kỹ thuật in, thuốc súng và la bàn.'],
