        'grammar' => [
            ['point' => 'Cấu trúc 不仅...也... (không chỉ...cũng...)', 'explain' => 'Cấu trúc bổ sung. 不仅 + A + 也 + B. Bài: 这些发明不仅推动了中国的发展，也影响了全世界 (Những phát minh này không chỉ thúc đẩy sự phát triển của Trung Quốc, cũng ảnh hưởng đến toàn thế giới). 不仅 có thể thay bằng 不但, 也 có thể thay bằng 还 hoặc 而且.', 'examples' => ['他不仅是我的老师，也是我的朋友。Anh ấy không chỉ là thầy tôi, cũng là bạn tôi.', '长城不仅是中国遗产，也是世界遗产。Vạn Lý Trường Thành không chỉ là di sản Trung Quốc, cũng là di sản thế giới.']],
            ['point' => 'Cấu trúc 以...为... (lấy...làm...)', 'explain' => '以...为... là cấu trúc trang trọng, nghĩa "lấy A làm B" hoặc "coi A là B". Bài: 以史为鉴 (Lấy lịch sử làm gương). Cấu trúc: 以 + A + 为 + B. Thường dùng trong thành ngữ: 以和为贵 (lấy hòa làm quý), 以人为本 (lấy con người làm gốc).', 'examples' => ['以史为鉴，可以知兴替。Lấy sử làm gương, có thể biết hưng thịnh suy tàn.', '我们应该以健康为重。Chúng ta nên lấy sức khỏe làm trọng.']],
