    48 => [
        'title' => 'Bài 48: 心理与成长 - Tâm lý và trưởng thành',
        'text' => '成长是一个漫长的过程，在这个过程中我们不仅身体在长大，心理也在不断成熟。年轻人常常会遇到各种各样的困惑和压力。学习的压力、人际关系的困扰、对未来的迷茫，这些都是成长中必须面对的课题。记得刚上高中的时候，我因为成绩下降而感到非常焦虑。那时候我总是担心自己考不好，晚上睡不好觉。后来在老师的帮助下，我学会了调整心态。老师告诉我，人的一生不可能一帆风顺，遇到困难是很正常的事情。关键是要以积极的态度面对困难，把挫折当作成长的机会。从那以后，我开始改变自己的思维方式。不再过分关注结果，而是享受努力的过程。我还学会了时间管理，合理安排学习和休息。运动也是缓解压力的好方法。每天跑跑步、打打球，心情就会好很多。现在我已经能够很好地管理自己的情绪了。成长不一定是快乐的，但经历过的每一次困难和挫折，都会让我们变得更加坚强。我相信，只要保持积极乐观的心态，就没有过不去的坎。',
        'dialogues' => [
            ['who' => '王小明', 'cn' => '老师，我最近感觉很焦虑，怎么办？', 'vi' => 'Thưa thầy, gần đây em cảm thấy lo lắng, phải làm sao?'],
            ['who' => '老师', 'cn' => '遇到什么事情了吗？可以跟老师说说。', 'vi' => 'Gặp chuyện gì à? Có thể nói với thầy.'],
            ['who' => '王小明', 'cn' => '马上要考试了，我怕考不好。', 'vi' => 'Sắp thi rồi, em sợ thi không tốt.'],
            ['who' => '老师', 'cn' => '考试只是检验学习的一种方式，不用太担心。', 'vi' => 'Thi chỉ là một cách kiểm tra học tập, không cần quá lo lắng.'],
            ['who' => '王小明', 'cn' => '但是我每天晚上都睡不好。', 'vi' => 'Nhưng tối nào em cũng ngủ không ngon.'],
            ['who' => '老师', 'cn' => '试试睡前听一些轻松的音乐，白天多运动。', 'vi' => 'Thử trước khi ngủ nghe nhạc nhẹ nhàng, ban ngày vận động nhiều.'],
            ['who' => '王小明', 'cn' => '好的，我试试。那如果考不好怎么办？', 'vi' => 'Vâng, em thử. Thế nếu thi không tốt thì sao?'],
            ['who' => '老师', 'cn' => '一次考试不能决定你的一生，重要的是学到什么。', 'vi' => 'Một kỳ thi không quyết định cả đời con, quan trọng là học được gì.'],
            ['who' => '王小明', 'cn' => '谢谢老师，我明白了。', 'vi' => 'Cảm ơn thầy, em hiểu rồi.'],
        ],
        'grammar' => [
            ['point' => 'Cấu trúc 常常 / 往往 (thường)', 'explain' => '常常 và 往往 đều có nghĩa "thường". 常常 chỉ tần suất cao, 往往 chỉ quy luật thông thường. Bài: 年轻人常常会遇到各种各样的困惑 và 每次困难都会让我们变得更加坚强. 常常 có thể dùng trong quá khứ và hiện tại, 往往 thường dùng cho quy luật. Phủ định: 不常.', 'examples' => ['他常常去图书馆。Anh ấy thường đến thư viện.', '考试前往往会有压力。Trước thi thường có áp lực.']],
            ['point' => 'Cấu trúc 把...当作... (coi...là...)', 'explain' => 'Cấu trúc 把 + A + 当作 + B. Bài: 把挫折当作成长的机会 (Coi khó khăn là cơ hội trưởng thành). Có thể thay 当作 bằng 作为. 把 là giới từ đặc biệt, đưa tân ngữ lên trước động từ.', 'examples' => ['把困难当作挑战。Coi khó khăn là thách thức.', '把失败当作经验。Coi thất bại là kinh nghiệm.']],
            ['point' => 'Cấu trúc 只要...就... (chỉ cần...là...)', 'explain' => 'Cấu trúc điều kiện đủ. 只要 + điều kiện + 就 + kết quả. Bài: 只要保持积极乐观的心态，就没有过不去的坎 (Chỉ cần giữ thái độ tích cực lạc quan, thì không có khó khăn nào không vượt qua). 没有...不... là phủ định kép, ý khẳng định mạnh mẽ.', 'examples' => ['只要努力，就会进步。Chỉ cần cố gắng, là sẽ tiến bộ.', '只要坚持，就没有克服不了的困难。Chỉ cần kiên trì, không có khó khăn nào không vượt qua.']],
        ],
        'pronunciation' => ['focus' => 'ie/üe distinction', 'drill' => ['jiē', 'juē', 'xiē', 'xuē', 'liè', 'lüè', 'qiè', 'què']],
        'vocab' => [
            ['w' => '成长', 'p' => 'chéngzhǎng', 'm' => 'trưởng thành', 'pos' => '动词', 'ex' => ['健康成长。Trưởng thành khỏe mạnh.', '成长的过程。Quá trình trưởng thành.']],
            ['w' => '心理', 'p' => 'xīnlǐ', 'm' => 'tâm lý', 'pos' => '名词', 'ex' => ['心理健康。Tâm lý khỏe mạnh.', '心理问题。Vấn đề tâm lý.']],
            ['w' => '困惑', 'p' => 'kùnhuò', 'm' => 'khốn hoặc, bối rối', 'pos' => '名词,形容词', 'ex' => ['感到困惑。Cảm thấy bối rối.', '成长中的困惑。Bối rối trong trưởng thành.']],
            ['w' => '压力', 'p' => 'yālì', 'm' => 'áp lực', 'pos' => '名词', 'ex' => ['学习压力。Áp lực học tập.', '减轻压力。Giảm áp lực.']],
            ['w' => '焦虑', 'p' => 'jiāolǜ', 'm' => 'lo lắng', 'pos' => '形容词', 'ex' => ['感到焦虑。Cảm thấy lo lắng.', '焦虑的情绪。Tâm trạng lo lắng.']],
            ['w' => '调整', 'p' => 'tiáozhěng', 'm' => 'điều chỉnh', 'pos' => '动词', 'ex' => ['调整心态。Điều chỉnh tâm thái.', '调整计划。Điều chỉnh kế hoạch.']],
            ['w' => '心态', 'p' => 'xīntài', 'm' => 'tâm thái', 'pos' => '名词', 'ex' => ['积极的心态。Tâm thái tích cực.', '调整心态。Điều chỉnh tâm thái.']],
            ['w' => '挫折', 'p' => 'cuòzhé', 'm' => 'thất bại, khó khăn', 'pos' => '名词', 'ex' => ['遇到挫折。Gặp khó khăn.', '面对挫折。Đối mặt khó khăn.']],
            ['w' => '态度', 'p' => 'tàidù', 'm' => 'thái độ', 'pos' => '名词', 'ex' => ['积极的态度。Thái độ tích cực.', '学习态度。Thái độ học tập.']],
