    49 => [
        'title' => 'Bài 49: 沟通与交流 - Giao tiếp và trao đổi',
        'text' => '沟通是人与人之间建立关系的桥梁。无论是在工作中还是在生活中，良好的沟通能力都非常重要。有效的沟通不仅能让别人理解你的想法，也能帮助你理解别人。很多矛盾的产生都是因为沟通不畅造成的。在沟通中，倾听和表达同样重要。有些人只注重说自己的想法，却不愿意听别人的意见，这样的沟通很难达到好的效果。倾听时要注意力集中，不要随意打断别人。表达时要清晰明了，使用恰当的语言。非语言沟通也很重要，面部表情、眼神、手势、姿态都能传递信息。有时候，一个微笑比很多话都更有力量。跨文化沟通越来越受到关注。不同国家、不同文化背景的人交流时，要注意文化差异。比如在中国，直接拒绝别人可能不太礼貌，人们往往会说"我考虑考虑"来表示委婉的拒绝。学会沟通是终身学习的课程。好的沟通可以拉近人与人之间的距离，增进感情，减少误解。我希望自己能成为一个善于沟通的人，用语言架起友谊的桥梁。',
        'dialogues' => [
            ['who' => '妈妈', 'cn' => '小明，你怎么和同学吵架了？', 'vi' => 'Tiểu Minh, sao con lại cãi nhau với bạn?'],
            ['who' => '王小明', 'cn' => '他误会我的意思了，我本来是想帮他。', 'vi' => 'Bạn ấy hiểu lầm ý con, con vốn định giúp bạn ấy.'],
            ['who' => '妈妈', 'cn' => '那你有没有好好解释？', 'vi' => 'Thế con có giải thích rõ ràng không?'],
            ['who' => '王小明', 'cn' => '我解释了，但是他不想听。', 'vi' => 'Con giải thích rồi, nhưng bạn ấy không muốn nghe.'],
            ['who' => '妈妈', 'cn' => '沟通是双方的，你也要听听他怎么想。', 'vi' => 'Giao tiếp là hai phía, con cũng phải nghe bạn ấy nghĩ gì.'],
            ['who' => '王小明', 'cn' => '我太着急了，没有好好听他说。', 'vi' => 'Con quá vội, không nghe bạn ấy nói kỹ.'],
            ['who' => '妈妈', 'cn' => '下次遇到问题先冷静，等双方都平静了再沟通。', 'vi' => 'Lần sau gặp vấn đề trước hãy bình tĩnh, đợi hai bên đều bình tĩnh rồi hãy giao tiếp.'],
            ['who' => '王小明', 'cn' => '我知道了，沟通需要耐心。', 'vi' => 'Con biết rồi, giao tiếp cần kiên nhẫn.'],
        ],
        'grammar' => [
            ['point' => 'Cấu trúc 无论...都... (bất luận...đều...)', 'explain' => '无论...都... nghĩa "bất kể...đều...". 无论 + tình huống bất kỳ + 都 + kết quả. Trong bài: 无论是在工作中还是在生活中，良好的沟通能力都非常重要 (Bất kể trong công việc hay trong cuộc sống, năng lực giao tiếp tốt đều rất quan trọng). 都 đặt trước tính từ hoặc động từ. 无论 có thể thay bằng 不管.', 'examples' => ['无论多忙，他都坚持运动。Bất kể bận thế nào, anh ấy đều kiên trì vận động.', '无论你是谁，都要遵守规则。Bất kể bạn là ai, đều phải tuân thủ quy tắc.']],
            ['point' => 'Cấu trúc 不仅...也... (không chỉ...cũng...)', 'explain' => 'Cấu trúc bổ sung. 不仅 + A + 也 + B. Bài: 良好的沟通能力不仅能让别人理解你的想法，也能帮助你理解别人 (Năng lực giao tiếp tốt không chỉ giúp người khác hiểu suy nghĩ của bạn, cũng giúp bạn hiểu người khác). 不仅 có thể đặt trước chủ ngữ hoặc sau chủ ngữ.', 'examples' => ['沟通不仅能表达自己，也能理解他人。Giao tiếp không chỉ biểu đạt bản thân, cũng hiểu người khác.', '他不仅学习好，也乐于助人。Anh ấy không chỉ học giỏi, cũng sẵn lòng giúp người.']],
            ['point' => 'Cấu trúc 越...越... (càng...càng...)', 'explain' => '越...越... chỉ mức độ tăng dần. Cấu trúc: 越 + A + 越 + B, A và B đều có thể là tính từ hoặc động từ. Ý nói A thay đổi thì B thay đổi tương ứng. Bài: 有时候直接拒绝可能不太礼貌 (không trực tiếp dùng 越...越..., nhưng nguyên lý tương tự). Dùng 越来越... cho thay đổi theo thời gian.', 'examples' => ['越说越清楚。Càng nói càng rõ.', '越沟通越理解。Càng giao tiếp càng hiểu.', '越多练习越好。Càng luyện tập nhiều càng tốt.']],
        ],
        'pronunciation' => ['focus' => 'ai/ei distinction', 'drill' => ['bái', 'bēi', 'pái', 'péi', 'mái', 'méi', 'dài', 'děi']],
