            ['w' => '桥梁', 'p' => 'qiáoliáng', 'm' => 'cầu nối', 'pos' => '名词', 'ex' => ['沟通的桥梁。Cầu nối giao tiếp.', '建立桥梁。Xây dựng cầu nối.']],
            ['w' => '能力', 'p' => 'nénglì', 'm' => 'năng lực', 'pos' => '名词', 'ex' => ['沟通能力。Năng lực giao tiếp.', '学习能力。Năng lực học tập.']],
            ['w' => '有效', 'p' => 'yǒuxiào', 'm' => 'hữu hiệu, có hiệu quả', 'pos' => '形容词', 'ex' => ['有效沟通。Giao tiếp hiệu quả.', '有效的方法。Phương pháp hiệu quả.']],
            ['w' => '矛盾', 'p' => 'máodùn', 'm' => 'mâu thuẫn', 'pos' => '名词', 'ex' => ['产生矛盾。Nảy sinh mâu thuẫn.', '解决矛盾。Giải quyết mâu thuẫn.']],
            ['w' => '倾听', 'p' => 'qīngtīng', 'm' => 'lắng nghe', 'pos' => '动词', 'ex' => ['学会倾听。Học cách lắng nghe.', '认真倾听。Chăm chú lắng nghe.']],
            ['w' => '表达', 'p' => 'biǎodá', 'm' => 'biểu đạt', 'pos' => '动词', 'ex' => ['表达想法。Biểu đạt suy nghĩ.', '语言表达。Biểu đạt ngôn ngữ.']],
            ['w' => '打断', 'p' => 'dǎduàn', 'm' => 'cắt ngang, ngắt lời', 'pos' => '动词', 'ex' => ['不要打断别人。Đừng ngắt lời người khác.', '打断谈话。Cắt ngang cuộc trò chuyện.']],
            ['w' => '眼神', 'p' => 'yǎnshén', 'm' => 'ánh mắt', 'pos' => '名词', 'ex' => ['眼神交流。Giao tiếp bằng mắt.', '温柔的眼神。Ánh mắt dịu dàng.']],
            ['w' => '手势', 'p' => 'shǒushì', 'm' => 'thủ thế, cử chỉ tay', 'pos' => '名词', 'ex' => ['打手势。Ra hiệu bằng tay.', '手势语言。Ngôn ngữ cử chỉ tay.']],
            ['w' => '姿态', 'p' => 'zītài', 'm' => 'tư thái', 'pos' => '名词', 'ex' => ['身体姿态。Tư thái cơ thể.', '积极的姿态。Tư thái tích cực.']],
