    50 => [
        'title' => 'Bài 50: 人生与哲学 - Nhân sinh và triết lý',
        'text' => '人生是一场旅行，每个人都有自己的路要走。在人生的道路上，我们会遇到各种各样的人和事，有欢笑也有泪水，有成功也有失败。这些都是人生宝贵的经历。关于人生的意义，不同的哲学家有不同的看法。有人认为人生的意义在于追求幸福，有人认为在于实现自我价值。我觉得人生的意义没有标准答案，每个人的选择不同，意义也就不同。在人生的不同阶段，我们的追求也会变化。年轻时我们追求知识和梦想；中年时我们追求事业和家庭；老年时我们追求内心的平静和满足。最重要的是要认真过好每一天，珍惜身边的人和事。我们常常为了追求远大的目标而忽略了眼前的美好。其实幸福并不遥远，它就藏在日常生活的点点滴滴中。和家人一起吃顿饭、和朋友聊聊天、看到路边的花开，这些都是幸福。人生短暂的，我们应该珍惜时间，做自己想做的事，爱自己想爱的人。不要等到失去了才后悔。用积极的态度面对生活，用感恩的心去感受世界，这样的人生才有意义。',
        'dialogues' => [
            ['who' => '王小明', 'cn' => '爷爷，您觉得人生的意义是什么？', 'vi' => 'Ông ơi, ông thấy ý nghĩa cuộc đời là gì?'],
            ['who' => '爷爷', 'cn' => '这个问题很深奥啊。爷爷活了一辈子，觉得意义就是好好活着。', 'vi' => 'Câu hỏi này sâu xa quá. Ông sống cả đời, thấy ý nghĩa là sống tốt.'],
            ['who' => '王小明', 'cn' => '好好活着是什么意思？', 'vi' => 'Sống tốt là ý gì?'],
            ['who' => '爷爷', 'cn' => '做自己喜欢的事，爱身边的人，不留下遗憾。', 'vi' => 'Làm việc mình thích, yêu người bên cạnh, không để lại hối tiếc.'],
            ['who' => '王小明', 'cn' => '那您觉得幸福是什么？', 'vi' => 'Thế ông thấy hạnh phúc là gì?'],
            ['who' => '爷爷', 'cn' => '幸福就在平常的生活里，比如现在和孙子聊天就很幸福。', 'vi' => 'Hạnh phúc ở trong cuộc sống thường ngày, như bây giờ nói chuyện với cháu là hạnh phúc.'],
            ['who' => '王小明', 'cn' => '我明白了，幸福其实很简单。', 'vi' => 'Cháu hiểu rồi, hạnh phúc thực ra rất đơn giản.'],
            ['who' => '爷爷', 'cn' => '对，珍惜拥有的，感恩生活的，就是幸福的。', 'vi' => 'Đúng, trân quý những gì có, cảm ơn cuộc sống, chính là hạnh phúc.'],
        ],
        'grammar' => [
            ['point' => 'Cấu trúc 有的人...有的人... (có người...có người...)', 'explain' => 'Cấu trúc liệt kê các nhóm người với sự lựa chọn khác nhau. 有的人 + A + 有的人 + B. Bài: 有人认为人生的意义在于追求幸福，有人认为在于实现自我价值 (Có người cho rằng ý nghĩa cuộc đời ở việc theo đuổi hạnh phúc, có người cho rằng ở việc thực hiện giá trị bản thân). Có thể dùng 有的 + danh từ.', 'examples' => ['有的人喜欢热闹，有的人喜欢安静。Có người thích náo nhiệt, có người thích yên tĩnh.', '有的追求财富，有的追求精神。Có người theo đuổi tài phú, có người theo đuổi tinh thần.']],
            ['point' => 'Cấu trúc 不要等到...才... (đừng đợi đến...mới...)', 'explain' => 'Cấu trúc khuyên răn, "đừng đợi đến lúc A mới B". Bài: 不要等到失去了才后悔 (Đừng đợi đến lúc mất đi mới hối tiếc). 等到 + mốc thời gian/điều kiện + 才 + hành động. 才 nhấn mạnh hành động xảy ra muộn.', 'examples' => ['不要等到生病了才注意健康。Đừng đợi đến lúc ốm mới chú ý sức khỏe.', '不要等到毕业了才后悔没好好学习。Đừng đợi đến lúc tốt nghiệp mới hối hận không học tốt.']],
            ['point' => 'Cấu trúc 在...中 (ở trong...)', 'explain' => '在 + danh từ + 中, chỉ phạm vi hoặc hoàn cảnh. Bài: 在人生的道路上 (Trên đường đời), 在人生的不同阶段 (Ở giai đoạn khác nhau của cuộc đời). 在...中 có thể chỉ vị trí, phạm vi, hoặc tình huống. Các biến thể: 在...上, 在...里, 在...方面.', 'examples' => ['在学习中进步。Tiến bộ trong học tập.', '在困难中成长。Trưởng thành trong khó khăn.']],
        ],
        'pronunciation' => ['focus' => 'ia/ie distinction', 'drill' => ['jiā', 'jiē', 'qià', 'qiè', 'xiá', 'xié', 'yā', 'yē']],
        'vocab' => [
