            ['w' => '哲学', 'p' => 'zhéxué', 'm' => 'triết học', 'pos' => '名词', 'ex' => ['人生哲学。Triết lý nhân sinh.', '哲学家。Nhà triết học.']],
            ['w' => '经历', 'p' => 'jīnglì', 'm' => 'trải qua, kinh lịch', 'pos' => '动词,名词', 'ex' => ['宝贵的经历。Kinh lịch quý báu.', '经历了很多。Đã trải qua nhiều.']],
            ['w' => '意义', 'p' => 'yìyì', 'm' => 'ý nghĩa', 'pos' => '名词', 'ex' => ['人生的意义。Ý nghĩa cuộc đời.', '有意义的工作。Công việc có ý nghĩa.']],
            ['w' => '标准', 'p' => 'biāozhǔn', 'm' => 'tiêu chuẩn', 'pos' => '名词', 'ex' => ['标准答案。Đáp án tiêu chuẩn.', '没有标准。Không có tiêu chuẩn.']],
            ['w' => '阶段', 'p' => 'jiēduàn', 'm' => 'giai đoạn', 'pos' => '名词', 'ex' => ['不同阶段。Giai đoạn khác nhau.', '学习阶段。Giai đoạn học tập.']],
            ['w' => '追求', 'p' => 'zhuīqiú', 'm' => 'theo đuổi', 'pos' => '动词', 'ex' => ['追求幸福。Theo đuổi hạnh phúc.', '追求梦想。Theo đuổi ước mơ.']],
            ['w' => '珍惜', 'p' => 'zhēnxī', 'm' => 'trân quý', 'pos' => '动词', 'ex' => ['珍惜时间。Trân quý thời gian.', '珍惜身边的人。Trân quý người bên cạnh.']],
            ['w' => '短暂', 'p' => 'duǎnzàn', 'm' => 'ngắn ngủi', 'pos' => '形容词', 'ex' => ['人生短暂。Cuộc đời ngắn ngủi.', '短暂的时光。Khoảng thời gian ngắn ngủi.']],
            ['w' => '平凡', 'p' => 'píngfán', 'm' => 'bình phàm', 'pos' => '形容词', 'ex' => ['平凡的生活。Cuộc sống bình phàm.', '平凡中见伟大。Thấy vĩ đại trong bình phàm.']],
            ['w' => '感恩', 'p' => 'gǎn\'ēn', 'm' => 'cảm ơn, tri ân', 'pos' => '动词', 'ex' => ['感恩的心。Tấm lòng tri ân.', '感恩生活。Cảm ơn cuộc sống.']],
