    51 => [
        'title' => 'Bài 51: 全球化与文化融合 - Toàn cầu hóa và giao thoa văn hóa',
        'text' => '全球化是当今世界的一个重要趋势。随着交通和通信技术的发展，各国之间的交流越来越频繁。商品、资本、人才和信息在全球范围内流动，让世界变得更加紧密。全球化给经济发展带来了巨大的机遇。企业可以在全球范围内配置资源，消费者可以享受到来自世界各地的产品和服务。同时，全球化也促进了文化的交流与融合。在中国，我们可以吃到意大利的比萨、日本的寿司、美国的汉堡。同样，中国的美食、武术、中医也在世界各地受到欢迎。越来越多的外国人学习中文，对中国文化产生浓厚的兴趣。然而，全球化也带来了一些挑战。文化同质化的问题引起了人们的关注，一些地方的传统文化和语言面临着消失的危险。此外，全球经济波动也会相互影响，一个国家的经济危机可能波及到其他国家。我认为全球化是不可逆转的趋势，我们要以开放的心态面对全球化。一方面要吸收其他文化的优秀成果，另一方面也要保护好自己的文化传统。在融合中保持特色，在交流中共同发展。',
        'dialogues' => [
            ['who' => '大卫', 'cn' => '王小明，你觉得全球化对中国有什么影响？', 'vi' => 'Vương Tiểu Minh, cậu thấy toàn cầu hóa có ảnh hưởng gì đến Trung Quốc?'],
            ['who' => '王小明', 'cn' => '我觉得影响很大，比如现在很多外国品牌在中国都很流行。', 'vi' => 'Tớ thấy ảnh hưởng lớn, ví dụ nhiều thương hiệu nước ngoài rất thịnh hành ở Trung Quốc.'],
            ['who' => '大卫', 'cn' => '中国文化在国外也越来越受欢迎。', 'vi' => 'Văn hóa Trung Quốc ở nước ngoài cũng càng ngày càng được ưa chuộng.'],
            ['who' => '王小明', 'cn' => '是的，我听说很多外国人喜欢中国功夫和中医。', 'vi' => 'Phải, tớ nghe nói nhiều người nước ngoài thích công phu và y học Trung Quốc.'],
            ['who' => '大卫', 'cn' => '不过全球化会不会让各国文化变得一样？', 'vi' => 'Nhưng toàn cầu hóa có làm văn hóa các nước trở nên giống nhau không?'],
            ['who' => '王小明', 'cn' => '这也是很多人担心的问题，所以我们要保护好自己的传统文化。', 'vi' => 'Đây cũng là vấn đề nhiều người lo lắng, nên chúng ta phải bảo vệ văn hóa truyền thống của mình.'],
            ['who' => '大卫', 'cn' => '你说得对，在开放的同时也要保持自己的特色。', 'vi' => 'Cậu nói đúng, trong mở cửa cũng phải giữ đặc sắc của mình.'],
        ],
        'grammar' => [
            ['point' => 'Cấu trúc 随着... (cùng với...)', 'explain' => '随着 + danh từ + động từ, chỉ sự thay đổi đồng thời. Bài: 随着交通和通信技术的发展 (Cùng với sự phát triển của kỹ thuật giao thông và truyền thông). 随着 thường đứng ở đầu câu, giới thiệu bối cảnh. Có thể dùng 随着...的... để nối danh từ.', 'examples' => ['随着经济发展，生活水平提高。Cùng với phát triển kinh tế, trình độ sống nâng cao.', '随着时间推移，一切都会变化。Cùng với thời gian trôi qua, mọi thứ sẽ thay đổi.']],
            ['point' => 'Cấu trúc 一方面...另一方面... (một mặt...mặt khác...)', 'explain' => '一方面 + A + 另一方面 + B. Dùng để trình bày hai khía cạnh của một vấn đề. Bài: 一方面要吸收其他文化的优秀成果，另一方面也要保护好自己的文化传统 (Một mặt phải hấp thụ thành quả ưu tú của các nền văn hóa khác, mặt khác cũng phải bảo vệ truyền thống văn hóa của mình).', 'examples' => ['一方面要学习，另一方面要休息。Một mặt phải học, mặt khác phải nghỉ ngơi.', '一方面发展经济，另一方面保护环境。Một mặt phát triển kinh tế, mặt khác bảo vệ môi trường.']],
            ['point' => 'Cấu trúc 随着...的+ danh từ (cùng với sự...của...)', 'explain' => '随着...的 + danh từ hóa. Biến thể của 随着. 随着 + (danh từ + 的) + danh từ. Tạo cụm danh từ phức tạp hơn. Bài: 随着交通和通信技术的发展 (sự phát triển), 随着全球化的发展 (sự phát triển của toàn cầu hóa).', 'examples' => ['随着社会的发展。Cùng với sự phát triển của xã hội.', '随着科技的进步。Cùng với sự tiến bộ của khoa học kỹ thuật.']],
        ],
        'pronunciation' => ['focus' => 'eng/ong distinction', 'drill' => ['fēng', 'fēng', 'dēng', 'dōng', 'téng', 'téng', 'néng', 'nóng']],
