    53 => [
        'title' => 'Bài 53: 媒体与信息 - Truyền thông và thông tin',
        'text' => '在信息时代，媒体的作用越来越重要。每天我们都会通过报纸、电视、网络等各种渠道获取大量的信息。媒体不仅传递新闻，还影响着人们的观念和态度。然而信息爆炸的时代也带来了问题。虚假信息、标题党、谣言在网络中泛滥，让人难辨真假。有时候一条假新闻在几分钟内就能传遍全网，造成很大的负面影响。因此培养媒介素养变得非常重要。学会辨别信息的真伪，不盲目相信和传播未经证实的消息，这是每一个现代公民应该具备的能力。传统媒体如报纸和电视有自己的编辑流程，相对来说比较可靠。而社交媒体上的信息则需要我们自己去判断。在转发信息之前，最好先核实来源是否可靠，内容是否合理。同时也要注意保护个人隐私，不随意在网络上泄露自己的信息。网络不是法外之地，每个人都要对自己的言行负责。我们应该在享受信息便利的同时，保持独立思考，不随波逐流。',
        'dialogues' => [
            ['who' => '王小明', 'cn' => '小红，你看到那条关于学校停课的消息了吗？', 'vi' => 'Tiểu Hồng, cậu thấy tin tức về trường nghỉ học kia chưa?'],
            ['who' => '小红', 'cn' => '看到了，但是我觉得不太可信，还没有官方通知。', 'vi' => 'Thấy rồi, nhưng tớ thấy không đáng tin, còn chưa có thông báo chính thức.'],
            ['who' => '王小明', 'cn' => '但是很多群都在转发，应该是真的吧？', 'vi' => 'Nhưng nhiều nhóm đang chuyển tiếp, chắc là thật chứ?'],
            ['who' => '小红', 'cn' => '不能因为很多人转发就相信，要先核实消息来源。', 'vi' => 'Không thể vì nhiều người chuyển tiếp mà tin, phải kiểm tra nguồn tin trước.'],
            ['who' => '王小明', 'cn' => '你说得对，我去学校官网看看有没有通知。', 'vi' => 'Cậu nói đúng, tớ đi xem website chính thức của trường có thông báo không.'],
            ['who' => '小红', 'cn' => '如果没有官方消息，就不要随便转发。', 'vi' => 'Nếu không có tin chính thức, thì đừng tùy tiện chuyển tiếp.'],
            ['who' => '王小明', 'cn' => '嗯，看来提高辨别信息的能力很重要。', 'vi' => 'Ừm, xem ra nâng cao năng lực phân biệt thông tin rất quan trọng.'],
        ],
        'grammar' => [
            ['point' => 'Cấu trúc 不仅...还... (không chỉ...mà còn...)', 'explain' => '媒体不仅传递新闻，还影响着人们的观念和态度. (Truyền thông không chỉ truyền đạt tin tức, mà còn ảnh hưởng quan niệm và thái độ của con người). 不仅 đứng trước A, 还 đứng trước B để bổ sung.', 'examples' => ['他不仅是我的同学，还是我的好朋友。Anh ấy không chỉ là bạn học, mà còn là bạn tốt của tôi.', '网络不仅方便，还改变了我们的生活。Mạng không chỉ tiện lợi, mà còn thay đổi cuộc sống chúng ta.']],
            ['point' => 'Cấu trúc 在...之前 (trước khi...)', 'explain' => '在 + thời gian/hành động + 之前, nghĩa "trước khi". Bài: 在转发信息之前 (Trước khi chuyển tiếp thông tin). 之前 đặt sau mốc thời gian hoặc hành động. Tương phản với 之后 (sau khi).', 'examples' => ['在出门之前检查一下。Kiểm tra trước khi ra ngoài.', '在做决定之前要慎重。Phải thận trọng trước khi quyết định.']],
            ['point' => 'Cấu trúc 对...负责 (chịu trách nhiệm về...)', 'explain' => '对 + đối tượng + 负责. Bài: 每个人都要对自己的言行负责 (Mỗi người đều phải chịu trách nhiệm về lời nói và hành động của mình). 对...负责 là cụm động từ cố định.', 'examples' => ['对自己的行为负责。Chịu trách nhiệm về hành vi của mình.', '对家庭负责。Chịu trách nhiệm với gia đình.']],
        ],
        'pronunciation' => ['focus' => 'ou/uo contrast', 'drill' => ['dōu', 'duō', 'gōu', 'guō', 'hòu', 'huò', 'zǒu', 'zuǒ']],
        'vocab' => [
            ['w' => '媒体', 'p' => 'méitǐ', 'm' => 'truyền thông', 'pos' => '名词', 'ex' => ['社交媒体。Truyền thông xã hội.', '新闻媒体。Truyền thông tin tức.']],
            ['w' => '信息', 'p' => 'xìnxī', 'm' => 'thông tin', 'pos' => '名词', 'ex' => ['信息时代。Thời đại thông tin.', '获取信息。Thu thập thông tin.']],
            ['w' => '渠道', 'p' => 'qúdào', 'm' => 'kênh, đường', 'pos' => '名词', 'ex' => ['信息渠道。Kênh thông tin.', '销售渠道。Kênh bán hàng.']],
            ['w' => '爆炸', 'p' => 'bàozhà', 'm' => 'bùng nổ', 'pos' => '动词', 'ex' => ['信息爆炸。Bùng nổ thông tin.', '人口爆炸。Bùng nổ dân số.']],
            ['w' => '虚假', 'p' => 'xūjiǎ', 'm' => 'hư giả, giả mạo', 'pos' => '形容词', 'ex' => ['虚假信息。Thông tin giả mạo.', '虚假广告。Quảng cáo giả mạo.']],
            ['w' => '谣言', 'p' => 'yáoyán', 'm' => 'lời đồn, tin đồn', 'pos' => '名词', 'ex' => ['传播谣言。Truyền bá tin đồn.', '辟谣。Dập tin đồn.']],
            ['w' => '泛滥', 'p' => 'fànlàn', 'm' => 'tràn lan', 'pos' => '动词', 'ex' => ['谣言泛滥。Tin đồn tràn lan.', '信息泛滥。Thông tin tràn lan.']],
            ['w' => '辨别', 'p' => 'biànbié', 'm' => 'phân biệt', 'pos' => '动词', 'ex' => ['辨别真伪。Phân biệt thật giả.', '辨别方向。Phân biệt phương hướng.']],
            ['w' => '真伪', 'p' => 'zhēnwěi', 'm' => 'thật giả', 'pos' => '名词', 'ex' => ['辨别真伪。Phân biệt thật giả.', '难辨真伪。Khó phân thật giả.']],
            ['w' => '媒介', 'p' => 'méijiè', 'm' => 'môi giới, phương tiện', 'pos' => '名词', 'ex' => ['媒介素养。Tố chất truyền thông.', '传播媒介。Phương tiện truyền thông.']],
            ['w' => '素养', 'p' => 'sùyǎng', 'm' => 'tố chất', 'pos' => '名词', 'ex' => ['媒介素养。Tố chất truyền thông.', '文化素养。Tố chất văn hóa.']],
            ['w' => '核实', 'p' => 'héshí', 'm' => 'kiểm tra, xác minh', 'pos' => '动词', 'ex' => ['核实消息。Xác minh tin tức.', '核实数据。Kiểm tra dữ liệu.']],
            ['w' => '来源', 'p' => 'láiyuán', 'm' => 'nguồn gốc', 'pos' => '名词', 'ex' => ['信息来源。Nguồn gốc thông tin.', '消息来源。Nguồn tin.']],
            ['w' => '泄露', 'p' => 'xièlòu', 'm' => 'rò rỉ, tiết lộ', 'pos' => '动词', 'ex' => ['泄露隐私。Tiết lộ riêng tư.', '信息泄露。Rò rỉ thông tin.']],
            ['w' => '随波逐流', 'p' => 'suí bō zhú liú', 'm' => 'theo dòng, a dua', 'pos' => '成语', 'ex' => ['不要随波逐流。Đừng a dua theo đám đông.', '保持独立不随波逐流。Giữ độc lập không a dua.']],
        ],
        'exercises' => [
            'fill_blank' => [
                ['s' => '媒____的作用越来越重要。', 'a' => '体'],
                ['s' => '不____传递新闻，还影响观念。', 'a' => '仅'],
