    54 => [
        'title' => 'Bài 54: 法律与道德 - Pháp luật và đạo đức',
        'text' => '法律和道德是维护社会秩序的两个重要手段。法律是由国家制定和执行的规则，违反法律会受到相应的惩罚。道德则是一种社会认同的行为准则，依靠人们的内心信念和社会的舆论来维持。法律和道德既有联系又有区别。法律是最低限度的道德，道德是更高层次的要求。一个行为可能不违法，但不一定符合道德。比如在公共场合大声喧哗，虽然不犯法，但却是不道德的行为。作为公民，我们要知法守法，同时也要有良好的道德修养。在日常生活中，我们要遵守交通规则、诚实守信、尊老爱幼。这些既是法律规定，也是道德要求。近年来，中国在法治建设方面取得了很大的进步。法律法规越来越完善，人们的法律意识也在不断提高。当权益受到侵害时，越来越多的人懂得用法律武器保护自己。但是仅仅依靠法律是不够的。法律不能约束所有的行为，很多方面需要靠道德来自我约束。所以我们要提高自身的道德修养，做一个遵纪守法的好公民。只有法律和道德共同发挥作用，社会才能更加和谐有序。',
        'dialogues' => [
            ['who' => '王小明', 'cn' => '爸爸，法律和道德有什么区别？', 'vi' => 'Bố ơi, pháp luật và đạo đức có gì khác nhau?'],
            ['who' => '爸爸', 'cn' => '法律是必须遵守的，违反法律会受到惩罚。道德是靠自觉的。', 'vi' => 'Pháp luật là phải tuân theo, vi phạm luật sẽ bị phạt. Đạo đức là dựa vào tự giác.'],
            ['who' => '王小明', 'cn' => '如果一个人不违法但做了不道德的事呢？', 'vi' => 'Nếu một người không vi phạm pháp luật nhưng làm việc trái đạo đức thì sao?'],
            ['who' => '爸爸', 'cn' => '会受到社会舆论的谴责，大家会批评他。', 'vi' => 'Sẽ bị dư luận xã hội lên án, mọi người sẽ phê bình anh ta.'],
            ['who' => '王小明', 'cn' => '我懂了，法律是底线，道德是更高的要求。', 'vi' => 'Con hiểu rồi, pháp luật là giới hạn dưới, đạo đức là yêu cầu cao hơn.'],
            ['who' => '爸爸', 'cn' => '对，所以我们既要学法守法，也要提高道德修养。', 'vi' => 'Đúng, vậy nên chúng ta vừa phải học luật tuân thủ luật, vừa phải nâng cao tu dưỡng đạo đức.'],
            ['who' => '王小明', 'cn' => '我会努力做一个遵纪守法的好公民。', 'vi' => 'Con sẽ cố gắng làm một công dân tốt tuân thủ pháp luật.'],
        ],
        'grammar' => [
            ['point' => 'Cấu trúc 由...来... (do...đảm nhận / do...mà...)', 'explain' => '由 + người/cơ quan + động từ, chỉ người thực hiện hành động. Bài: 法律是由国家制定和执行的 (Pháp luật là do nhà nước ban hành và chấp hành). 由 thường dùng trong văn phong trang trọng để chỉ tác nhân.', 'examples' => ['会议由校长主持。Cuộc họp do hiệu trưởng chủ trì.', '这个问题由你来解决。Vấn đề này do bạn giải quyết.']],
