    55 => [
        'title' => 'Bài 55: 城市与乡村 - Thành thị và nông thôn',
        'text' => '城市和乡村是中国两种不同的生活方式。城市生活节奏快，机会多，教育资源丰富，医疗条件好。很多人为了追求更好的发展机会，选择到城市工作和生活。北京、上海、广州这样的大城市每年都吸引着大量的年轻人。然而城市也面临着交通拥堵、房价高昂、环境污染等问题。相比之下，乡村生活节奏慢，空气新鲜，自然环境好。乡村的人们生活简单，邻里关系密切，互相帮助。但是乡村的教育和医疗条件相对落后，就业机会也比较少。近年来，中国政府提出了乡村振兴战略，希望缩小城乡差距。许多年轻人也开始回到乡村创业，发展乡村旅游、电商和特色农业。我认为城市和乡村各有优势，关键是根据自己的需求和喜好做出选择。有些人喜欢城市的热闹和便利，有些人喜欢乡村的宁静和自然。理想的状态是城乡协调发展，让人们无论在城市还是在乡村都能享受到美好的生活。',
        'dialogues' => [
            ['who' => '王小明', 'cn' => '爷爷，您喜欢住在城市还是乡村？', 'vi' => 'Ông ơi, ông thích ở thành phố hay nông thôn?'],
            ['who' => '爷爷', 'cn' => '爷爷在乡村住了一辈子，习惯了那里的安静和新鲜空气。', 'vi' => 'Ông ở nông thôn cả đời, quen với sự yên tĩnh và không khí trong lành ở đó.'],
            ['who' => '王小明', 'cn' => '但是乡村没有城市那么方便，买东西、看病都不太方便。', 'vi' => 'Nhưng nông thôn không tiện bằng thành phố, mua đồ, khám bệnh đều không tiện lắm.'],
            ['who' => '爷爷', 'cn' => '是啊，所以现在乡村也在发展，条件越来越好了。', 'vi' => 'Phải đấy, nên bây giờ nông thôn cũng đang phát triển, điều kiện càng ngày càng tốt.'],
            ['who' => '王小明', 'cn' => '您觉得未来乡村会变得像城市一样吗？', 'vi' => 'Ông thấy tương lai nông thôn sẽ trở nên giống thành phố không?'],
            ['who' => '爷爷', 'cn' => '应该有乡村的特色，不能完全和城市一样。', 'vi' => 'Nên có đặc sắc nông thôn, không thể hoàn toàn giống thành phố.'],
            ['who' => '王小明', 'cn' => '我同意，乡村应该有乡村的美好。', 'vi' => 'Cháu đồng ý, nông thôn nên có vẻ đẹp riêng của nông thôn.'],
        ],
        'grammar' => [
            ['point' => 'Cấu trúc 相比之下 (so sánh mà nói)', 'explain' => '相比之下 là cụm trạng ngữ đứng đầu câu, nghĩa "so sánh mà nói". Dùng để chuyển ý so sánh giữa hai đối tượng. Bài: 相比之下，乡村生活节奏慢 (So sánh mà nói, nhịp sống nông thôn chậm). Có thể thay bằng 相比之下，...更...', 'examples' => ['城市压力大，相比之下，乡村更轻松。Thành phố áp lực lớn, so sánh mà nói, nông thôn nhẹ nhàng hơn.', '相比之下，我更喜欢自然风景。So sánh mà nói, tôi thích phong cảnh tự nhiên hơn.']],
            ['point' => 'Cấu trúc 无论...都... (bất kể...đều...)', 'explain' => '无论 + A + 还是 + B + 都 + kết quả. Bài: 无论在城市还是在乡村都能享受到美好的生活 (Bất kể ở thành phố hay nông thôn đều có thể tận hưởng cuộc sống tốt đẹp). 无论...都... nhấn mạnh kết quả không thay đổi.', 'examples' => ['无论在城市还是乡村，都要好好生活。Bất kể ở thành phố hay nông thôn, đều phải sống tốt.', '无论做什么工作，都要认真。Bất kể làm gì, đều phải nghiêm túc.']],
            ['point' => 'Cấu trúc 根据... (căn cứ vào...)', 'explain' => '根据 + danh từ, nghĩa "căn cứ vào, dựa vào". Bài: 根据自己需求和喜好做出选择 (Căn cứ vào nhu cầu và sở thích của mình mà đưa ra lựa chọn). 根据 thường đứng đầu câu hoặc sau chủ ngữ.', 'examples' => ['根据自己的兴趣选择专业。Căn cứ vào sở thích chọn ngành.', '根据天气预报决定是否出门。Căn cứ vào dự báo thời tiết quyết định có ra ngoài không.']],
