    56 => [
        'title' => 'Bài 56: 自然资源与可持续发展 - Tài nguyên thiên nhiên và phát triển bền vững',
        'text' => '地球上的自然资源是有限的。随着人口增长和经济发展，人类对自然资源的需求越来越大。煤、石油、天然气等不可再生资源正在快速消耗，水资源短缺和森林面积减少也成为全球性问题。如果我们不改变目前的生产和生活方式，未来的子孙后代将面临资源枯竭的困境。可持续发展理念正是在这样的背景下产生的。可持续发展要求我们既要满足当代人的需求，又不能损害后代人满足需求的能力。这意味着我们必须合理利用资源，发展循环经济，推广绿色能源。每个人都可以为可持续发展做出贡献。节约用水、减少浪费、使用可再生能源、绿色出行，这些看似小的行为，汇聚起来就是巨大的力量。很多国家已经制定了碳中和目标，中国也承诺在2030年前实现碳达峰、2060年前实现碳中和。这需要全社会共同努力。作为一个普通人，我也要从自己做起。少用一次性物品，多乘坐公共交通，随手关灯关水。我相信只要每个人都行动起来，我们的地球会更加美好。',
        'dialogues' => [
            ['who' => '王小明', 'cn' => '老师，什么是碳达峰和碳中和？', 'vi' => 'Thưa thầy, carbon đỉnh và trung hòa carbon là gì?'],
            ['who' => '老师', 'cn' => '碳达峰是指碳排放达到最高点后开始下降，碳中和是指排放的碳和吸收的碳相抵消。', 'vi' => 'Carbon đỉnh là lượng carbon thải đạt đỉnh rồi bắt đầu giảm, trung hòa carbon là lượng thải và lượng hấp thụ bù trừ.'],
            ['who' => '王小明', 'cn' => '要做到碳中和是不是很难？', 'vi' => 'Để đạt trung hòa carbon có khó không?'],
            ['who' => '老师', 'cn' => '确实不容易，需要全社会一起努力。', 'vi' => 'Quả thật không dễ, cần toàn xã hội cùng nỗ lực.'],
            ['who' => '王小明', 'cn' => '我能做些什么呢？', 'vi' => 'Em có thể làm gì?'],
            ['who' => '老师', 'cn' => '节约用电、多坐公交、减少浪费，这些都是贡献。', 'vi' => 'Tiết kiệm điện, đi xe buýt, giảm lãng phí, những điều này đều là đóng góp.'],
            ['who' => '王小明', 'cn' => '我明白了，从小事做起。', 'vi' => 'Em hiểu rồi, bắt đầu từ việc nhỏ.'],
        ],
        'grammar' => [
            ['point' => 'Cấu trúc 随着... (cùng với...)', 'explain' => '随着 + sự thay đổi + chủ ngữ + động từ. Bài: 随着人口增长和经济发展，人类对自然资源的需求越来越大 (Cùng với dân số tăng và kinh tế phát triển, nhu cầu của con người về tài nguyên thiên nhiên càng ngày càng lớn). 随着 đặt đầu câu.', 'examples' => ['随着社会发展，生活水平提高。Cùng với xã hội phát triển, trình độ sống nâng cao.', '随着科技发展，生活方式改变。Cùng với khoa học phát triển, phương thức sống thay đổi.']],
            ['point' => 'Cấu trúc 既...又... (vừa...vừa...)', 'explain' => '满足当代人的需求，又 + không + 损害后代人满足需求的能力. Cấu trúc: 既 A 又 B. Bài: 既要满足当代人的需求，又不能损害后代人满足需求的能力 (Vừa phải đáp ứng nhu cầu của người đương thời, lại vừa không được tổn hại năng lực đáp ứng nhu cầu của thế hệ tương lai).', 'examples' => ['既要发展经济，又要保护环境。Vừa phát triển kinh tế, vừa bảo vệ môi trường.', '既要利用资源，又要节约资源。Vừa sử dụng tài nguyên, vừa tiết kiệm tài nguyên.']],
            ['point' => 'Cấu trúc 从...做起 (bắt đầu từ...)', 'explain' => '从 + việc gì + 做起, nghĩa "bắt đầu từ việc gì". Bài: 从我做起，少用一次性物品 (Bắt đầu từ tôi, dùng ít đồ dùng một lần). Cấu trúc thường dùng trong khẩu hiệu và lời kêu gọi.', 'examples' => ['从身边的小事做起。Bắt đầu từ việc nhỏ bên cạnh.', '从节约用水做起。Bắt đầu từ tiết kiệm nước.']],
        ],
        'pronunciation' => ['focus' => 'in/ing contrast review', 'drill' => ['jìn', 'jìng', 'pín', 'píng', 'xīn', 'xīng', 'mín', 'míng']],
        'vocab' => [
