            ['w' => '有限', 'p' => 'yǒuxiàn', 'm' => 'hữu hạn', 'pos' => '形容词', 'ex' => ['资源有限。Tài nguyên hữu hạn.', '时间有限。Thời gian hữu hạn.']],
            ['w' => '消耗', 'p' => 'xiāohào', 'm' => 'tiêu hao', 'pos' => '动词', 'ex' => ['资源消耗。Tiêu hao tài nguyên.', '消耗能源。Tiêu hao năng lượng.']],
            ['w' => '枯竭', 'p' => 'kūjié', 'm' => 'cạn kiệt', 'pos' => '动词', 'ex' => ['资源枯竭。Tài nguyên cạn kiệt.', '能源枯竭。Năng lượng cạn kiệt.']],
