            ['w' => '理念', 'p' => 'lǐniàn', 'm' => 'lý niệm', 'pos' => '名词', 'ex' => ['发展理念。Lý niệm phát triển.', '环保理念。Lý niệm bảo vệ môi trường.']],
            ['w' => '循环', 'p' => 'xúnhuán', 'm' => 'tuần hoàn', 'pos' => '动词,名词', 'ex' => ['循环经济。Kinh tế tuần hoàn.', '良性循环。Tuần hoàn lành tính.']],
