            ['w' => '可再生', 'p' => 'kězàishēng', 'm' => 'có thể tái sinh', 'pos' => '形容词', 'ex' => ['可再生能源。Năng lượng tái sinh.', '可再生资源。Tài nguyên tái sinh.']],
