            ['w' => '碳达峰', 'p' => 'tàndáfēng', 'm' => 'carbon đỉnh', 'pos' => '名词', 'ex' => ['碳达峰目标。Mục tiêu carbon đỉnh.', '实现碳达峰。Thực hiện carbon đỉnh.']],
