    57 => [
        'title' => 'Bài 57: 家庭与社会 - Gia đình và xã hội',
        'text' => '家庭是社会的基本单位。一个和谐的家庭不仅能让家庭成员感到温暖和幸福，也是社会稳定和发展的基础。在中国传统文化中，家庭观念非常重要。"家和万事兴"这句话就说明了家庭和睦的重要性。随着社会的发展，家庭结构也发生了变化。以前是几代人住在一起的大家庭，现在越来越多的是父母和孩子组成的小家庭。独生子女政策虽然已经调整，但对家庭结构的影响仍然存在。现代社会中，家庭面临着许多挑战。工作压力大、生活节奏快，导致很多人没有足够的时间陪伴家人。代沟问题也越来越突出，年轻人和父母之间的观念差异有时会导致矛盾。尽管如此，家庭依然是我们最重要的依靠。无论在外面遇到什么困难，回到家总会感到安心。我们应该珍惜与家人在一起的时光，多沟通、多理解、多包容。作为子女，要孝敬父母；作为父母，要关爱子女。每个家庭成员都承担着自己的责任。只有每个家庭都和睦幸福，社会才能更加和谐稳定。',
        'dialogues' => [
            ['who' => '王小明', 'cn' => '妈妈，您觉得家庭最重要的是什么？', 'vi' => 'Mẹ ơi, mẹ thấy gia đình quan trọng nhất là gì?'],
            ['who' => '妈妈', 'cn' => '最重要的是和睦，一家人互相理解、互相关心。', 'vi' => 'Quan trọng nhất là hòa thuận, cả nhà hiểu nhau, quan tâm nhau.'],
            ['who' => '王小明', 'cn' => '现在很多人工作忙，没有时间陪家人怎么办？', 'vi' => 'Bây giờ nhiều người bận làm, không có thời gian ở bên gia đình thì sao?'],
            ['who' => '妈妈', 'cn' => '虽然忙，但要尽量抽出时间，哪怕是一起吃顿饭也好。', 'vi' => 'Tuy bận, nhưng phải cố gắng dành thời gian, dù chỉ là cùng nhau ăn bữa cơm cũng tốt.'],
            ['who' => '王小明', 'cn' => '我和奶奶有时候想法不一样，这正常吗？', 'vi' => 'Con và bà đôi khi suy nghĩ khác nhau, điều này bình thường không?'],
            ['who' => '妈妈', 'cn' => '这叫代沟，是很正常的，要多沟通互相理解。', 'vi' => 'Đây gọi là thế hệ khác biệt, rất bình thường, phải giao tiếp nhiều hiểu nhau.'],
            ['who' => '王小明', 'cn' => '我懂了，家庭需要每个人都用心经营。', 'vi' => 'Con hiểu rồi, gia đình cần mỗi người đều dùng tâm vun đắp.'],
        ],
        'grammar' => [
            ['point' => 'Cấu trúc 随着... (cùng với...)', 'explain' => 'Với sự thay đổi của xã hội, kết cấu gia đình cũng thay đổi. 随着社会的发展，家庭结构也发生了变化 (Cùng với sự phát triển của xã hội, cấu trúc gia đình cũng đã thay đổi).', 'examples' => ['随着时代变化，家庭观念也在变化。Cùng với thời đại thay đổi, quan niệm gia đình cũng thay đổi.', '随着生活水平提高，家庭生活质量也在提高。Cùng với trình độ sống nâng cao, chất lượng cuộc sống gia đình cũng nâng cao.']],
            ['point' => 'Cấu trúc 尽管...依然... (mặc dù...vẫn...)', 'explain' => '尽管 + A + 依然 + B, nghĩa "mặc dù A, nhưng vẫn B". Bài: 尽管有挑战，家庭依然是我们最重要的依靠 (Mặc dù có thách thức, gia đình vẫn là chỗ dựa quan trọng nhất của chúng ta). 尽管 thay thế cho 虽然 với sắc thái mạnh hơn.', 'examples' => ['尽管工作很忙，他依然陪家人。Mặc dù công việc rất bận, anh ấy vẫn ở bên gia đình.', '尽管有代沟，依然可以沟通。Mặc dù có thế hệ khác biệt, vẫn có thể giao tiếp.']],
            ['point' => 'Cấu trúc 只有...才... (chỉ có...mới...)', 'explain' => '只有每个家庭都和睦幸福，社会才能更加和谐稳定 (Chỉ có mỗi gia đình đều hòa thuận hạnh phúc, xã hội mới càng hài hòa ổn định). Điều kiện tiên quyết.', 'examples' => ['只有家庭和睦，社会才能稳定。Chỉ có gia đình hòa thuận, xã hội mới ổn định.', '只有用心经营，家庭才能幸福。Chỉ có dùng tâm vun đắp, gia đình mới hạnh phúc.']],
        ],
        'pronunciation' => ['focus' => 'e/er distinction', 'drill' => ['é', 'ér', 'zhè', 'zhèr', 'gē', 'gēr', 'hé', 'hér']],
        'vocab' => [
