            ['w' => '观念', 'p' => 'guānniàn', 'm' => 'quan niệm', 'pos' => '名词', 'ex' => ['家庭观念。Quan niệm gia đình.', '传统观念。Quan niệm truyền thống.']],
            ['w' => '结构', 'p' => 'jiégòu', 'm' => 'kết cấu', 'pos' => '名词', 'ex' => ['家庭结构。Kết cấu gia đình.', '社会结构。Kết cấu xã hội.']],
