            ['w' => '孝敬', 'p' => 'xiàojìng', 'm' => 'hiếu kính', 'pos' => '动词', 'ex' => ['孝敬父母。Hiếu kính cha mẹ.', '孝敬老人。Hiếu kính người già.']],
            ['w' => '关爱', 'p' => 'guān\'ài', 'm' => 'quan ái', 'pos' => '动词', 'ex' => ['关爱子女。Quan ái con cái.', '互相关爱。Quan tâm yêu thương nhau.']],
