    58 => [
        'title' => 'Bài 58: 艺术审美 - Thẩm mỹ nghệ thuật',
        'text' => '艺术审美是人类精神生活的重要组成部分。审美能力不是天生的，而是可以通过学习和培养来提高的。美存在于生活的方方面面，关键在于我们是否有一双发现美的眼睛。在自然界中，日出日落、花开花谢、山川河流都是美的。在艺术作品中，一幅画、一首歌、一支舞蹈也能给人美的享受。不同的人对美有不同的理解。有人喜欢气势磅礴的山水画，有人喜欢细腻传神的人物画；有人喜欢激昂的交响乐，有人喜欢温柔的民谣。审美没有绝对的标准，每个人都可以有自己的偏好。学习艺术是提高审美能力的好方法。很多人在工作之余学习画画、弹琴、摄影，不仅丰富了生活，也提高了审美趣味。中国传统美学讲究"意境"，强调作品要给人留下想象的空间。比如中国画中的留白，看似空白，实则有无穷的韵味。我认为培养审美能力对生活很有帮助。有良好审美的人，在穿衣搭配、家居装饰、生活安排上都会更加讲究。审美让生活更加精致美好。让我们一起在生活中发现美、感受美、创造美。',
        'dialogues' => [
            ['who' => '王小明', 'cn' => '小红，你觉得什么是美？', 'vi' => 'Tiểu Hồng, cậu thấy thế nào là đẹp?'],
            ['who' => '小红', 'cn' => '美是一种感觉，每个人对美的理解不一样。', 'vi' => 'Đẹp là một cảm giác, mỗi người có cách hiểu về đẹp khác nhau.'],
            ['who' => '王小明', 'cn' => '那你觉得怎么提高审美能力？', 'vi' => 'Thế cậu thấy làm thế nào nâng cao năng lực thẩm mỹ?'],
            ['who' => '小红', 'cn' => '多接触美好的事物，比如看画展、听音乐会、读好书。', 'vi' => 'Tiếp xúc nhiều với sự vật đẹp, như xem triển lãm tranh, nghe hòa nhạc, đọc sách hay.'],
            ['who' => '王小明', 'cn' => '中国画里的留白是什么意思？', 'vi' => 'Lưu bạch trong tranh Trung Quốc có nghĩa là gì?'],
            ['who' => '小红', 'cn' => '留白就是留下空白，给观众想象的空间。', 'vi' => 'Lưu bạch là để lại khoảng trống, cho khán giả không gian tưởng tượng.'],
            ['who' => '王小明', 'cn' => '原来审美这么有意思！', 'vi' => 'Thì ra thẩm mỹ thú vị như vậy!'],
        ],
        'grammar' => [
            ['point' => 'Cấu trúc 在于... (nằm ở...)', 'explain' => '在于 + danh từ/mệnh đề, nghĩa "nằm ở chỗ". Bài: 美存在于生活的方方面面，关键在于我们是否有一双发现美的眼睛 (Cái đẹp tồn tại ở mọi mặt cuộc sống, mấu chốt nằm ở chỗ chúng ta có đôi mắt phát hiện cái đẹp hay không). 在于 dùng để chỉ ra bản chất hoặc điểm mấu chốt.', 'examples' => ['幸福在于心态。Hạnh phúc nằm ở tâm thái.', '关键在于努力。Mấu chốt nằm ở cố gắng.']],
            ['point' => 'Cấu trúc 不仅...也... (không chỉ...cũng...)', 'explain' => '不仅丰富了生活，也提高了审美趣味 (Không chỉ phong phú cuộc sống, cũng nâng cao thú vị thẩm mỹ). 不仅 A 也 B: bổ sung thông tin.', 'examples' => ['学音乐不仅有趣，也提高审美。Học nhạc không chỉ thú vị, cũng nâng cao thẩm mỹ.', '看书不仅增长知识，也陶冶情操。Đọc sách không chỉ tăng tri thức, cũng trau dồi tình cảm.']],
            ['point' => 'Cấu trúc 越...越... (càng...càng...)', 'explain' => '越 + A + 越 + B. Chỉ mức độ A tăng thì B tăng tương ứng. Bài không dùng trực tiếp nhưng có thể hiểu: càng tiếp xúc với nghệ thuật, càng nâng cao thẩm mỹ. Cấu trúc phổ biến trong so sánh mức độ.', 'examples' => ['越看越喜欢。Càng xem càng thích.', '越学越有興趣。Càng học càng có hứng thú.']],
        ],
        'pronunciation' => ['focus' => 'u/ü contrast', 'drill' => ['lù', 'lǜ', 'nǔ', 'nǚ', 'dù', 'dù', 'tú', 'tú']],
        'vocab' => [
            ['w' => '审美', 'p' => 'shěnměi', 'm' => 'thẩm mỹ', 'pos' => '名词', 'ex' => ['审美能力。Năng lực thẩm mỹ.', '审美趣味。Thú vị thẩm mỹ.']],
            ['w' => '天生', 'p' => 'tiānshēng', 'm' => 'thiên sinh, bẩm sinh', 'pos' => '形容词', 'ex' => ['不是天生的。Không phải bẩm sinh.', '天生就会。Bẩm sinh đã biết.']],
            ['w' => '培养', 'p' => 'péiyǎng', 'm' => 'bồi dưỡng', 'pos' => '动词', 'ex' => ['培养审美。Bồi dưỡng thẩm mỹ.', '培养兴趣。Bồi dưỡng sở thích.']],
            ['w' => '发现', 'p' => 'fāxiàn', 'm' => 'phát hiện', 'pos' => '动词', 'ex' => ['发现美。Phát hiện cái đẹp.', '发现机会。Phát hiện cơ hội.']],
            ['w' => '陶醉', 'p' => 'táozuì', 'm' => 'đắm chìm, say mê', 'pos' => '动词', 'ex' => ['陶醉在音乐中。Đắm chìm trong âm nhạc.', '令人陶醉。Khiến người say mê.']],
            ['w' => '气势', 'p' => 'qìshì', 'm' => 'khí thế', 'pos' => '名词', 'ex' => ['气势磅礴。Khí thế bàng bạc.', '有气势。Có khí thế.']],
            ['w' => '磅礴', 'p' => 'pángbó', 'm' => 'bàng bạc', 'pos' => '形容词', 'ex' => ['气势磅礴。Khí thế bàng bạc.', '磅礴的气势。Khí thế hùng vĩ.']],
            ['w' => '细腻', 'p' => 'xìnì', 'm' => 'tinh tế, tỉ mỉ', 'pos' => '形容词', 'ex' => ['细腻的描写。Miêu tả tinh tế.', '画风细腻。Phong cách hội họa tinh tế.']],
            ['w' => '传神', 'p' => 'chuánshén', 'm' => 'truyền thần, sống động', 'pos' => '形容词', 'ex' => ['画得传神。Vẽ truyền thần.', '传神的人物。Nhân vật sống động.']],
            ['w' => '激昂', 'p' => 'jī\'áng', 'm' => 'kích động, hào hứng', 'pos' => '形容词', 'ex' => ['激昂的音乐。Âm nhạc hào hứng.', '情绪激昂。Cảm xúc dâng trào.']],
