    59 => [
        'title' => 'Bài 59: 人生智慧 - Trí tuệ nhân sinh',
        'text' => '人生是一本厚重的书，每个人都在用自己的经历书写自己的故事。在漫长的人生旅途中，我们会积累许多经验和智慧。古人说："活到老，学到老。"学习不仅仅是学生时代的事情，而是贯穿一生的过程。保持好奇心和学习的热忱，是保持年轻的秘诀。除了学习，健康也是人生最重要的财富之一。没有健康的身体，再多的财富和成就都没有意义。所以要学会照顾自己，保持规律的作息，适当的运动和健康的饮食。人际关系也是人生幸福的重要因素。与人为善、懂得感恩、学会宽容，这些品质能让我们获得真正的友谊和爱。人生不可能一帆风顺，每个人都会遇到困难和挫折。面对困难时，要保持乐观的态度。正如一位哲人所说："黑暗中总有一线光明。"困难是暂时的，只要坚持就一定能看到希望。人生的意义不在于取得了多少成就，而在于是否活出了真实的自己。不要为了迎合别人而改变自己，也不要为了追求物质而忽略了精神的富足。听从内心的声音，做自己真正想做的事，和自己真正喜欢的人在一起。这样的人生才是充实而有意义的。',
        'dialogues' => [
            ['who' => '爷爷', 'cn' => '小明，你觉得怎么样的人生才算成功？', 'vi' => 'Tiểu Minh, con thấy thế nào là cuộc đời thành công?'],
            ['who' => '王小明', 'cn' => '我觉得成功就是实现自己的梦想。', 'vi' => 'Con thấy thành công là thực hiện được ước mơ của mình.'],
            ['who' => '爷爷', 'cn' => '那如果梦想没有实现呢？', 'vi' => 'Thế nếu ước mơ không thực hiện được thì sao?'],
            ['who' => '王小明', 'cn' => '这……那我也不知道了。', 'vi' => 'Cái này... thế con cũng không biết nữa.'],
            ['who' => '爷爷', 'cn' => '爷爷觉得成功不是达到什么目标，而是这一生做了自己想做的事，没有太多遗憾。', 'vi' => 'Ông thấy thành công không phải đạt được mục tiêu gì, mà là cả đời làm điều mình muốn, không nhiều tiếc nuối.'],
            ['who' => '王小明', 'cn' => '那就是要听从内心的声音？', 'vi' => 'Vậy là phải nghe theo tiếng nói nội tâm?'],
