        'grammar' => [
            ['point' => 'Cấu trúc 除了...也... (ngoài...cũng...)', 'explain' => '除了 + A + 也 + B. Bài: 除了学习，健康也是人生最重要的财富之一 (Ngoài học tập, sức khỏe cũng là một trong những tài sản quan trọng nhất cuộc đời).', 'examples' => ['除了工作，也要享受生活。Ngoài công việc, cũng phải tận hưởng cuộc sống.', '除了物质，精神也很重要。Ngoài vật chất, tinh thần cũng rất quan trọng.']],
            ['point' => 'Cấu trúc 哪怕...也... (dù...cũng...)', 'explain' => '哪怕 + A + 也 + B, nghĩa "dù cho A, cũng B". Bài: 困难是暂时的，哪怕再大的困难，也一定能看到希望 (Khó khăn là tạm thời, dù cho khó khăn lớn thế nào, cũng nhất định thấy hy vọng). 哪怕 nhấn mạnh giả định cực đoan.', 'examples' => ['哪怕再难，也要坚持。Dù khó thế nào, cũng phải kiên trì.', '哪怕失败，也不要放弃。Dù thất bại, cũng đừng từ bỏ.']],
